export default JSON.parse('{"work":{"id":"shiji","schoolId":"histories","title":"史記","genreStrategy":"parallel","sourceNote":"版本來源自通行本及校勘附記。","chapterIds":["shiji_ch-1","shiji_ch-2"],"totalChars":8637},"chapters":[{"id":"shiji_ch-1","workId":"shiji","order":1,"title":"五帝本紀","difficulty":4,"estimatedMinutes":16,"passageIds":["shiji_ch-1_p-1","shiji_ch-1_p-2","shiji_ch-1_p-3","shiji_ch-1_p-4","shiji_ch-1_p-5","shiji_ch-1_p-6","shiji_ch-1_p-7","shiji_ch-1_p-8","shiji_ch-1_p-9","shiji_ch-1_p-10","shiji_ch-1_p-11","shiji_ch-1_p-12","shiji_ch-1_p-13","shiji_ch-1_p-14","shiji_ch-1_p-15","shiji_ch-1_p-16","shiji_ch-1_p-17","shiji_ch-1_p-18","shiji_ch-1_p-19","shiji_ch-1_p-20","shiji_ch-1_p-21","shiji_ch-1_p-22","shiji_ch-1_p-23","shiji_ch-1_p-24","shiji_ch-1_p-25","shiji_ch-1_p-26","shiji_ch-1_p-27","shiji_ch-1_p-28","shiji_ch-1_p-29"],"tags":[]},{"id":"shiji_ch-2","workId":"shiji","order":2,"title":"夏本紀","difficulty":4,"estimatedMinutes":14,"passageIds":["shiji_ch-2_p-1","shiji_ch-2_p-2","shiji_ch-2_p-3","shiji_ch-2_p-4","shiji_ch-2_p-5","shiji_ch-2_p-6","shiji_ch-2_p-7","shiji_ch-2_p-8","shiji_ch-2_p-9","shiji_ch-2_p-10","shiji_ch-2_p-11","shiji_ch-2_p-12","shiji_ch-2_p-13","shiji_ch-2_p-14","shiji_ch-2_p-15","shiji_ch-2_p-16","shiji_ch-2_p-17","shiji_ch-2_p-18","shiji_ch-2_p-19","shiji_ch-2_p-20","shiji_ch-2_p-21","shiji_ch-2_p-22","shiji_ch-2_p-23","shiji_ch-2_p-24","shiji_ch-2_p-25","shiji_ch-2_p-26","shiji_ch-2_p-27","shiji_ch-2_p-28","shiji_ch-2_p-29","shiji_ch-2_p-30","shiji_ch-2_p-31","shiji_ch-2_p-32","shiji_ch-2_p-33","shiji_ch-2_p-34","shiji_ch-2_p-35"],"tags":[]}],"passages":[{"id":"shiji_ch-1_p-1","chapterId":"shiji_ch-1","order":1,"canonicalText":"黃帝者，少典之子，姓公孫，名曰軒轅。生而神靈，弱而能言，幼而徇齊，長而敦敏，成而聰明。","sentenceIds":["shiji_ch-1_p-1_s-1","shiji_ch-1_p-1_s-2"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"}]},{"id":"shiji_ch-1_p-2","chapterId":"shiji_ch-1","order":2,"canonicalText":"軒轅之時，神農氏世衰。諸侯相侵伐，暴虐百姓，而神農氏弗能征。於是軒轅乃習用干戈，以征不享，諸侯咸來賓從。而蚩尤最為暴，莫能伐。炎帝欲侵陵諸侯，諸侯咸歸軒轅。軒轅乃修德振兵，治五氣，藝五種，撫萬民，度四方，教熊羆貔貅貙虎，以與炎帝戰於阪泉之野。三戰然後得其志。蚩尤作亂，不用帝命。於是黃帝乃徵師諸侯，與蚩尤戰於涿鹿之野，遂禽殺蚩尤。而諸侯咸尊軒轅為天子，代神農氏，是為黃帝。天下有不順者，黃帝從而征之，平者去之，披山通道，未嘗寧居。","sentenceIds":["shiji_ch-1_p-2_s-1","shiji_ch-1_p-2_s-2","shiji_ch-1_p-2_s-3","shiji_ch-1_p-2_s-4","shiji_ch-1_p-2_s-5","shiji_ch-1_p-2_s-6","shiji_ch-1_p-2_s-7","shiji_ch-1_p-2_s-8","shiji_ch-1_p-2_s-9","shiji_ch-1_p-2_s-10","shiji_ch-1_p-2_s-11"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"}]},{"id":"shiji_ch-1_p-3","chapterId":"shiji_ch-1","order":3,"canonicalText":"東至于海，登丸山，及岱宗。西至于空桐，登雞頭。南至于江，登熊、湘。北逐葷粥，合符釜山，而邑于涿鹿之阿。遷徙往來無常處，以師兵為營衛。官名皆以雲命，為雲師。置左右大監，監于萬國。萬國和，而鬼神山川封禪與為多焉。獲寶鼎，迎日推筴。舉風后、力牧、常先、大鴻以治民。順天地之紀，幽明之占，死生之說，存亡之難。時播百穀草木，淳化鳥獸蟲蛾，旁羅日月星辰水波土石金玉，勞勤心力耳目，節用水火材物。有土德之瑞，故號黃帝。","sentenceIds":["shiji_ch-1_p-3_s-1","shiji_ch-1_p-3_s-2","shiji_ch-1_p-3_s-3","shiji_ch-1_p-3_s-4","shiji_ch-1_p-3_s-5","shiji_ch-1_p-3_s-6","shiji_ch-1_p-3_s-7","shiji_ch-1_p-3_s-8","shiji_ch-1_p-3_s-9","shiji_ch-1_p-3_s-10","shiji_ch-1_p-3_s-11","shiji_ch-1_p-3_s-12","shiji_ch-1_p-3_s-13"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"}]},{"id":"shiji_ch-1_p-4","chapterId":"shiji_ch-1","order":4,"canonicalText":"黃帝二十五子，其得姓者十四人。","sentenceIds":["shiji_ch-1_p-4_s-1"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"}]},{"id":"shiji_ch-1_p-5","chapterId":"shiji_ch-1","order":5,"canonicalText":"黃帝居于軒轅之丘，而娶于西陵之女，是為嫘祖為黃帝正妃，生二子，其後皆有天下：其一曰玄囂，是為青陽，青陽降居江水；其二曰昌意，降居若水。昌意娶蜀山氏女，曰昌仆，生高陽，高陽有聖德焉。黃帝崩，葬橋山。其孫昌意之子高陽立，是為帝顓頊也。","sentenceIds":["shiji_ch-1_p-5_s-1","shiji_ch-1_p-5_s-2","shiji_ch-1_p-5_s-3","shiji_ch-1_p-5_s-4","shiji_ch-1_p-5_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"}]},{"id":"shiji_ch-1_p-6","chapterId":"shiji_ch-1","order":6,"canonicalText":"帝顓頊高陽者，黃帝之孫而昌意之子也。靜淵以有謀，疏通而知事；養材以任地，載時以象天，依鬼神以制義，治氣以教化，絜誠以祭祀。北至于幽陵，南至于交阯，西至于流沙，東至于蟠木。動靜之物，大小之神，日月所照，莫不砥屬。","sentenceIds":["shiji_ch-1_p-6_s-1","shiji_ch-1_p-6_s-2","shiji_ch-1_p-6_s-3","shiji_ch-1_p-6_s-4","shiji_ch-1_p-6_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"}]},{"id":"shiji_ch-1_p-7","chapterId":"shiji_ch-1","order":7,"canonicalText":"帝顓頊生子曰窮蟬。顓頊崩，而玄囂之孫高辛立，是為帝嚳。","sentenceIds":["shiji_ch-1_p-7_s-1","shiji_ch-1_p-7_s-2"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"}]},{"id":"shiji_ch-1_p-8","chapterId":"shiji_ch-1","order":8,"canonicalText":"帝嚳高辛者，黃帝之曾孫也。高辛父曰蟜極，蟜極父曰玄囂，玄囂父曰黃帝。自玄囂與蟜極皆不得在位，至高辛即帝位。高辛於顓頊為族子。","sentenceIds":["shiji_ch-1_p-8_s-1","shiji_ch-1_p-8_s-2","shiji_ch-1_p-8_s-3","shiji_ch-1_p-8_s-4"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"}]},{"id":"shiji_ch-1_p-9","chapterId":"shiji_ch-1","order":9,"canonicalText":"高辛生而神靈，自言其名。普施利物，不於其身。聰以知遠，明以察微。順天之義，知民之急。仁而威，惠而信，修身而天下服。取地之財而節用之，撫教萬民而利誨之，歷日月而迎送之，明鬼神而敬事之。其色郁郁，其德嶷嶷。其動也時，其服也士。帝嚳溉執中而遍天下，日月所照，風雨所至，莫不從服。","sentenceIds":["shiji_ch-1_p-9_s-1","shiji_ch-1_p-9_s-2","shiji_ch-1_p-9_s-3","shiji_ch-1_p-9_s-4","shiji_ch-1_p-9_s-5","shiji_ch-1_p-9_s-6","shiji_ch-1_p-9_s-7","shiji_ch-1_p-9_s-8","shiji_ch-1_p-9_s-9"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"}]},{"id":"shiji_ch-1_p-10","chapterId":"shiji_ch-1","order":10,"canonicalText":"帝嚳娶陳鋒氏女，生放勛。娶娵訾氏女，生摯。帝嚳崩，而摯代立。帝摯立，不善（崩），而弟放勛立，是為帝堯。","sentenceIds":["shiji_ch-1_p-10_s-1","shiji_ch-1_p-10_s-2","shiji_ch-1_p-10_s-3","shiji_ch-1_p-10_s-4"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"}]},{"id":"shiji_ch-1_p-11","chapterId":"shiji_ch-1","order":11,"canonicalText":"帝堯者，放勛。其仁如天，其知如神。就之如日，望之如雲。富而不驕，貴而不舒。黃收純衣，彤車乘白馬。能明馴德，以親九族。九族既睦，便章百姓。百姓昭明，合和萬國。","sentenceIds":["shiji_ch-1_p-11_s-1","shiji_ch-1_p-11_s-2","shiji_ch-1_p-11_s-3","shiji_ch-1_p-11_s-4","shiji_ch-1_p-11_s-5","shiji_ch-1_p-11_s-6","shiji_ch-1_p-11_s-7","shiji_ch-1_p-11_s-8"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"}]},{"id":"shiji_ch-1_p-12","chapterId":"shiji_ch-1","order":12,"canonicalText":"乃命羲、和，敬順昊天，數法日月星辰，敬授民時。分命羲仲，居郁夷，曰暘谷。敬道日出，便程東作。日中，星鳥，以殷中春。其民析，鳥獸字微。申命羲叔，居南交。便程南為，敬致。日永，星火，以正中夏。其民因，鳥獸希革。申命和仲，居西土，曰昧谷。敬道日入，便程西成。夜中，星虛，以正中秋。其民夷易，鳥獸毛毨。申命和叔；居北方，曰幽都。便在伏物。日短，星昴，以正中冬。其民燠，鳥獸氄毛。歲三百六十六日，以閏月正四時。信飭百官，眾功皆興。","sentenceIds":["shiji_ch-1_p-12_s-1","shiji_ch-1_p-12_s-2","shiji_ch-1_p-12_s-3","shiji_ch-1_p-12_s-4","shiji_ch-1_p-12_s-5","shiji_ch-1_p-12_s-6","shiji_ch-1_p-12_s-7","shiji_ch-1_p-12_s-8","shiji_ch-1_p-12_s-9","shiji_ch-1_p-12_s-10","shiji_ch-1_p-12_s-11","shiji_ch-1_p-12_s-12","shiji_ch-1_p-12_s-13","shiji_ch-1_p-12_s-14","shiji_ch-1_p-12_s-15","shiji_ch-1_p-12_s-16","shiji_ch-1_p-12_s-17","shiji_ch-1_p-12_s-18","shiji_ch-1_p-12_s-19","shiji_ch-1_p-12_s-20"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"}]},{"id":"shiji_ch-1_p-13","chapterId":"shiji_ch-1","order":13,"canonicalText":"堯曰：「誰可順此事？」放齊曰：「嗣子丹朱開明。」堯曰：「吁！頑凶，不用。」堯又曰：「誰可者？」讙兜曰：「共工旁聚布功，可用。」堯曰：「共工善言，其用僻，似恭漫天，不可。」堯又曰：「嗟，四嶽，湯湯洪水滔天，浩浩懷山襄陵，下民其憂，有能使治者？」皆曰鯀可。堯曰：「鯀負命毀族，不可。」嶽曰：「異哉，試不可用而已。」堯於是聽嶽用鯀。九歲，功用不成。","sentenceIds":["shiji_ch-1_p-13_s-1","shiji_ch-1_p-13_s-2","shiji_ch-1_p-13_s-3","shiji_ch-1_p-13_s-4","shiji_ch-1_p-13_s-5","shiji_ch-1_p-13_s-6","shiji_ch-1_p-13_s-7","shiji_ch-1_p-13_s-8","shiji_ch-1_p-13_s-9","shiji_ch-1_p-13_s-10","shiji_ch-1_p-13_s-11","shiji_ch-1_p-13_s-12","shiji_ch-1_p-13_s-13"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"}]},{"id":"shiji_ch-1_p-14","chapterId":"shiji_ch-1","order":14,"canonicalText":"堯曰：「嗟！四嶽：朕在位七十載，汝能庸命，踐朕位？」嶽應曰：「鄙德忝帝位。」堯曰：「悉舉貴戚及疏遠隱匿者。」眾皆言於堯曰：「有矜在民閒，曰虞舜。」堯曰：「然，朕聞之。其何如？」嶽曰：「盲者子。父頑，母嚚，弟傲，能和以孝，烝烝治，不至姦。」堯曰：「吾其試哉。」於是堯妻之二女，觀其德於二女。舜飭下二女於媯汭，如婦禮。","sentenceIds":["shiji_ch-1_p-14_s-1","shiji_ch-1_p-14_s-2","shiji_ch-1_p-14_s-3","shiji_ch-1_p-14_s-4","shiji_ch-1_p-14_s-5","shiji_ch-1_p-14_s-6","shiji_ch-1_p-14_s-7","shiji_ch-1_p-14_s-8","shiji_ch-1_p-14_s-9","shiji_ch-1_p-14_s-10","shiji_ch-1_p-14_s-11","shiji_ch-1_p-14_s-12"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"}]},{"id":"shiji_ch-1_p-15","chapterId":"shiji_ch-1","order":15,"canonicalText":"堯善之，乃使舜慎和五典，五典能從。乃遍入百官，百官時序。賓於四門，四門穆穆，諸侯遠方賓客皆敬。堯使舜入山林川澤，暴風雷雨，舜行不迷。堯以為聖，召舜曰：「女謀事至而言可績，三年矣。女登帝位。」舜讓於德不懌。正月上日，舜受終於文祖。文祖者，堯大祖也。","sentenceIds":["shiji_ch-1_p-15_s-1","shiji_ch-1_p-15_s-2","shiji_ch-1_p-15_s-3","shiji_ch-1_p-15_s-4","shiji_ch-1_p-15_s-5","shiji_ch-1_p-15_s-6","shiji_ch-1_p-15_s-7","shiji_ch-1_p-15_s-8","shiji_ch-1_p-15_s-9"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"}]},{"id":"shiji_ch-1_p-16","chapterId":"shiji_ch-1","order":16,"canonicalText":"於是帝堯老，命舜攝行天子之政，以觀天命。舜乃在璿璣玉衡，以齊七政。遂類于上帝，禋于六宗，望于山川，辯于群神。揖五瑞，擇吉月日，見四嶽諸牧，班瑞。歲二月，東巡狩，至於岱宗，祡，望秩於山川。遂見東方君長，合時月正日，同律度量衡，修五禮五玉三帛二生一死為摯，如五器，卒乃復。五月，南巡狩；八月，西巡狩；十一月，北巡狩：皆如初。歸，至于祖禰廟，用特牛禮。五歲一巡狩，群后四朝。遍告以言，明試以功，車服以庸。肇十有二州，決川。象以典刑，流宥五刑，鞭作官刑，撲作教刑，金作贖刑。眚災過，赦；怙終賊，刑。欽哉，欽哉，惟刑之靜哉！","sentenceIds":["shiji_ch-1_p-16_s-1","shiji_ch-1_p-16_s-2","shiji_ch-1_p-16_s-3","shiji_ch-1_p-16_s-4","shiji_ch-1_p-16_s-5","shiji_ch-1_p-16_s-6","shiji_ch-1_p-16_s-7","shiji_ch-1_p-16_s-8","shiji_ch-1_p-16_s-9","shiji_ch-1_p-16_s-10","shiji_ch-1_p-16_s-11","shiji_ch-1_p-16_s-12","shiji_ch-1_p-16_s-13","shiji_ch-1_p-16_s-14","shiji_ch-1_p-16_s-15","shiji_ch-1_p-16_s-16","shiji_ch-1_p-16_s-17"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"}]},{"id":"shiji_ch-1_p-17","chapterId":"shiji_ch-1","order":17,"canonicalText":"讙兜進言共工，堯曰不可而試之工師，共工果淫辟。四嶽舉鯀治鴻水，堯以為不可，嶽彊請試之，試之而無功，故百姓不便。三苗在江淮、荊州數為亂。於是舜歸而言於帝，請流共工於幽陵，以變北狄；放讙兜於崇山，以變南蠻；遷三苗於三危，以變西戎；殛鯀於羽山，以變東夷：四罪而天下咸服。","sentenceIds":["shiji_ch-1_p-17_s-1","shiji_ch-1_p-17_s-2","shiji_ch-1_p-17_s-3","shiji_ch-1_p-17_s-4","shiji_ch-1_p-17_s-5","shiji_ch-1_p-17_s-6","shiji_ch-1_p-17_s-7"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"}]},{"id":"shiji_ch-1_p-18","chapterId":"shiji_ch-1","order":18,"canonicalText":"堯立七十年得舜，二十年而老，令舜攝行天子之政，薦之於天。堯辟位凡二十八年而崩。百姓悲哀，如喪父母。三年，四方莫舉樂，以思堯。堯知子丹朱之不肖，不足授天下，於是乃權授舜。授舜，則天下得其利而丹朱病；授丹朱，則天下病而丹朱得其利。堯曰：「終不以天下之病而利一人」，而卒授舜以天下。堯崩，三年之喪畢，舜讓辟丹朱於南河之南。諸侯朝覲者不之丹朱而之舜，獄訟者不之丹朱而之舜，謳歌者不謳歌丹朱而謳歌舜。舜曰：「天也」，夫而後之中國踐天子位焉，是為帝舜。","sentenceIds":["shiji_ch-1_p-18_s-1","shiji_ch-1_p-18_s-2","shiji_ch-1_p-18_s-3","shiji_ch-1_p-18_s-4","shiji_ch-1_p-18_s-5","shiji_ch-1_p-18_s-6","shiji_ch-1_p-18_s-7","shiji_ch-1_p-18_s-8","shiji_ch-1_p-18_s-9","shiji_ch-1_p-18_s-10","shiji_ch-1_p-18_s-11"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"}]},{"id":"shiji_ch-1_p-19","chapterId":"shiji_ch-1","order":19,"canonicalText":"虞舜者，名曰重華。重華父曰瞽叟，瞽叟父曰橋牛，橋牛父曰句望，句望父曰敬康，敬康父曰窮蟬，窮蟬父曰帝顓頊，顓頊父曰昌意：以至舜七世矣。自從窮蟬以至帝舜，皆微為庶人。","sentenceIds":["shiji_ch-1_p-19_s-1","shiji_ch-1_p-19_s-2","shiji_ch-1_p-19_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"}]},{"id":"shiji_ch-1_p-20","chapterId":"shiji_ch-1","order":20,"canonicalText":"舜父瞽叟盲，而舜母死，瞽叟更娶妻而生象，象傲。瞽叟愛後妻子，常欲殺舜，舜避逃；及有小過，則受罪。順事父及後母與弟，日以篤謹，匪有解。","sentenceIds":["shiji_ch-1_p-20_s-1","shiji_ch-1_p-20_s-2","shiji_ch-1_p-20_s-3","shiji_ch-1_p-20_s-4"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"}]},{"id":"shiji_ch-1_p-21","chapterId":"shiji_ch-1","order":21,"canonicalText":"舜，冀州之人也。舜耕歷山，漁雷澤，陶河濱，作什器於壽丘，就時於負夏。舜父瞽叟頑，母嚚，弟象傲，皆欲殺舜。舜順適不失子道，兄弟孝慈。欲殺，不可得；即求，嘗在側。","sentenceIds":["shiji_ch-1_p-21_s-1","shiji_ch-1_p-21_s-2","shiji_ch-1_p-21_s-3","shiji_ch-1_p-21_s-4","shiji_ch-1_p-21_s-5","shiji_ch-1_p-21_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"}]},{"id":"shiji_ch-1_p-22","chapterId":"shiji_ch-1","order":22,"canonicalText":"舜年二十以孝聞。三十而帝堯問可用者，四嶽咸薦虞舜，曰可。於是堯乃以二女妻舜以觀其內，使九男與處以觀其外。舜居媯汭，內行彌謹。堯二女不敢以貴驕事舜親戚，甚有婦道。堯九男皆益篤。舜耕歷山，歷山之人皆讓畔；漁雷澤，雷澤上人皆讓居；陶河濱，河濱器皆不苦窳。一年而所居成聚，二年成邑，三年成都。堯乃賜舜絺衣，與琴，為筑倉廩，予牛羊。瞽叟尚復欲殺之，使舜上涂廩，瞽叟從下縱火焚廩。舜乃以兩笠自捍而下，去，得不死。後瞽叟又使舜穿井，舜穿井為匿空旁出。舜既入深，瞽叟與象共下土實井，舜從匿空出，去。瞽叟、象喜，以舜為已死。象曰：「本謀者象。」象與其父母分，於是曰：「舜妻堯二女，與琴，象取之。牛羊倉廩予父母。」象乃止舜宮居，鼓其琴。舜往見之。象鄂不懌，曰：「我思舜正郁陶！」舜曰：「然，爾其庶矣！」舜復事瞽叟愛弟彌謹。於是堯乃試舜五典百官，皆治。","sentenceIds":["shiji_ch-1_p-22_s-1","shiji_ch-1_p-22_s-2","shiji_ch-1_p-22_s-3","shiji_ch-1_p-22_s-4","shiji_ch-1_p-22_s-5","shiji_ch-1_p-22_s-6","shiji_ch-1_p-22_s-7","shiji_ch-1_p-22_s-8","shiji_ch-1_p-22_s-9","shiji_ch-1_p-22_s-10","shiji_ch-1_p-22_s-11","shiji_ch-1_p-22_s-12","shiji_ch-1_p-22_s-13","shiji_ch-1_p-22_s-14","shiji_ch-1_p-22_s-15","shiji_ch-1_p-22_s-16","shiji_ch-1_p-22_s-17","shiji_ch-1_p-22_s-18","shiji_ch-1_p-22_s-19","shiji_ch-1_p-22_s-20","shiji_ch-1_p-22_s-21","shiji_ch-1_p-22_s-22","shiji_ch-1_p-22_s-23","shiji_ch-1_p-22_s-24","shiji_ch-1_p-22_s-25"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"}]},{"id":"shiji_ch-1_p-23","chapterId":"shiji_ch-1","order":23,"canonicalText":"昔高陽氏有才子八人，世得其利，謂之「八愷」。高辛氏有才子八人，世謂之「八元」。此十六族者，世濟其美，不隕其名。至於堯，堯未能舉。舜舉八愷，使主后土，以揆百事，莫不時序。舉八元，使布五教于四方，父義，母慈，兄友，弟恭，子孝，內平外成。","sentenceIds":["shiji_ch-1_p-23_s-1","shiji_ch-1_p-23_s-2","shiji_ch-1_p-23_s-3","shiji_ch-1_p-23_s-4","shiji_ch-1_p-23_s-5","shiji_ch-1_p-23_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"}]},{"id":"shiji_ch-1_p-24","chapterId":"shiji_ch-1","order":24,"canonicalText":"昔帝鴻氏有不才子，掩義隱賊，好行凶慝，天下謂之渾沌。少暤氏有不才子，毀信惡忠，崇飾惡言，天下謂之窮奇。顓頊氏有不才子，不可教訓，不知話言，天下謂之梼杌。此三族世憂之。至于堯，堯未能去。縉云氏有不才子，貪于飲食，冒于貨賄，天下謂之饕餮。天下惡之，比之三凶。舜賓於四門，乃流四凶族，遷于四裔，以御螭魅，於是四門辟，言毋凶人也。","sentenceIds":["shiji_ch-1_p-24_s-1","shiji_ch-1_p-24_s-2","shiji_ch-1_p-24_s-3","shiji_ch-1_p-24_s-4","shiji_ch-1_p-24_s-5","shiji_ch-1_p-24_s-6","shiji_ch-1_p-24_s-7","shiji_ch-1_p-24_s-8"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"}]},{"id":"shiji_ch-1_p-25","chapterId":"shiji_ch-1","order":25,"canonicalText":"舜入于大麓，烈風雷雨不迷，堯乃知舜之足授天下。堯老，使舜攝行天子政，巡狩。舜得舉用事二十年，而堯使攝政。攝政八年而堯崩。三年喪畢，讓丹朱，天下歸舜。而禹、皋陶、契、后稷、伯夷、夔、龍、倕、益、彭祖自堯時而皆舉用，未有分職。於是舜乃至於文祖，謀于四嶽，辟四門，明通四方耳目，命十二牧論帝德，行厚德，遠佞人，則蠻夷率服。舜謂四嶽曰：「有能奮庸美堯之事者，使居官相事？」皆曰：「伯禹為司空，可美帝功。」舜曰：「嗟，然！禹，汝平水土，維是勉哉。」禹拜稽首，讓於稷、契與皋陶。舜曰：「然，往矣。」舜曰：「棄，黎民始饑，汝后稷播時百穀。」舜曰：「契，百姓不親，五品不馴，汝為司徒，而敬敷五教，在寬。」舜曰：「皋陶，蠻夷猾夏，寇賊姦軌，汝作士，五刑有服，五服三就；五流有度，五度三居：維明能信。」舜曰：「誰能馴予工？」皆曰垂可。於是以垂為共工。舜曰：「誰能馴予上下草木鳥獸？」皆曰益可。於是以益為朕虞。益拜稽首，讓于諸臣朱虎、熊羆。舜曰：「往矣，汝諧。」遂以朱虎、熊羆為佐。舜曰：「嗟！四嶽，有能典朕三禮？」皆曰伯夷可。舜曰：「嗟！伯夷，以汝為秩宗，夙夜維敬，直哉維靜絜。」伯夷讓夔、龍。舜曰：「然。以夔為典樂，教稚子，直而溫，寬而栗，剛而毋虐，簡而毋傲；詩言意，歌長言，聲依永，律和聲，八音能諧，毋相奪倫，神人以和。」夔曰：「於！予擊石拊石，百獸率舞。」舜曰：「龍，朕畏忌讒說殄偽，振驚朕眾，命汝為納言，夙夜出入朕命，惟信。」舜曰：「嗟！女二十有二人，敬哉，惟時相天事。」三歲一考功，三考絀陟，遠近眾功咸興。分北三苗。","sentenceIds":["shiji_ch-1_p-25_s-1","shiji_ch-1_p-25_s-2","shiji_ch-1_p-25_s-3","shiji_ch-1_p-25_s-4","shiji_ch-1_p-25_s-5","shiji_ch-1_p-25_s-6","shiji_ch-1_p-25_s-7","shiji_ch-1_p-25_s-8","shiji_ch-1_p-25_s-9","shiji_ch-1_p-25_s-10","shiji_ch-1_p-25_s-11","shiji_ch-1_p-25_s-12","shiji_ch-1_p-25_s-13","shiji_ch-1_p-25_s-14","shiji_ch-1_p-25_s-15","shiji_ch-1_p-25_s-16","shiji_ch-1_p-25_s-17","shiji_ch-1_p-25_s-18","shiji_ch-1_p-25_s-19","shiji_ch-1_p-25_s-20","shiji_ch-1_p-25_s-21","shiji_ch-1_p-25_s-22","shiji_ch-1_p-25_s-23","shiji_ch-1_p-25_s-24","shiji_ch-1_p-25_s-25","shiji_ch-1_p-25_s-26","shiji_ch-1_p-25_s-27","shiji_ch-1_p-25_s-28","shiji_ch-1_p-25_s-29","shiji_ch-1_p-25_s-30","shiji_ch-1_p-25_s-31","shiji_ch-1_p-25_s-32","shiji_ch-1_p-25_s-33","shiji_ch-1_p-25_s-34","shiji_ch-1_p-25_s-35","shiji_ch-1_p-25_s-36","shiji_ch-1_p-25_s-37","shiji_ch-1_p-25_s-38","shiji_ch-1_p-25_s-39","shiji_ch-1_p-25_s-40","shiji_ch-1_p-25_s-41","shiji_ch-1_p-25_s-42"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"}]},{"id":"shiji_ch-1_p-26","chapterId":"shiji_ch-1","order":26,"canonicalText":"此二十二人咸成厥功：皋陶為大理，平，民各伏得其實；伯夷主禮，上下咸讓；垂主工師，百工致功；益主虞，山澤辟；棄主稷，百穀時茂；契主司徒，百姓親和；龍主賓客，遠人至；十二牧行而九州莫敢辟違；唯禹之功為大，披九山，通九澤，決九河，定九州，各以其職來貢，不失厥宜。方五千里，至于荒服。南撫交阯、北發，西戎、析枝、渠廋、氐、羌，北山戎、發、息慎，東長、鳥夷，四海之內咸戴帝舜之功。於是禹乃興九招之樂，致異物，鳳皇來翔。天下明德皆自虞帝始。","sentenceIds":["shiji_ch-1_p-26_s-1","shiji_ch-1_p-26_s-2","shiji_ch-1_p-26_s-3","shiji_ch-1_p-26_s-4","shiji_ch-1_p-26_s-5","shiji_ch-1_p-26_s-6","shiji_ch-1_p-26_s-7","shiji_ch-1_p-26_s-8","shiji_ch-1_p-26_s-9","shiji_ch-1_p-26_s-10","shiji_ch-1_p-26_s-11","shiji_ch-1_p-26_s-12","shiji_ch-1_p-26_s-13"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"}]},{"id":"shiji_ch-1_p-27","chapterId":"shiji_ch-1","order":27,"canonicalText":"舜年二十以孝聞，年三十堯舉之，年五十攝行天子事，年五十八堯崩，年六十一代堯踐帝位。踐帝位三十九年，南巡狩，崩於蒼梧之野。葬於江南九疑，是為零陵。舜之踐帝位，載天子旗，往朝父瞽叟，夔夔唯謹，如子道。封弟象為諸侯。舜子商均亦不肖，舜乃豫薦禹於天。十七年而崩。三年喪畢，禹亦乃讓舜子，如舜讓堯子。諸侯歸之，然後禹踐天子位。堯子丹朱，舜子商均，皆有疆土，以奉先祀。服其服，禮樂如之。以客見天子，天子弗臣，示不敢專也。","sentenceIds":["shiji_ch-1_p-27_s-1","shiji_ch-1_p-27_s-2","shiji_ch-1_p-27_s-3","shiji_ch-1_p-27_s-4","shiji_ch-1_p-27_s-5","shiji_ch-1_p-27_s-6","shiji_ch-1_p-27_s-7","shiji_ch-1_p-27_s-8","shiji_ch-1_p-27_s-9","shiji_ch-1_p-27_s-10","shiji_ch-1_p-27_s-11","shiji_ch-1_p-27_s-12"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"}]},{"id":"shiji_ch-1_p-28","chapterId":"shiji_ch-1","order":28,"canonicalText":"自黃帝至舜、禹，皆同姓而異其國號，以章明德。故黃帝為有熊，帝顓頊為高陽，帝嚳為高辛，帝堯為陶唐，帝舜為有虞。帝禹為夏后而別氏，姓姒氏。契為商，姓子氏。棄為周，姓姬氏。","sentenceIds":["shiji_ch-1_p-28_s-1","shiji_ch-1_p-28_s-2","shiji_ch-1_p-28_s-3","shiji_ch-1_p-28_s-4","shiji_ch-1_p-28_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"}]},{"id":"shiji_ch-1_p-29","chapterId":"shiji_ch-1","order":29,"canonicalText":"太史公曰：學者多稱五帝，尚矣。然尚書獨載堯以來；而百家言黃帝，其文不雅馴，薦紳先生難言之。孔子所傳宰予問五帝德及帝系姓，儒者或不傳。余嘗西至空桐，北過涿鹿，東漸於海，南浮江淮矣，至長老皆各往往稱黃帝、堯、舜之處，風教固殊焉，總之不離古文者近是。予觀春秋、國語，其發明五帝德、帝系姓章矣，顧弟弗深考，其所表見皆不虛。書缺有閒矣，其軼乃時時見於他說。非好學深思，心知其意，固難為淺見寡聞道也。余并論次，擇其言尤雅者，故著為本紀書首。","sentenceIds":["shiji_ch-1_p-29_s-1","shiji_ch-1_p-29_s-2","shiji_ch-1_p-29_s-3","shiji_ch-1_p-29_s-4","shiji_ch-1_p-29_s-5","shiji_ch-1_p-29_s-6","shiji_ch-1_p-29_s-7","shiji_ch-1_p-29_s-8","shiji_ch-1_p-29_s-9"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"}]},{"id":"shiji_ch-2_p-1","chapterId":"shiji_ch-2","order":1,"canonicalText":"夏禹，名曰文命。禹之父曰鯀，鯀之父曰帝顓頊，顓頊之父曰昌意，昌意之父曰黃帝。禹者，黃帝之玄孫而帝顓頊之孫也。禹之曾大父昌意及父鯀皆不得在帝位，為人臣。","sentenceIds":["shiji_ch-2_p-1_s-1","shiji_ch-2_p-1_s-2","shiji_ch-2_p-1_s-3","shiji_ch-2_p-1_s-4"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"}]},{"id":"shiji_ch-2_p-2","chapterId":"shiji_ch-2","order":2,"canonicalText":"當帝堯之時，鴻水滔天，浩浩懷山襄陵，下民其憂。堯求能治水者，群臣四嶽皆曰鯀可。堯曰：「鯀為人負命毀族，不可。」四嶽曰：「等之未有賢於鯀者，願帝試之。」於是堯聽四嶽，用鯀治水。九年而水不息，功用不成。於是帝堯乃求人，更得舜。舜登用，攝行天子之政，巡狩。行視鯀之治水無狀，乃殛鯀於羽山以死。天下皆以舜之誅為是。於是舜舉鯀子禹，而使續鯀之業。","sentenceIds":["shiji_ch-2_p-2_s-1","shiji_ch-2_p-2_s-2","shiji_ch-2_p-2_s-3","shiji_ch-2_p-2_s-4","shiji_ch-2_p-2_s-5","shiji_ch-2_p-2_s-6","shiji_ch-2_p-2_s-7","shiji_ch-2_p-2_s-8","shiji_ch-2_p-2_s-9","shiji_ch-2_p-2_s-10","shiji_ch-2_p-2_s-11"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"}]},{"id":"shiji_ch-2_p-3","chapterId":"shiji_ch-2","order":3,"canonicalText":"堯崩，帝舜問四嶽曰：「有能成美堯之事者使居官？」皆曰：「伯禹為司空，可成美堯之功。」舜曰：「嗟，然！」命禹：「女平水土，維是勉之。」禹拜稽首，讓於契、后稷、皋陶。舜曰：「女其往視爾事矣。」","sentenceIds":["shiji_ch-2_p-3_s-1","shiji_ch-2_p-3_s-2","shiji_ch-2_p-3_s-3","shiji_ch-2_p-3_s-4","shiji_ch-2_p-3_s-5","shiji_ch-2_p-3_s-6","shiji_ch-2_p-3_s-7"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"}]},{"id":"shiji_ch-2_p-4","chapterId":"shiji_ch-2","order":4,"canonicalText":"禹為人敏給克勤；其德不違，其仁可親，其言可信；聲為律，身為度，稱以出；亹亹穆穆，為綱為紀。","sentenceIds":["shiji_ch-2_p-4_s-1","shiji_ch-2_p-4_s-2","shiji_ch-2_p-4_s-3","shiji_ch-2_p-4_s-4"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"}]},{"id":"shiji_ch-2_p-5","chapterId":"shiji_ch-2","order":5,"canonicalText":"禹乃遂與益、后稷奉帝命，命諸侯百姓興人徒以傅土，行山表木，定高山大川。禹傷先人父鯀功之不成受誅，乃勞身焦思，居外十三年，過家門不敢入。薄衣食，致孝于鬼神。卑宮室，致費於溝淢。陸行乘車，水行乘船，泥行乘橇，山行乘檋。左準繩，右規矩，載四時，以開九州，通九道，陂九澤，度九山。令益予眾庶稻，可種卑溼。命后稷予眾庶難得之食。食少，調有餘相給，以均諸侯。禹乃行相地宜所有以貢，及山川之便利。","sentenceIds":["shiji_ch-2_p-5_s-1","shiji_ch-2_p-5_s-2","shiji_ch-2_p-5_s-3","shiji_ch-2_p-5_s-4","shiji_ch-2_p-5_s-5","shiji_ch-2_p-5_s-6","shiji_ch-2_p-5_s-7","shiji_ch-2_p-5_s-8","shiji_ch-2_p-5_s-9","shiji_ch-2_p-5_s-10"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"}]},{"id":"shiji_ch-2_p-6","chapterId":"shiji_ch-2","order":6,"canonicalText":"禹行自冀州始。冀州：既載壺口，治梁及岐。既修太原，至于嶽陽。覃懷致功，至於衡漳。其土白壤。賦上上錯，田中中，常、衛既從，大陸既為。鳥夷皮服。夾右碣石，入于海。","sentenceIds":["shiji_ch-2_p-6_s-1","shiji_ch-2_p-6_s-2","shiji_ch-2_p-6_s-3","shiji_ch-2_p-6_s-4","shiji_ch-2_p-6_s-5","shiji_ch-2_p-6_s-6","shiji_ch-2_p-6_s-7","shiji_ch-2_p-6_s-8"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"}]},{"id":"shiji_ch-2_p-7","chapterId":"shiji_ch-2","order":7,"canonicalText":"濟、河維沇州：九河既道，雷夏既澤，雍、沮會同，桑土既蠶，於是民得下丘居土。其土黑墳，草繇木條。田中下，賦貞，作十有三年乃同。其貢漆絲，其篚織文。浮於濟、漯，通於河。","sentenceIds":["shiji_ch-2_p-7_s-1","shiji_ch-2_p-7_s-2","shiji_ch-2_p-7_s-3","shiji_ch-2_p-7_s-4","shiji_ch-2_p-7_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"}]},{"id":"shiji_ch-2_p-8","chapterId":"shiji_ch-2","order":8,"canonicalText":"海岱維青州：堣夷既略，濰、淄其道。其土白墳，海濱廣潟，厥田斥鹵。田上下，賦中上。厥貢鹽絺，海物維錯，岱畎絲、枲、鉛、松、怪石，萊夷為牧，其篚酓絲。浮於汶，通於濟。","sentenceIds":["shiji_ch-2_p-8_s-1","shiji_ch-2_p-8_s-2","shiji_ch-2_p-8_s-3","shiji_ch-2_p-8_s-4","shiji_ch-2_p-8_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"}]},{"id":"shiji_ch-2_p-9","chapterId":"shiji_ch-2","order":9,"canonicalText":"海岱及淮維徐州：淮、沂其治，蒙、羽其藝。大野既都，東原底平。其土赤埴墳，草木漸包。其田上中，賦中中。貢維土五色，羽畎夏狄，嶧陽孤桐，泗濱浮磬，淮夷蠙珠臮魚，其篚玄纖縞。浮于淮、泗，通于河。","sentenceIds":["shiji_ch-2_p-9_s-1","shiji_ch-2_p-9_s-2","shiji_ch-2_p-9_s-3","shiji_ch-2_p-9_s-4","shiji_ch-2_p-9_s-5","shiji_ch-2_p-9_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"}]},{"id":"shiji_ch-2_p-10","chapterId":"shiji_ch-2","order":10,"canonicalText":"淮海維揚州：彭蠡既都，陽鳥所居。三江既入，震澤致定。竹箭既布。其草惟夭，其木惟喬，其土涂泥。田下下，賦下上上雜。貢金三品，瑤、琨、竹箭，齒、革、羽、旄，島夷卉服，其篚織貝，其包橘、柚錫貢。均江海，通淮、泗。","sentenceIds":["shiji_ch-2_p-10_s-1","shiji_ch-2_p-10_s-2","shiji_ch-2_p-10_s-3","shiji_ch-2_p-10_s-4","shiji_ch-2_p-10_s-5","shiji_ch-2_p-10_s-6","shiji_ch-2_p-10_s-7"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"}]},{"id":"shiji_ch-2_p-11","chapterId":"shiji_ch-2","order":11,"canonicalText":"荊及衡陽維荊州：江、漢朝宗于海。九江甚中，沱、涔已道，云土、夢為治。其土涂泥。田下中，賦上下。貢羽、旄、齒、革，金三品，杶、榦、栝、柏，礪、砥、砮、丹，維箘簬、楛，三國致貢其名，包匭菁茅，其篚玄纁璣組，九江入賜大龜。浮于江、沱、涔、（于）漢，踰于雒，至于南河。","sentenceIds":["shiji_ch-2_p-11_s-1","shiji_ch-2_p-11_s-2","shiji_ch-2_p-11_s-3","shiji_ch-2_p-11_s-4","shiji_ch-2_p-11_s-5","shiji_ch-2_p-11_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"}]},{"id":"shiji_ch-2_p-12","chapterId":"shiji_ch-2","order":12,"canonicalText":"荊河惟豫州：伊、雒、瀍、澗既入于河，滎播既都，道荷澤，被明都。其土壤，下土墳壚。田中上，賦雜上中。貢漆、絲、絺、紵，其篚纖絮，錫貢磬錯。浮於雒，達於河。","sentenceIds":["shiji_ch-2_p-12_s-1","shiji_ch-2_p-12_s-2","shiji_ch-2_p-12_s-3","shiji_ch-2_p-12_s-4","shiji_ch-2_p-12_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"}]},{"id":"shiji_ch-2_p-13","chapterId":"shiji_ch-2","order":13,"canonicalText":"華陽黑水惟梁州：汶、嶓既藝，沱、涔既道，蔡、蒙旅平，和夷厎績。其土青驪。田下上，賦下中三錯。貢璆、鐵、銀、鏤、砮、磬，熊、羆、狐、貍、織皮。西傾因桓是來，浮于潛，踰于沔，入于渭，亂于河。","sentenceIds":["shiji_ch-2_p-13_s-1","shiji_ch-2_p-13_s-2","shiji_ch-2_p-13_s-3","shiji_ch-2_p-13_s-4","shiji_ch-2_p-13_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"}]},{"id":"shiji_ch-2_p-14","chapterId":"shiji_ch-2","order":14,"canonicalText":"黑水西河惟雍州：弱水既西，涇屬渭汭。漆、沮既從，灃水所同。荊、岐已旅，終南、敦物至于鳥鼠。原隰厎績，至于都野。三危既度，三苗大序。其土黃壤。田上上，賦中下。貢璆、琳、瑯玕。浮于積石，至于龍門西河，會于渭汭。織皮昆侖、析支、渠搜，西戎即序。","sentenceIds":["shiji_ch-2_p-14_s-1","shiji_ch-2_p-14_s-2","shiji_ch-2_p-14_s-3","shiji_ch-2_p-14_s-4","shiji_ch-2_p-14_s-5","shiji_ch-2_p-14_s-6","shiji_ch-2_p-14_s-7","shiji_ch-2_p-14_s-8","shiji_ch-2_p-14_s-9","shiji_ch-2_p-14_s-10"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"}]},{"id":"shiji_ch-2_p-15","chapterId":"shiji_ch-2","order":15,"canonicalText":"道九山：汧及岐至于荊山，踰于河；壺口、雷首至于太嶽；砥柱、析城至于王屋；太行、常山至于碣石，入于海；西傾、朱圉、鳥鼠至于太華；熊耳、外方、桐柏至于負尾；道嶓冢，至于荊山；內方至于大別；汶山之陽至衡山，過九江，至于敷淺原。","sentenceIds":["shiji_ch-2_p-15_s-1","shiji_ch-2_p-15_s-2","shiji_ch-2_p-15_s-3","shiji_ch-2_p-15_s-4","shiji_ch-2_p-15_s-5","shiji_ch-2_p-15_s-6","shiji_ch-2_p-15_s-7","shiji_ch-2_p-15_s-8","shiji_ch-2_p-15_s-9"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"}]},{"id":"shiji_ch-2_p-16","chapterId":"shiji_ch-2","order":16,"canonicalText":"道九川：弱水至於合黎，餘波入于流沙。道黑水，至于三危，入于南海。道河積石，至于龍門，南至華陰，東至砥柱，又東至于盟津，東過雒汭，至于大邳，北過降水，至于大陸，北播為九河，同為逆河，入于海。嶓冢道瀁，東流為漢，又東為蒼浪之水，過三澨，入于大別，南入于江，東匯澤為彭蠡，東為北江，入于海。汶山道江，東別為沱，又東至于醴，過九江，至于東陵，東迆北會于匯，東為中江，入于梅。道沇水，東為濟，入于河，泆為滎，東出陶丘北，又東至于荷，又東北會于汶，又東北入于海。道淮自桐柏，東會于泗、沂，東入于海。道渭自鳥鼠同穴，東會于灃，又東北至于涇，東過漆、沮，入于河。道雒自熊耳，東北會于澗、瀍，又東會于伊，東北入于河。","sentenceIds":["shiji_ch-2_p-16_s-1","shiji_ch-2_p-16_s-2","shiji_ch-2_p-16_s-3","shiji_ch-2_p-16_s-4","shiji_ch-2_p-16_s-5","shiji_ch-2_p-16_s-6","shiji_ch-2_p-16_s-7","shiji_ch-2_p-16_s-8","shiji_ch-2_p-16_s-9"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"}]},{"id":"shiji_ch-2_p-17","chapterId":"shiji_ch-2","order":17,"canonicalText":"於是九州攸同，四奧既居，九山刊旅，九川滌原，九澤既陂，四海會同。六府甚修，眾土交正，致慎財賦，咸則三壤成賦。中國賜土姓：「祗臺德先，不距朕行。」","sentenceIds":["shiji_ch-2_p-17_s-1","shiji_ch-2_p-17_s-2","shiji_ch-2_p-17_s-3","shiji_ch-2_p-17_s-4"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"}]},{"id":"shiji_ch-2_p-18","chapterId":"shiji_ch-2","order":18,"canonicalText":"令天子之國以外五百里甸服：百里賦納總，二百里納銍，三百里納秸服，四百里粟，五百里米。甸服外五百里侯服：百里采，二百里任國，三百里諸侯。侯服外五百里綏服：三百里揆文教，二百里奮武衛。綏服外五百里要服：三百里夷，二百里蔡。要服外五百里荒服：三百里蠻，二百里流。","sentenceIds":["shiji_ch-2_p-18_s-1","shiji_ch-2_p-18_s-2","shiji_ch-2_p-18_s-3","shiji_ch-2_p-18_s-4","shiji_ch-2_p-18_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"}]},{"id":"shiji_ch-2_p-19","chapterId":"shiji_ch-2","order":19,"canonicalText":"東漸于海，西被于流沙，朔、南暨：聲教訖于四海。於是帝錫禹玄圭，以告成功于天下。天下於是太平治。","sentenceIds":["shiji_ch-2_p-19_s-1","shiji_ch-2_p-19_s-2","shiji_ch-2_p-19_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"}]},{"id":"shiji_ch-2_p-20","chapterId":"shiji_ch-2","order":20,"canonicalText":"皋陶作士以理民。帝舜朝，禹、伯夷、皋陶相與語帝前。皋陶述其謀曰：「信其道德，謀明輔和。」禹曰：「然，如何？」皋陶曰：「於！慎其身修，思長，敦序九族，眾明高翼，近可遠在已。」禹拜美言，曰：「然。」皋陶曰：「於！在知人，在安民。」禹曰：「吁！皆若是，惟帝其難之。知人則智，能官人；能安民則惠，黎民懷之。能知能惠，何憂乎驩兜，何遷乎有苗，何畏乎巧言善色佞人？」皋陶曰：「然，於！亦行有九德，亦言其有德。」乃言曰：「始事事，寬而栗，柔而立，願而共，治而敬，擾而毅，直而溫，簡而廉，剛而實，彊而義，章其有常，吉哉。日宣三德，蚤夜翊明有家。日嚴振敬六德，亮采有國。翕受普施，九德咸事，俊乂在官，百吏肅謹。毋教邪淫奇謀。非其人居其官，是謂亂天事。天討有罪，五刑五用哉。吾言厎可行乎？」禹曰：「女言致可績行。」皋陶曰：「余未有知，思贊道哉。」","sentenceIds":["shiji_ch-2_p-20_s-1","shiji_ch-2_p-20_s-2","shiji_ch-2_p-20_s-3","shiji_ch-2_p-20_s-4","shiji_ch-2_p-20_s-5","shiji_ch-2_p-20_s-6","shiji_ch-2_p-20_s-7","shiji_ch-2_p-20_s-8","shiji_ch-2_p-20_s-9","shiji_ch-2_p-20_s-10","shiji_ch-2_p-20_s-11","shiji_ch-2_p-20_s-12","shiji_ch-2_p-20_s-13","shiji_ch-2_p-20_s-14","shiji_ch-2_p-20_s-15","shiji_ch-2_p-20_s-16","shiji_ch-2_p-20_s-17","shiji_ch-2_p-20_s-18","shiji_ch-2_p-20_s-19","shiji_ch-2_p-20_s-20","shiji_ch-2_p-20_s-21","shiji_ch-2_p-20_s-22","shiji_ch-2_p-20_s-23","shiji_ch-2_p-20_s-24","shiji_ch-2_p-20_s-25","shiji_ch-2_p-20_s-26","shiji_ch-2_p-20_s-27"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"}]},{"id":"shiji_ch-2_p-21","chapterId":"shiji_ch-2","order":21,"canonicalText":"帝舜謂禹曰：「女亦昌言。」禹拜曰；「於，予何言！予思日孳孳。」皋陶難禹曰：「何謂孳孳？」禹曰：「鴻水滔天，浩浩懷山襄陵，下民皆服於水。予陸行乘車，水行乘舟，泥行乘橇，山行乘檋，行山刊木。與益予眾庶稻鮮食。以決九川致四海，浚畎澮致之川。與稷予眾庶難得之食。食少，調有餘補不足，徙居。眾民乃定，萬國為治。」皋陶曰：「然，此而美也。」","sentenceIds":["shiji_ch-2_p-21_s-1","shiji_ch-2_p-21_s-2","shiji_ch-2_p-21_s-3","shiji_ch-2_p-21_s-4","shiji_ch-2_p-21_s-5","shiji_ch-2_p-21_s-6","shiji_ch-2_p-21_s-7","shiji_ch-2_p-21_s-8","shiji_ch-2_p-21_s-9","shiji_ch-2_p-21_s-10","shiji_ch-2_p-21_s-11","shiji_ch-2_p-21_s-12","shiji_ch-2_p-21_s-13","shiji_ch-2_p-21_s-14"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"}]},{"id":"shiji_ch-2_p-22","chapterId":"shiji_ch-2","order":22,"canonicalText":"禹曰：「於，帝！慎乃在位，安爾止。輔德，天下大應。清意以昭待上帝命，天其重命用休。」帝曰：「吁，臣哉，臣哉！臣作朕股肱耳目。予欲左右有民，女輔之。余欲觀古人之象。日月星辰，作文繡服色，女明之。予欲聞六律五聲八音，來始滑，以出入五言，女聽。予即辟，女匡拂予。女無面諛。退而謗予。敬四輔臣。諸眾讒嬖臣，君德誠施皆清矣。」禹曰：「然。帝即不時，布同善惡則毋功。」","sentenceIds":["shiji_ch-2_p-22_s-1","shiji_ch-2_p-22_s-2","shiji_ch-2_p-22_s-3","shiji_ch-2_p-22_s-4","shiji_ch-2_p-22_s-5","shiji_ch-2_p-22_s-6","shiji_ch-2_p-22_s-7","shiji_ch-2_p-22_s-8","shiji_ch-2_p-22_s-9","shiji_ch-2_p-22_s-10","shiji_ch-2_p-22_s-11","shiji_ch-2_p-22_s-12","shiji_ch-2_p-22_s-13","shiji_ch-2_p-22_s-14","shiji_ch-2_p-22_s-15","shiji_ch-2_p-22_s-16","shiji_ch-2_p-22_s-17","shiji_ch-2_p-22_s-18"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"}]},{"id":"shiji_ch-2_p-23","chapterId":"shiji_ch-2","order":23,"canonicalText":"帝曰：「毋若丹朱傲，維慢游是好，毋水行舟，朋淫于家，用絕其世。予不能順是。」禹曰：「予（辛壬）娶涂山，［辛壬］癸甲，生啟予不子，以故能成水土功。輔成五服，至于五千里，州十二師，外薄四海，咸建五長，各道有功。苗頑不即功，帝其念哉。」帝曰：「道吾德，乃女功序之也。」","sentenceIds":["shiji_ch-2_p-23_s-1","shiji_ch-2_p-23_s-2","shiji_ch-2_p-23_s-3","shiji_ch-2_p-23_s-4","shiji_ch-2_p-23_s-5","shiji_ch-2_p-23_s-6","shiji_ch-2_p-23_s-7"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"}]},{"id":"shiji_ch-2_p-24","chapterId":"shiji_ch-2","order":24,"canonicalText":"皋陶於是敬禹之德，令民皆則禹。不如言，刑從之。舜德大明。","sentenceIds":["shiji_ch-2_p-24_s-1","shiji_ch-2_p-24_s-2","shiji_ch-2_p-24_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"}]},{"id":"shiji_ch-2_p-25","chapterId":"shiji_ch-2","order":25,"canonicalText":"於是夔行樂，祖考至，群后相讓，鳥獸翔舞，簫韶九成，鳳皇來儀，百獸率舞，百官信諧。帝用此作歌曰：「陟天之命，維時維幾。」乃歌曰：「股肱喜哉，元首起哉，百工熙哉！」皋陶拜手稽首揚言曰：「念哉，率為興事，慎乃憲，敬哉！」乃更為歌曰：「元首明哉，股肱良哉，庶事康哉！」（舜）又歌曰：「元首叢脞哉，股肱惰哉，萬事墮哉！」帝拜曰：「然，往欽哉！」於是天下皆宗禹之明度數聲樂，為山川神主。","sentenceIds":["shiji_ch-2_p-25_s-1","shiji_ch-2_p-25_s-2","shiji_ch-2_p-25_s-3","shiji_ch-2_p-25_s-4","shiji_ch-2_p-25_s-5","shiji_ch-2_p-25_s-6","shiji_ch-2_p-25_s-7","shiji_ch-2_p-25_s-8"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"}]},{"id":"shiji_ch-2_p-26","chapterId":"shiji_ch-2","order":26,"canonicalText":"帝舜薦禹於天，為嗣。十七年而帝舜崩。三年喪畢，禹辭辟舜之子商均於陽城。天下諸侯皆去商均而朝禹。禹於是遂即天子位，南面朝天下，國號曰夏后，姓姒氏。","sentenceIds":["shiji_ch-2_p-26_s-1","shiji_ch-2_p-26_s-2","shiji_ch-2_p-26_s-3","shiji_ch-2_p-26_s-4","shiji_ch-2_p-26_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"}]},{"id":"shiji_ch-2_p-27","chapterId":"shiji_ch-2","order":27,"canonicalText":"帝禹立而舉皋陶薦之，且授政焉，而皋陶卒。封皋陶之後於英、六，或在許。而后舉益，任之政。","sentenceIds":["shiji_ch-2_p-27_s-1","shiji_ch-2_p-27_s-2","shiji_ch-2_p-27_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"}]},{"id":"shiji_ch-2_p-28","chapterId":"shiji_ch-2","order":28,"canonicalText":"十年，帝禹東巡狩，至于會稽而崩。以天下授益。三年之喪畢，益讓帝禹之子啟，而辟居箕山之陽。禹子啟賢，天下屬意焉。及禹崩，雖授益，益之佐禹日淺，天下未洽。故諸侯皆去益而朝啟，曰：「吾君帝禹之子也」。於是啟遂即天子之位，是為夏后帝啟。","sentenceIds":["shiji_ch-2_p-28_s-1","shiji_ch-2_p-28_s-2","shiji_ch-2_p-28_s-3","shiji_ch-2_p-28_s-4","shiji_ch-2_p-28_s-5","shiji_ch-2_p-28_s-6","shiji_ch-2_p-28_s-7"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"}]},{"id":"shiji_ch-2_p-29","chapterId":"shiji_ch-2","order":29,"canonicalText":"夏后帝啟，禹之子，其母涂山氏之女也。","sentenceIds":["shiji_ch-2_p-29_s-1"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"}]},{"id":"shiji_ch-2_p-30","chapterId":"shiji_ch-2","order":30,"canonicalText":"有扈氏不服，啟伐之，大戰於甘。將戰，作甘誓，乃召六卿申之。啟曰：「嗟！六事之人，予誓告女：有扈氏威侮五行，怠棄三正，天用勦絕其命。今予維共行天之罰。左不攻于左，右不攻于右，女不共命。御非其馬之政，女不共命。用命，賞于祖；不用命，僇于社，予則帑僇女。」遂滅有扈氏。天下咸朝。","sentenceIds":["shiji_ch-2_p-30_s-1","shiji_ch-2_p-30_s-2","shiji_ch-2_p-30_s-3","shiji_ch-2_p-30_s-4","shiji_ch-2_p-30_s-5","shiji_ch-2_p-30_s-6","shiji_ch-2_p-30_s-7","shiji_ch-2_p-30_s-8","shiji_ch-2_p-30_s-9","shiji_ch-2_p-30_s-10","shiji_ch-2_p-30_s-11"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"}]},{"id":"shiji_ch-2_p-31","chapterId":"shiji_ch-2","order":31,"canonicalText":"夏后帝啟崩，子帝太康立。帝太康失國，昆弟五人，須于洛汭，作五子之歌。","sentenceIds":["shiji_ch-2_p-31_s-1","shiji_ch-2_p-31_s-2"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"}]},{"id":"shiji_ch-2_p-32","chapterId":"shiji_ch-2","order":32,"canonicalText":"太康崩，弟中康立，是為帝中康。帝中康時，羲、和湎淫，廢時亂日。胤往征之，作胤征。","sentenceIds":["shiji_ch-2_p-32_s-1","shiji_ch-2_p-32_s-2","shiji_ch-2_p-32_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"}]},{"id":"shiji_ch-2_p-33","chapterId":"shiji_ch-2","order":33,"canonicalText":"中康崩，子帝相立。帝相崩，子帝少康立。帝少康崩，子帝予立。帝予崩，子帝槐立。帝槐崩，子帝芒立。帝芒崩，子帝泄立。帝泄崩，子帝不降立。帝不降崩，弟帝扃立。帝扃崩，子帝廑立。帝廑崩，立帝不降之子孔甲，是為帝孔甲。帝孔甲立，好方鬼神，事淫亂。夏后氏德衰，諸侯畔之。天降龍二，有雌雄，孔甲不能食，未得豢龍氏。陶唐既衰，其后有劉累，學擾龍于豢龍氏，以事孔甲。孔甲賜之姓曰御龍氏，受豕韋之後。龍一雌死，以食夏后。夏后使求，懼而遷去。","sentenceIds":["shiji_ch-2_p-33_s-1","shiji_ch-2_p-33_s-2","shiji_ch-2_p-33_s-3","shiji_ch-2_p-33_s-4","shiji_ch-2_p-33_s-5","shiji_ch-2_p-33_s-6","shiji_ch-2_p-33_s-7","shiji_ch-2_p-33_s-8","shiji_ch-2_p-33_s-9","shiji_ch-2_p-33_s-10","shiji_ch-2_p-33_s-11","shiji_ch-2_p-33_s-12","shiji_ch-2_p-33_s-13","shiji_ch-2_p-33_s-14","shiji_ch-2_p-33_s-15","shiji_ch-2_p-33_s-16","shiji_ch-2_p-33_s-17"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"}]},{"id":"shiji_ch-2_p-34","chapterId":"shiji_ch-2","order":34,"canonicalText":"孔甲崩，子帝皋立。帝皋崩，子帝發立。帝發崩，子帝履癸立，是為桀。帝桀之時，自孔甲以來而諸侯多畔夏，桀不務德而武傷百姓，百姓弗堪。乃召湯而囚之夏臺，已而釋之。湯修德，諸侯皆歸湯，湯遂率兵以伐夏桀。桀走鳴條，遂放而死。桀謂人曰：「吾悔不遂殺湯於夏臺，使至此。」湯乃踐天子位，代夏朝天下。湯封夏之後，至周封於杞也。","sentenceIds":["shiji_ch-2_p-34_s-1","shiji_ch-2_p-34_s-2","shiji_ch-2_p-34_s-3","shiji_ch-2_p-34_s-4","shiji_ch-2_p-34_s-5","shiji_ch-2_p-34_s-6","shiji_ch-2_p-34_s-7","shiji_ch-2_p-34_s-8","shiji_ch-2_p-34_s-9","shiji_ch-2_p-34_s-10"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"}]},{"id":"shiji_ch-2_p-35","chapterId":"shiji_ch-2","order":35,"canonicalText":"太史公曰：禹為姒姓，其後分封，用國為姓，故有夏后氏、有扈氏、有男氏、斟尋氏、彤城氏、褒氏、費氏、杞氏、繒氏、辛氏、冥氏、斟（氏）戈氏。孔子正夏時，學者多傳夏小正云。自虞、夏時，貢賦備矣。或言禹會諸侯江南，計功而崩，因葬焉，命曰會稽。會稽者，會計也。","sentenceIds":["shiji_ch-2_p-35_s-1","shiji_ch-2_p-35_s-2","shiji_ch-2_p-35_s-3","shiji_ch-2_p-35_s-4","shiji_ch-2_p-35_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/shiji/zh"}]}],"sentences":[{"id":"shiji_ch-1_p-1_s-1","passageId":"shiji_ch-1_p-1","order":1,"canonicalText":"黃帝者，少典之子，姓公孫，名曰軒轅。","chunks":[["黃帝者，少典之子，姓公孫，名曰軒轅。","zh-Hant"]]},{"id":"shiji_ch-1_p-1_s-2","passageId":"shiji_ch-1_p-1","order":2,"canonicalText":"生而神靈，弱而能言，幼而徇齊，長而敦敏，成而聰明。","chunks":[["生而神靈，弱而能言，幼而徇齊，長而敦敏，成而聰明。","zh-Hant"]]},{"id":"shiji_ch-1_p-2_s-1","passageId":"shiji_ch-1_p-2","order":1,"canonicalText":"軒轅之時，神農氏世衰。","chunks":[["軒轅之時，神農氏世衰。","zh-Hant"]]},{"id":"shiji_ch-1_p-2_s-2","passageId":"shiji_ch-1_p-2","order":2,"canonicalText":"諸侯相侵伐，暴虐百姓，而神農氏弗能征。","chunks":[["諸侯相侵伐，暴虐百姓，而神農氏弗能征。","zh-Hant"]]},{"id":"shiji_ch-1_p-2_s-3","passageId":"shiji_ch-1_p-2","order":3,"canonicalText":"於是軒轅乃習用干戈，以征不享，諸侯咸來賓從。","chunks":[["於是軒轅乃習用干戈，以征不享，諸侯咸來賓從。","zh-Hant"]]},{"id":"shiji_ch-1_p-2_s-4","passageId":"shiji_ch-1_p-2","order":4,"canonicalText":"而蚩尤最為暴，莫能伐。","chunks":[["而蚩尤最為暴，莫能伐。","zh-Hant"]]},{"id":"shiji_ch-1_p-2_s-5","passageId":"shiji_ch-1_p-2","order":5,"canonicalText":"炎帝欲侵陵諸侯，諸侯咸歸軒轅。","chunks":[["炎帝欲侵陵諸侯，諸侯咸歸軒轅。","zh-Hant"]]},{"id":"shiji_ch-1_p-2_s-6","passageId":"shiji_ch-1_p-2","order":6,"canonicalText":"軒轅乃修德振兵，治五氣，藝五種，撫萬民，度四方，教熊羆貔貅貙虎，以與炎帝戰於阪泉之野。","chunks":[["軒轅乃修德振兵，治五氣，藝五種，撫萬民，度四方，教熊羆貔貅貙虎，以與炎帝戰於阪泉之野。","zh-Hant"]]},{"id":"shiji_ch-1_p-2_s-7","passageId":"shiji_ch-1_p-2","order":7,"canonicalText":"三戰然後得其志。","chunks":[["三戰然後得其志。","zh-Hant"]]},{"id":"shiji_ch-1_p-2_s-8","passageId":"shiji_ch-1_p-2","order":8,"canonicalText":"蚩尤作亂，不用帝命。","chunks":[["蚩尤作亂，不用帝命。","zh-Hant"]]},{"id":"shiji_ch-1_p-2_s-9","passageId":"shiji_ch-1_p-2","order":9,"canonicalText":"於是黃帝乃徵師諸侯，與蚩尤戰於涿鹿之野，遂禽殺蚩尤。","chunks":[["於是黃帝乃徵師諸侯，與蚩尤戰於涿鹿之野，遂禽殺蚩尤。","zh-Hant"]]},{"id":"shiji_ch-1_p-2_s-10","passageId":"shiji_ch-1_p-2","order":10,"canonicalText":"而諸侯咸尊軒轅為天子，代神農氏，是為黃帝。","chunks":[["而諸侯咸尊軒轅為天子，代神農氏，是為黃帝。","zh-Hant"]]},{"id":"shiji_ch-1_p-2_s-11","passageId":"shiji_ch-1_p-2","order":11,"canonicalText":"天下有不順者，黃帝從而征之，平者去之，披山通道，未嘗寧居。","chunks":[["天下有不順者，黃帝從而征之，平者去之，披山通道，未嘗寧居。","zh-Hant"]]},{"id":"shiji_ch-1_p-3_s-1","passageId":"shiji_ch-1_p-3","order":1,"canonicalText":"東至于海，登丸山，及岱宗。","chunks":[["東至于海，登丸山，及岱宗。","zh-Hant"]]},{"id":"shiji_ch-1_p-3_s-2","passageId":"shiji_ch-1_p-3","order":2,"canonicalText":"西至于空桐，登雞頭。","chunks":[["西至于空桐，登雞頭。","zh-Hant"]]},{"id":"shiji_ch-1_p-3_s-3","passageId":"shiji_ch-1_p-3","order":3,"canonicalText":"南至于江，登熊、湘。","chunks":[["南至于江，登熊、湘。","zh-Hant"]]},{"id":"shiji_ch-1_p-3_s-4","passageId":"shiji_ch-1_p-3","order":4,"canonicalText":"北逐葷粥，合符釜山，而邑于涿鹿之阿。","chunks":[["北逐葷粥，合符釜山，而邑于涿鹿之阿。","zh-Hant"]]},{"id":"shiji_ch-1_p-3_s-5","passageId":"shiji_ch-1_p-3","order":5,"canonicalText":"遷徙往來無常處，以師兵為營衛。","chunks":[["遷徙往來無常處，以師兵為營衛。","zh-Hant"]]},{"id":"shiji_ch-1_p-3_s-6","passageId":"shiji_ch-1_p-3","order":6,"canonicalText":"官名皆以雲命，為雲師。","chunks":[["官名皆以雲命，為雲師。","zh-Hant"]]},{"id":"shiji_ch-1_p-3_s-7","passageId":"shiji_ch-1_p-3","order":7,"canonicalText":"置左右大監，監于萬國。","chunks":[["置左右大監，監于萬國。","zh-Hant"]]},{"id":"shiji_ch-1_p-3_s-8","passageId":"shiji_ch-1_p-3","order":8,"canonicalText":"萬國和，而鬼神山川封禪與為多焉。","chunks":[["萬國和，而鬼神山川封禪與為多焉。","zh-Hant"]]},{"id":"shiji_ch-1_p-3_s-9","passageId":"shiji_ch-1_p-3","order":9,"canonicalText":"獲寶鼎，迎日推筴。","chunks":[["獲寶鼎，迎日推筴。","zh-Hant"]]},{"id":"shiji_ch-1_p-3_s-10","passageId":"shiji_ch-1_p-3","order":10,"canonicalText":"舉風后、力牧、常先、大鴻以治民。","chunks":[["舉風后、力牧、常先、大鴻以治民。","zh-Hant"]]},{"id":"shiji_ch-1_p-3_s-11","passageId":"shiji_ch-1_p-3","order":11,"canonicalText":"順天地之紀，幽明之占，死生之說，存亡之難。","chunks":[["順天地之紀，幽明之占，死生之說，存亡之難。","zh-Hant"]]},{"id":"shiji_ch-1_p-3_s-12","passageId":"shiji_ch-1_p-3","order":12,"canonicalText":"時播百穀草木，淳化鳥獸蟲蛾，旁羅日月星辰水波土石金玉，勞勤心力耳目，節用水火材物。","chunks":[["時播百穀草木，淳化鳥獸蟲蛾，旁羅日月星辰水波土石金玉，勞勤心力耳目，節用水火材物。","zh-Hant"]]},{"id":"shiji_ch-1_p-3_s-13","passageId":"shiji_ch-1_p-3","order":13,"canonicalText":"有土德之瑞，故號黃帝。","chunks":[["有土德之瑞，故號黃帝。","zh-Hant"]]},{"id":"shiji_ch-1_p-4_s-1","passageId":"shiji_ch-1_p-4","order":1,"canonicalText":"黃帝二十五子，其得姓者十四人。","chunks":[["黃帝二十五子，其得姓者十四人。","zh-Hant"]]},{"id":"shiji_ch-1_p-5_s-1","passageId":"shiji_ch-1_p-5","order":1,"canonicalText":"黃帝居于軒轅之丘，而娶于西陵之女，是為嫘祖為黃帝正妃，生二子，其後皆有天下：其一曰玄囂，是為青陽，青陽降居江水；","chunks":[["黃帝居于軒轅之丘，而娶于西陵之女，是為嫘祖為黃帝正妃，生二子，其後皆有天下：其一曰玄囂，是為青陽，青陽降居江水；","zh-Hant"]]},{"id":"shiji_ch-1_p-5_s-2","passageId":"shiji_ch-1_p-5","order":2,"canonicalText":"其二曰昌意，降居若水。","chunks":[["其二曰昌意，降居若水。","zh-Hant"]]},{"id":"shiji_ch-1_p-5_s-3","passageId":"shiji_ch-1_p-5","order":3,"canonicalText":"昌意娶蜀山氏女，曰昌仆，生高陽，高陽有聖德焉。","chunks":[["昌意娶蜀山氏女，曰昌仆，生高陽，高陽有聖德焉。","zh-Hant"]]},{"id":"shiji_ch-1_p-5_s-4","passageId":"shiji_ch-1_p-5","order":4,"canonicalText":"黃帝崩，葬橋山。","chunks":[["黃帝崩，葬橋山。","zh-Hant"]]},{"id":"shiji_ch-1_p-5_s-5","passageId":"shiji_ch-1_p-5","order":5,"canonicalText":"其孫昌意之子高陽立，是為帝顓頊也。","chunks":[["其孫昌意之子高陽立，是為帝顓頊也。","zh-Hant"]]},{"id":"shiji_ch-1_p-6_s-1","passageId":"shiji_ch-1_p-6","order":1,"canonicalText":"帝顓頊高陽者，黃帝之孫而昌意之子也。","chunks":[["帝顓頊高陽者，黃帝之孫而昌意之子也。","zh-Hant"]]},{"id":"shiji_ch-1_p-6_s-2","passageId":"shiji_ch-1_p-6","order":2,"canonicalText":"靜淵以有謀，疏通而知事；","chunks":[["靜淵以有謀，疏通而知事；","zh-Hant"]]},{"id":"shiji_ch-1_p-6_s-3","passageId":"shiji_ch-1_p-6","order":3,"canonicalText":"養材以任地，載時以象天，依鬼神以制義，治氣以教化，絜誠以祭祀。","chunks":[["養材以任地，載時以象天，依鬼神以制義，治氣以教化，絜誠以祭祀。","zh-Hant"]]},{"id":"shiji_ch-1_p-6_s-4","passageId":"shiji_ch-1_p-6","order":4,"canonicalText":"北至于幽陵，南至于交阯，西至于流沙，東至于蟠木。","chunks":[["北至于幽陵，南至于交阯，西至于流沙，東至于蟠木。","zh-Hant"]]},{"id":"shiji_ch-1_p-6_s-5","passageId":"shiji_ch-1_p-6","order":5,"canonicalText":"動靜之物，大小之神，日月所照，莫不砥屬。","chunks":[["動靜之物，大小之神，日月所照，莫不砥屬。","zh-Hant"]]},{"id":"shiji_ch-1_p-7_s-1","passageId":"shiji_ch-1_p-7","order":1,"canonicalText":"帝顓頊生子曰窮蟬。","chunks":[["帝顓頊生子曰窮蟬。","zh-Hant"]]},{"id":"shiji_ch-1_p-7_s-2","passageId":"shiji_ch-1_p-7","order":2,"canonicalText":"顓頊崩，而玄囂之孫高辛立，是為帝嚳。","chunks":[["顓頊崩，而玄囂之孫高辛立，是為帝嚳。","zh-Hant"]]},{"id":"shiji_ch-1_p-8_s-1","passageId":"shiji_ch-1_p-8","order":1,"canonicalText":"帝嚳高辛者，黃帝之曾孫也。","chunks":[["帝嚳高辛者，黃帝之曾孫也。","zh-Hant"]]},{"id":"shiji_ch-1_p-8_s-2","passageId":"shiji_ch-1_p-8","order":2,"canonicalText":"高辛父曰蟜極，蟜極父曰玄囂，玄囂父曰黃帝。","chunks":[["高辛父曰蟜極，蟜極父曰玄囂，玄囂父曰黃帝。","zh-Hant"]]},{"id":"shiji_ch-1_p-8_s-3","passageId":"shiji_ch-1_p-8","order":3,"canonicalText":"自玄囂與蟜極皆不得在位，至高辛即帝位。","chunks":[["自玄囂與蟜極皆不得在位，至高辛即帝位。","zh-Hant"]]},{"id":"shiji_ch-1_p-8_s-4","passageId":"shiji_ch-1_p-8","order":4,"canonicalText":"高辛於顓頊為族子。","chunks":[["高辛於顓頊為族子。","zh-Hant"]]},{"id":"shiji_ch-1_p-9_s-1","passageId":"shiji_ch-1_p-9","order":1,"canonicalText":"高辛生而神靈，自言其名。","chunks":[["高辛生而神靈，自言其名。","zh-Hant"]]},{"id":"shiji_ch-1_p-9_s-2","passageId":"shiji_ch-1_p-9","order":2,"canonicalText":"普施利物，不於其身。","chunks":[["普施利物，不於其身。","zh-Hant"]]},{"id":"shiji_ch-1_p-9_s-3","passageId":"shiji_ch-1_p-9","order":3,"canonicalText":"聰以知遠，明以察微。","chunks":[["聰以知遠，明以察微。","zh-Hant"]]},{"id":"shiji_ch-1_p-9_s-4","passageId":"shiji_ch-1_p-9","order":4,"canonicalText":"順天之義，知民之急。","chunks":[["順天之義，知民之急。","zh-Hant"]]},{"id":"shiji_ch-1_p-9_s-5","passageId":"shiji_ch-1_p-9","order":5,"canonicalText":"仁而威，惠而信，修身而天下服。","chunks":[["仁而威，惠而信，修身而天下服。","zh-Hant"]]},{"id":"shiji_ch-1_p-9_s-6","passageId":"shiji_ch-1_p-9","order":6,"canonicalText":"取地之財而節用之，撫教萬民而利誨之，歷日月而迎送之，明鬼神而敬事之。","chunks":[["取地之財而節用之，撫教萬民而利誨之，歷日月而迎送之，明鬼神而敬事之。","zh-Hant"]]},{"id":"shiji_ch-1_p-9_s-7","passageId":"shiji_ch-1_p-9","order":7,"canonicalText":"其色郁郁，其德嶷嶷。","chunks":[["其色郁郁，其德嶷嶷。","zh-Hant"]]},{"id":"shiji_ch-1_p-9_s-8","passageId":"shiji_ch-1_p-9","order":8,"canonicalText":"其動也時，其服也士。","chunks":[["其動也時，其服也士。","zh-Hant"]]},{"id":"shiji_ch-1_p-9_s-9","passageId":"shiji_ch-1_p-9","order":9,"canonicalText":"帝嚳溉執中而遍天下，日月所照，風雨所至，莫不從服。","chunks":[["帝嚳溉執中而遍天下，日月所照，風雨所至，莫不從服。","zh-Hant"]]},{"id":"shiji_ch-1_p-10_s-1","passageId":"shiji_ch-1_p-10","order":1,"canonicalText":"帝嚳娶陳鋒氏女，生放勛。","chunks":[["帝嚳娶陳鋒氏女，生放勛。","zh-Hant"]]},{"id":"shiji_ch-1_p-10_s-2","passageId":"shiji_ch-1_p-10","order":2,"canonicalText":"娶娵訾氏女，生摯。","chunks":[["娶娵訾氏女，生摯。","zh-Hant"]]},{"id":"shiji_ch-1_p-10_s-3","passageId":"shiji_ch-1_p-10","order":3,"canonicalText":"帝嚳崩，而摯代立。","chunks":[["帝嚳崩，而摯代立。","zh-Hant"]]},{"id":"shiji_ch-1_p-10_s-4","passageId":"shiji_ch-1_p-10","order":4,"canonicalText":"帝摯立，不善（崩），而弟放勛立，是為帝堯。","chunks":[["帝摯立，不善（崩），而弟放勛立，是為帝堯。","zh-Hant"]]},{"id":"shiji_ch-1_p-11_s-1","passageId":"shiji_ch-1_p-11","order":1,"canonicalText":"帝堯者，放勛。","chunks":[["帝堯者，放勛。","zh-Hant"]]},{"id":"shiji_ch-1_p-11_s-2","passageId":"shiji_ch-1_p-11","order":2,"canonicalText":"其仁如天，其知如神。","chunks":[["其仁如天，其知如神。","zh-Hant"]]},{"id":"shiji_ch-1_p-11_s-3","passageId":"shiji_ch-1_p-11","order":3,"canonicalText":"就之如日，望之如雲。","chunks":[["就之如日，望之如雲。","zh-Hant"]]},{"id":"shiji_ch-1_p-11_s-4","passageId":"shiji_ch-1_p-11","order":4,"canonicalText":"富而不驕，貴而不舒。","chunks":[["富而不驕，貴而不舒。","zh-Hant"]]},{"id":"shiji_ch-1_p-11_s-5","passageId":"shiji_ch-1_p-11","order":5,"canonicalText":"黃收純衣，彤車乘白馬。","chunks":[["黃收純衣，彤車乘白馬。","zh-Hant"]]},{"id":"shiji_ch-1_p-11_s-6","passageId":"shiji_ch-1_p-11","order":6,"canonicalText":"能明馴德，以親九族。","chunks":[["能明馴德，以親九族。","zh-Hant"]]},{"id":"shiji_ch-1_p-11_s-7","passageId":"shiji_ch-1_p-11","order":7,"canonicalText":"九族既睦，便章百姓。","chunks":[["九族既睦，便章百姓。","zh-Hant"]]},{"id":"shiji_ch-1_p-11_s-8","passageId":"shiji_ch-1_p-11","order":8,"canonicalText":"百姓昭明，合和萬國。","chunks":[["百姓昭明，合和萬國。","zh-Hant"]]},{"id":"shiji_ch-1_p-12_s-1","passageId":"shiji_ch-1_p-12","order":1,"canonicalText":"乃命羲、和，敬順昊天，數法日月星辰，敬授民時。","chunks":[["乃命羲、和，敬順昊天，數法日月星辰，敬授民時。","zh-Hant"]]},{"id":"shiji_ch-1_p-12_s-2","passageId":"shiji_ch-1_p-12","order":2,"canonicalText":"分命羲仲，居郁夷，曰暘谷。","chunks":[["分命羲仲，居郁夷，曰暘谷。","zh-Hant"]]},{"id":"shiji_ch-1_p-12_s-3","passageId":"shiji_ch-1_p-12","order":3,"canonicalText":"敬道日出，便程東作。","chunks":[["敬道日出，便程東作。","zh-Hant"]]},{"id":"shiji_ch-1_p-12_s-4","passageId":"shiji_ch-1_p-12","order":4,"canonicalText":"日中，星鳥，以殷中春。","chunks":[["日中，星鳥，以殷中春。","zh-Hant"]]},{"id":"shiji_ch-1_p-12_s-5","passageId":"shiji_ch-1_p-12","order":5,"canonicalText":"其民析，鳥獸字微。","chunks":[["其民析，鳥獸字微。","zh-Hant"]]},{"id":"shiji_ch-1_p-12_s-6","passageId":"shiji_ch-1_p-12","order":6,"canonicalText":"申命羲叔，居南交。","chunks":[["申命羲叔，居南交。","zh-Hant"]]},{"id":"shiji_ch-1_p-12_s-7","passageId":"shiji_ch-1_p-12","order":7,"canonicalText":"便程南為，敬致。","chunks":[["便程南為，敬致。","zh-Hant"]]},{"id":"shiji_ch-1_p-12_s-8","passageId":"shiji_ch-1_p-12","order":8,"canonicalText":"日永，星火，以正中夏。","chunks":[["日永，星火，以正中夏。","zh-Hant"]]},{"id":"shiji_ch-1_p-12_s-9","passageId":"shiji_ch-1_p-12","order":9,"canonicalText":"其民因，鳥獸希革。","chunks":[["其民因，鳥獸希革。","zh-Hant"]]},{"id":"shiji_ch-1_p-12_s-10","passageId":"shiji_ch-1_p-12","order":10,"canonicalText":"申命和仲，居西土，曰昧谷。","chunks":[["申命和仲，居西土，曰昧谷。","zh-Hant"]]},{"id":"shiji_ch-1_p-12_s-11","passageId":"shiji_ch-1_p-12","order":11,"canonicalText":"敬道日入，便程西成。","chunks":[["敬道日入，便程西成。","zh-Hant"]]},{"id":"shiji_ch-1_p-12_s-12","passageId":"shiji_ch-1_p-12","order":12,"canonicalText":"夜中，星虛，以正中秋。","chunks":[["夜中，星虛，以正中秋。","zh-Hant"]]},{"id":"shiji_ch-1_p-12_s-13","passageId":"shiji_ch-1_p-12","order":13,"canonicalText":"其民夷易，鳥獸毛毨。","chunks":[["其民夷易，鳥獸毛毨。","zh-Hant"]]},{"id":"shiji_ch-1_p-12_s-14","passageId":"shiji_ch-1_p-12","order":14,"canonicalText":"申命和叔；","chunks":[["申命和叔；","zh-Hant"]]},{"id":"shiji_ch-1_p-12_s-15","passageId":"shiji_ch-1_p-12","order":15,"canonicalText":"居北方，曰幽都。","chunks":[["居北方，曰幽都。","zh-Hant"]]},{"id":"shiji_ch-1_p-12_s-16","passageId":"shiji_ch-1_p-12","order":16,"canonicalText":"便在伏物。","chunks":[["便在伏物。","zh-Hant"]]},{"id":"shiji_ch-1_p-12_s-17","passageId":"shiji_ch-1_p-12","order":17,"canonicalText":"日短，星昴，以正中冬。","chunks":[["日短，星昴，以正中冬。","zh-Hant"]]},{"id":"shiji_ch-1_p-12_s-18","passageId":"shiji_ch-1_p-12","order":18,"canonicalText":"其民燠，鳥獸氄毛。","chunks":[["其民燠，鳥獸氄毛。","zh-Hant"]]},{"id":"shiji_ch-1_p-12_s-19","passageId":"shiji_ch-1_p-12","order":19,"canonicalText":"歲三百六十六日，以閏月正四時。","chunks":[["歲三百六十六日，以閏月正四時。","zh-Hant"]]},{"id":"shiji_ch-1_p-12_s-20","passageId":"shiji_ch-1_p-12","order":20,"canonicalText":"信飭百官，眾功皆興。","chunks":[["信飭百官，眾功皆興。","zh-Hant"]]},{"id":"shiji_ch-1_p-13_s-1","passageId":"shiji_ch-1_p-13","order":1,"canonicalText":"堯曰：「誰可順此事？","chunks":[["堯曰：「誰可順此事？","zh-Hant"]]},{"id":"shiji_ch-1_p-13_s-2","passageId":"shiji_ch-1_p-13","order":2,"canonicalText":"」放齊曰：「嗣子丹朱開明。","chunks":[["」放齊曰：「嗣子丹朱開明。","zh-Hant"]]},{"id":"shiji_ch-1_p-13_s-3","passageId":"shiji_ch-1_p-13","order":3,"canonicalText":"」堯曰：「吁！","chunks":[["」堯曰：「吁！","zh-Hant"]]},{"id":"shiji_ch-1_p-13_s-4","passageId":"shiji_ch-1_p-13","order":4,"canonicalText":"頑凶，不用。","chunks":[["頑凶，不用。","zh-Hant"]]},{"id":"shiji_ch-1_p-13_s-5","passageId":"shiji_ch-1_p-13","order":5,"canonicalText":"」堯又曰：「誰可者？","chunks":[["」堯又曰：「誰可者？","zh-Hant"]]},{"id":"shiji_ch-1_p-13_s-6","passageId":"shiji_ch-1_p-13","order":6,"canonicalText":"」讙兜曰：「共工旁聚布功，可用。","chunks":[["」讙兜曰：「共工旁聚布功，可用。","zh-Hant"]]},{"id":"shiji_ch-1_p-13_s-7","passageId":"shiji_ch-1_p-13","order":7,"canonicalText":"」堯曰：「共工善言，其用僻，似恭漫天，不可。","chunks":[["」堯曰：「共工善言，其用僻，似恭漫天，不可。","zh-Hant"]]},{"id":"shiji_ch-1_p-13_s-8","passageId":"shiji_ch-1_p-13","order":8,"canonicalText":"」堯又曰：「嗟，四嶽，湯湯洪水滔天，浩浩懷山襄陵，下民其憂，有能使治者？","chunks":[["」堯又曰：「嗟，四嶽，湯湯洪水滔天，浩浩懷山襄陵，下民其憂，有能使治者？","zh-Hant"]]},{"id":"shiji_ch-1_p-13_s-9","passageId":"shiji_ch-1_p-13","order":9,"canonicalText":"」皆曰鯀可。","chunks":[["」皆曰鯀可。","zh-Hant"]]},{"id":"shiji_ch-1_p-13_s-10","passageId":"shiji_ch-1_p-13","order":10,"canonicalText":"堯曰：「鯀負命毀族，不可。","chunks":[["堯曰：「鯀負命毀族，不可。","zh-Hant"]]},{"id":"shiji_ch-1_p-13_s-11","passageId":"shiji_ch-1_p-13","order":11,"canonicalText":"」嶽曰：「異哉，試不可用而已。","chunks":[["」嶽曰：「異哉，試不可用而已。","zh-Hant"]]},{"id":"shiji_ch-1_p-13_s-12","passageId":"shiji_ch-1_p-13","order":12,"canonicalText":"」堯於是聽嶽用鯀。","chunks":[["」堯於是聽嶽用鯀。","zh-Hant"]]},{"id":"shiji_ch-1_p-13_s-13","passageId":"shiji_ch-1_p-13","order":13,"canonicalText":"九歲，功用不成。","chunks":[["九歲，功用不成。","zh-Hant"]]},{"id":"shiji_ch-1_p-14_s-1","passageId":"shiji_ch-1_p-14","order":1,"canonicalText":"堯曰：「嗟！","chunks":[["堯曰：「嗟！","zh-Hant"]]},{"id":"shiji_ch-1_p-14_s-2","passageId":"shiji_ch-1_p-14","order":2,"canonicalText":"四嶽：朕在位七十載，汝能庸命，踐朕位？","chunks":[["四嶽：朕在位七十載，汝能庸命，踐朕位？","zh-Hant"]]},{"id":"shiji_ch-1_p-14_s-3","passageId":"shiji_ch-1_p-14","order":3,"canonicalText":"」嶽應曰：「鄙德忝帝位。","chunks":[["」嶽應曰：「鄙德忝帝位。","zh-Hant"]]},{"id":"shiji_ch-1_p-14_s-4","passageId":"shiji_ch-1_p-14","order":4,"canonicalText":"」堯曰：「悉舉貴戚及疏遠隱匿者。","chunks":[["」堯曰：「悉舉貴戚及疏遠隱匿者。","zh-Hant"]]},{"id":"shiji_ch-1_p-14_s-5","passageId":"shiji_ch-1_p-14","order":5,"canonicalText":"」眾皆言於堯曰：「有矜在民閒，曰虞舜。","chunks":[["」眾皆言於堯曰：「有矜在民閒，曰虞舜。","zh-Hant"]]},{"id":"shiji_ch-1_p-14_s-6","passageId":"shiji_ch-1_p-14","order":6,"canonicalText":"」堯曰：「然，朕聞之。","chunks":[["」堯曰：「然，朕聞之。","zh-Hant"]]},{"id":"shiji_ch-1_p-14_s-7","passageId":"shiji_ch-1_p-14","order":7,"canonicalText":"其何如？","chunks":[["其何如？","zh-Hant"]]},{"id":"shiji_ch-1_p-14_s-8","passageId":"shiji_ch-1_p-14","order":8,"canonicalText":"」嶽曰：「盲者子。","chunks":[["」嶽曰：「盲者子。","zh-Hant"]]},{"id":"shiji_ch-1_p-14_s-9","passageId":"shiji_ch-1_p-14","order":9,"canonicalText":"父頑，母嚚，弟傲，能和以孝，烝烝治，不至姦。","chunks":[["父頑，母嚚，弟傲，能和以孝，烝烝治，不至姦。","zh-Hant"]]},{"id":"shiji_ch-1_p-14_s-10","passageId":"shiji_ch-1_p-14","order":10,"canonicalText":"」堯曰：「吾其試哉。","chunks":[["」堯曰：「吾其試哉。","zh-Hant"]]},{"id":"shiji_ch-1_p-14_s-11","passageId":"shiji_ch-1_p-14","order":11,"canonicalText":"」於是堯妻之二女，觀其德於二女。","chunks":[["」於是堯妻之二女，觀其德於二女。","zh-Hant"]]},{"id":"shiji_ch-1_p-14_s-12","passageId":"shiji_ch-1_p-14","order":12,"canonicalText":"舜飭下二女於媯汭，如婦禮。","chunks":[["舜飭下二女於媯汭，如婦禮。","zh-Hant"]]},{"id":"shiji_ch-1_p-15_s-1","passageId":"shiji_ch-1_p-15","order":1,"canonicalText":"堯善之，乃使舜慎和五典，五典能從。","chunks":[["堯善之，乃使舜慎和五典，五典能從。","zh-Hant"]]},{"id":"shiji_ch-1_p-15_s-2","passageId":"shiji_ch-1_p-15","order":2,"canonicalText":"乃遍入百官，百官時序。","chunks":[["乃遍入百官，百官時序。","zh-Hant"]]},{"id":"shiji_ch-1_p-15_s-3","passageId":"shiji_ch-1_p-15","order":3,"canonicalText":"賓於四門，四門穆穆，諸侯遠方賓客皆敬。","chunks":[["賓於四門，四門穆穆，諸侯遠方賓客皆敬。","zh-Hant"]]},{"id":"shiji_ch-1_p-15_s-4","passageId":"shiji_ch-1_p-15","order":4,"canonicalText":"堯使舜入山林川澤，暴風雷雨，舜行不迷。","chunks":[["堯使舜入山林川澤，暴風雷雨，舜行不迷。","zh-Hant"]]},{"id":"shiji_ch-1_p-15_s-5","passageId":"shiji_ch-1_p-15","order":5,"canonicalText":"堯以為聖，召舜曰：「女謀事至而言可績，三年矣。","chunks":[["堯以為聖，召舜曰：「女謀事至而言可績，三年矣。","zh-Hant"]]},{"id":"shiji_ch-1_p-15_s-6","passageId":"shiji_ch-1_p-15","order":6,"canonicalText":"女登帝位。","chunks":[["女登帝位。","zh-Hant"]]},{"id":"shiji_ch-1_p-15_s-7","passageId":"shiji_ch-1_p-15","order":7,"canonicalText":"」舜讓於德不懌。","chunks":[["」舜讓於德不懌。","zh-Hant"]]},{"id":"shiji_ch-1_p-15_s-8","passageId":"shiji_ch-1_p-15","order":8,"canonicalText":"正月上日，舜受終於文祖。","chunks":[["正月上日，舜受終於文祖。","zh-Hant"]]},{"id":"shiji_ch-1_p-15_s-9","passageId":"shiji_ch-1_p-15","order":9,"canonicalText":"文祖者，堯大祖也。","chunks":[["文祖者，堯大祖也。","zh-Hant"]]},{"id":"shiji_ch-1_p-16_s-1","passageId":"shiji_ch-1_p-16","order":1,"canonicalText":"於是帝堯老，命舜攝行天子之政，以觀天命。","chunks":[["於是帝堯老，命舜攝行天子之政，以觀天命。","zh-Hant"]]},{"id":"shiji_ch-1_p-16_s-2","passageId":"shiji_ch-1_p-16","order":2,"canonicalText":"舜乃在璿璣玉衡，以齊七政。","chunks":[["舜乃在璿璣玉衡，以齊七政。","zh-Hant"]]},{"id":"shiji_ch-1_p-16_s-3","passageId":"shiji_ch-1_p-16","order":3,"canonicalText":"遂類于上帝，禋于六宗，望于山川，辯于群神。","chunks":[["遂類于上帝，禋于六宗，望于山川，辯于群神。","zh-Hant"]]},{"id":"shiji_ch-1_p-16_s-4","passageId":"shiji_ch-1_p-16","order":4,"canonicalText":"揖五瑞，擇吉月日，見四嶽諸牧，班瑞。","chunks":[["揖五瑞，擇吉月日，見四嶽諸牧，班瑞。","zh-Hant"]]},{"id":"shiji_ch-1_p-16_s-5","passageId":"shiji_ch-1_p-16","order":5,"canonicalText":"歲二月，東巡狩，至於岱宗，祡，望秩於山川。","chunks":[["歲二月，東巡狩，至於岱宗，祡，望秩於山川。","zh-Hant"]]},{"id":"shiji_ch-1_p-16_s-6","passageId":"shiji_ch-1_p-16","order":6,"canonicalText":"遂見東方君長，合時月正日，同律度量衡，修五禮五玉三帛二生一死為摯，如五器，卒乃復。","chunks":[["遂見東方君長，合時月正日，同律度量衡，修五禮五玉三帛二生一死為摯，如五器，卒乃復。","zh-Hant"]]},{"id":"shiji_ch-1_p-16_s-7","passageId":"shiji_ch-1_p-16","order":7,"canonicalText":"五月，南巡狩；","chunks":[["五月，南巡狩；","zh-Hant"]]},{"id":"shiji_ch-1_p-16_s-8","passageId":"shiji_ch-1_p-16","order":8,"canonicalText":"八月，西巡狩；","chunks":[["八月，西巡狩；","zh-Hant"]]},{"id":"shiji_ch-1_p-16_s-9","passageId":"shiji_ch-1_p-16","order":9,"canonicalText":"十一月，北巡狩：皆如初。","chunks":[["十一月，北巡狩：皆如初。","zh-Hant"]]},{"id":"shiji_ch-1_p-16_s-10","passageId":"shiji_ch-1_p-16","order":10,"canonicalText":"歸，至于祖禰廟，用特牛禮。","chunks":[["歸，至于祖禰廟，用特牛禮。","zh-Hant"]]},{"id":"shiji_ch-1_p-16_s-11","passageId":"shiji_ch-1_p-16","order":11,"canonicalText":"五歲一巡狩，群后四朝。","chunks":[["五歲一巡狩，群后四朝。","zh-Hant"]]},{"id":"shiji_ch-1_p-16_s-12","passageId":"shiji_ch-1_p-16","order":12,"canonicalText":"遍告以言，明試以功，車服以庸。","chunks":[["遍告以言，明試以功，車服以庸。","zh-Hant"]]},{"id":"shiji_ch-1_p-16_s-13","passageId":"shiji_ch-1_p-16","order":13,"canonicalText":"肇十有二州，決川。","chunks":[["肇十有二州，決川。","zh-Hant"]]},{"id":"shiji_ch-1_p-16_s-14","passageId":"shiji_ch-1_p-16","order":14,"canonicalText":"象以典刑，流宥五刑，鞭作官刑，撲作教刑，金作贖刑。","chunks":[["象以典刑，流宥五刑，鞭作官刑，撲作教刑，金作贖刑。","zh-Hant"]]},{"id":"shiji_ch-1_p-16_s-15","passageId":"shiji_ch-1_p-16","order":15,"canonicalText":"眚災過，赦；","chunks":[["眚災過，赦；","zh-Hant"]]},{"id":"shiji_ch-1_p-16_s-16","passageId":"shiji_ch-1_p-16","order":16,"canonicalText":"怙終賊，刑。","chunks":[["怙終賊，刑。","zh-Hant"]]},{"id":"shiji_ch-1_p-16_s-17","passageId":"shiji_ch-1_p-16","order":17,"canonicalText":"欽哉，欽哉，惟刑之靜哉！","chunks":[["欽哉，欽哉，惟刑之靜哉！","zh-Hant"]]},{"id":"shiji_ch-1_p-17_s-1","passageId":"shiji_ch-1_p-17","order":1,"canonicalText":"讙兜進言共工，堯曰不可而試之工師，共工果淫辟。","chunks":[["讙兜進言共工，堯曰不可而試之工師，共工果淫辟。","zh-Hant"]]},{"id":"shiji_ch-1_p-17_s-2","passageId":"shiji_ch-1_p-17","order":2,"canonicalText":"四嶽舉鯀治鴻水，堯以為不可，嶽彊請試之，試之而無功，故百姓不便。","chunks":[["四嶽舉鯀治鴻水，堯以為不可，嶽彊請試之，試之而無功，故百姓不便。","zh-Hant"]]},{"id":"shiji_ch-1_p-17_s-3","passageId":"shiji_ch-1_p-17","order":3,"canonicalText":"三苗在江淮、荊州數為亂。","chunks":[["三苗在江淮、荊州數為亂。","zh-Hant"]]},{"id":"shiji_ch-1_p-17_s-4","passageId":"shiji_ch-1_p-17","order":4,"canonicalText":"於是舜歸而言於帝，請流共工於幽陵，以變北狄；","chunks":[["於是舜歸而言於帝，請流共工於幽陵，以變北狄；","zh-Hant"]]},{"id":"shiji_ch-1_p-17_s-5","passageId":"shiji_ch-1_p-17","order":5,"canonicalText":"放讙兜於崇山，以變南蠻；","chunks":[["放讙兜於崇山，以變南蠻；","zh-Hant"]]},{"id":"shiji_ch-1_p-17_s-6","passageId":"shiji_ch-1_p-17","order":6,"canonicalText":"遷三苗於三危，以變西戎；","chunks":[["遷三苗於三危，以變西戎；","zh-Hant"]]},{"id":"shiji_ch-1_p-17_s-7","passageId":"shiji_ch-1_p-17","order":7,"canonicalText":"殛鯀於羽山，以變東夷：四罪而天下咸服。","chunks":[["殛鯀於羽山，以變東夷：四罪而天下咸服。","zh-Hant"]]},{"id":"shiji_ch-1_p-18_s-1","passageId":"shiji_ch-1_p-18","order":1,"canonicalText":"堯立七十年得舜，二十年而老，令舜攝行天子之政，薦之於天。","chunks":[["堯立七十年得舜，二十年而老，令舜攝行天子之政，薦之於天。","zh-Hant"]]},{"id":"shiji_ch-1_p-18_s-2","passageId":"shiji_ch-1_p-18","order":2,"canonicalText":"堯辟位凡二十八年而崩。","chunks":[["堯辟位凡二十八年而崩。","zh-Hant"]]},{"id":"shiji_ch-1_p-18_s-3","passageId":"shiji_ch-1_p-18","order":3,"canonicalText":"百姓悲哀，如喪父母。","chunks":[["百姓悲哀，如喪父母。","zh-Hant"]]},{"id":"shiji_ch-1_p-18_s-4","passageId":"shiji_ch-1_p-18","order":4,"canonicalText":"三年，四方莫舉樂，以思堯。","chunks":[["三年，四方莫舉樂，以思堯。","zh-Hant"]]},{"id":"shiji_ch-1_p-18_s-5","passageId":"shiji_ch-1_p-18","order":5,"canonicalText":"堯知子丹朱之不肖，不足授天下，於是乃權授舜。","chunks":[["堯知子丹朱之不肖，不足授天下，於是乃權授舜。","zh-Hant"]]},{"id":"shiji_ch-1_p-18_s-6","passageId":"shiji_ch-1_p-18","order":6,"canonicalText":"授舜，則天下得其利而丹朱病；","chunks":[["授舜，則天下得其利而丹朱病；","zh-Hant"]]},{"id":"shiji_ch-1_p-18_s-7","passageId":"shiji_ch-1_p-18","order":7,"canonicalText":"授丹朱，則天下病而丹朱得其利。","chunks":[["授丹朱，則天下病而丹朱得其利。","zh-Hant"]]},{"id":"shiji_ch-1_p-18_s-8","passageId":"shiji_ch-1_p-18","order":8,"canonicalText":"堯曰：「終不以天下之病而利一人」，而卒授舜以天下。","chunks":[["堯曰：「終不以天下之病而利一人」，而卒授舜以天下。","zh-Hant"]]},{"id":"shiji_ch-1_p-18_s-9","passageId":"shiji_ch-1_p-18","order":9,"canonicalText":"堯崩，三年之喪畢，舜讓辟丹朱於南河之南。","chunks":[["堯崩，三年之喪畢，舜讓辟丹朱於南河之南。","zh-Hant"]]},{"id":"shiji_ch-1_p-18_s-10","passageId":"shiji_ch-1_p-18","order":10,"canonicalText":"諸侯朝覲者不之丹朱而之舜，獄訟者不之丹朱而之舜，謳歌者不謳歌丹朱而謳歌舜。","chunks":[["諸侯朝覲者不之丹朱而之舜，獄訟者不之丹朱而之舜，謳歌者不謳歌丹朱而謳歌舜。","zh-Hant"]]},{"id":"shiji_ch-1_p-18_s-11","passageId":"shiji_ch-1_p-18","order":11,"canonicalText":"舜曰：「天也」，夫而後之中國踐天子位焉，是為帝舜。","chunks":[["舜曰：「天也」，夫而後之中國踐天子位焉，是為帝舜。","zh-Hant"]]},{"id":"shiji_ch-1_p-19_s-1","passageId":"shiji_ch-1_p-19","order":1,"canonicalText":"虞舜者，名曰重華。","chunks":[["虞舜者，名曰重華。","zh-Hant"]]},{"id":"shiji_ch-1_p-19_s-2","passageId":"shiji_ch-1_p-19","order":2,"canonicalText":"重華父曰瞽叟，瞽叟父曰橋牛，橋牛父曰句望，句望父曰敬康，敬康父曰窮蟬，窮蟬父曰帝顓頊，顓頊父曰昌意：以至舜七世矣。","chunks":[["重華父曰瞽叟，瞽叟父曰橋牛，橋牛父曰句望，句望父曰敬康，敬康父曰窮蟬，窮蟬父曰帝顓頊，顓頊父曰昌意：以至舜七世矣。","zh-Hant"]]},{"id":"shiji_ch-1_p-19_s-3","passageId":"shiji_ch-1_p-19","order":3,"canonicalText":"自從窮蟬以至帝舜，皆微為庶人。","chunks":[["自從窮蟬以至帝舜，皆微為庶人。","zh-Hant"]]},{"id":"shiji_ch-1_p-20_s-1","passageId":"shiji_ch-1_p-20","order":1,"canonicalText":"舜父瞽叟盲，而舜母死，瞽叟更娶妻而生象，象傲。","chunks":[["舜父瞽叟盲，而舜母死，瞽叟更娶妻而生象，象傲。","zh-Hant"]]},{"id":"shiji_ch-1_p-20_s-2","passageId":"shiji_ch-1_p-20","order":2,"canonicalText":"瞽叟愛後妻子，常欲殺舜，舜避逃；","chunks":[["瞽叟愛後妻子，常欲殺舜，舜避逃；","zh-Hant"]]},{"id":"shiji_ch-1_p-20_s-3","passageId":"shiji_ch-1_p-20","order":3,"canonicalText":"及有小過，則受罪。","chunks":[["及有小過，則受罪。","zh-Hant"]]},{"id":"shiji_ch-1_p-20_s-4","passageId":"shiji_ch-1_p-20","order":4,"canonicalText":"順事父及後母與弟，日以篤謹，匪有解。","chunks":[["順事父及後母與弟，日以篤謹，匪有解。","zh-Hant"]]},{"id":"shiji_ch-1_p-21_s-1","passageId":"shiji_ch-1_p-21","order":1,"canonicalText":"舜，冀州之人也。","chunks":[["舜，冀州之人也。","zh-Hant"]]},{"id":"shiji_ch-1_p-21_s-2","passageId":"shiji_ch-1_p-21","order":2,"canonicalText":"舜耕歷山，漁雷澤，陶河濱，作什器於壽丘，就時於負夏。","chunks":[["舜耕歷山，漁雷澤，陶河濱，作什器於壽丘，就時於負夏。","zh-Hant"]]},{"id":"shiji_ch-1_p-21_s-3","passageId":"shiji_ch-1_p-21","order":3,"canonicalText":"舜父瞽叟頑，母嚚，弟象傲，皆欲殺舜。","chunks":[["舜父瞽叟頑，母嚚，弟象傲，皆欲殺舜。","zh-Hant"]]},{"id":"shiji_ch-1_p-21_s-4","passageId":"shiji_ch-1_p-21","order":4,"canonicalText":"舜順適不失子道，兄弟孝慈。","chunks":[["舜順適不失子道，兄弟孝慈。","zh-Hant"]]},{"id":"shiji_ch-1_p-21_s-5","passageId":"shiji_ch-1_p-21","order":5,"canonicalText":"欲殺，不可得；","chunks":[["欲殺，不可得；","zh-Hant"]]},{"id":"shiji_ch-1_p-21_s-6","passageId":"shiji_ch-1_p-21","order":6,"canonicalText":"即求，嘗在側。","chunks":[["即求，嘗在側。","zh-Hant"]]},{"id":"shiji_ch-1_p-22_s-1","passageId":"shiji_ch-1_p-22","order":1,"canonicalText":"舜年二十以孝聞。","chunks":[["舜年二十以孝聞。","zh-Hant"]]},{"id":"shiji_ch-1_p-22_s-2","passageId":"shiji_ch-1_p-22","order":2,"canonicalText":"三十而帝堯問可用者，四嶽咸薦虞舜，曰可。","chunks":[["三十而帝堯問可用者，四嶽咸薦虞舜，曰可。","zh-Hant"]]},{"id":"shiji_ch-1_p-22_s-3","passageId":"shiji_ch-1_p-22","order":3,"canonicalText":"於是堯乃以二女妻舜以觀其內，使九男與處以觀其外。","chunks":[["於是堯乃以二女妻舜以觀其內，使九男與處以觀其外。","zh-Hant"]]},{"id":"shiji_ch-1_p-22_s-4","passageId":"shiji_ch-1_p-22","order":4,"canonicalText":"舜居媯汭，內行彌謹。","chunks":[["舜居媯汭，內行彌謹。","zh-Hant"]]},{"id":"shiji_ch-1_p-22_s-5","passageId":"shiji_ch-1_p-22","order":5,"canonicalText":"堯二女不敢以貴驕事舜親戚，甚有婦道。","chunks":[["堯二女不敢以貴驕事舜親戚，甚有婦道。","zh-Hant"]]},{"id":"shiji_ch-1_p-22_s-6","passageId":"shiji_ch-1_p-22","order":6,"canonicalText":"堯九男皆益篤。","chunks":[["堯九男皆益篤。","zh-Hant"]]},{"id":"shiji_ch-1_p-22_s-7","passageId":"shiji_ch-1_p-22","order":7,"canonicalText":"舜耕歷山，歷山之人皆讓畔；","chunks":[["舜耕歷山，歷山之人皆讓畔；","zh-Hant"]]},{"id":"shiji_ch-1_p-22_s-8","passageId":"shiji_ch-1_p-22","order":8,"canonicalText":"漁雷澤，雷澤上人皆讓居；","chunks":[["漁雷澤，雷澤上人皆讓居；","zh-Hant"]]},{"id":"shiji_ch-1_p-22_s-9","passageId":"shiji_ch-1_p-22","order":9,"canonicalText":"陶河濱，河濱器皆不苦窳。","chunks":[["陶河濱，河濱器皆不苦窳。","zh-Hant"]]},{"id":"shiji_ch-1_p-22_s-10","passageId":"shiji_ch-1_p-22","order":10,"canonicalText":"一年而所居成聚，二年成邑，三年成都。","chunks":[["一年而所居成聚，二年成邑，三年成都。","zh-Hant"]]},{"id":"shiji_ch-1_p-22_s-11","passageId":"shiji_ch-1_p-22","order":11,"canonicalText":"堯乃賜舜絺衣，與琴，為筑倉廩，予牛羊。","chunks":[["堯乃賜舜絺衣，與琴，為筑倉廩，予牛羊。","zh-Hant"]]},{"id":"shiji_ch-1_p-22_s-12","passageId":"shiji_ch-1_p-22","order":12,"canonicalText":"瞽叟尚復欲殺之，使舜上涂廩，瞽叟從下縱火焚廩。","chunks":[["瞽叟尚復欲殺之，使舜上涂廩，瞽叟從下縱火焚廩。","zh-Hant"]]},{"id":"shiji_ch-1_p-22_s-13","passageId":"shiji_ch-1_p-22","order":13,"canonicalText":"舜乃以兩笠自捍而下，去，得不死。","chunks":[["舜乃以兩笠自捍而下，去，得不死。","zh-Hant"]]},{"id":"shiji_ch-1_p-22_s-14","passageId":"shiji_ch-1_p-22","order":14,"canonicalText":"後瞽叟又使舜穿井，舜穿井為匿空旁出。","chunks":[["後瞽叟又使舜穿井，舜穿井為匿空旁出。","zh-Hant"]]},{"id":"shiji_ch-1_p-22_s-15","passageId":"shiji_ch-1_p-22","order":15,"canonicalText":"舜既入深，瞽叟與象共下土實井，舜從匿空出，去。","chunks":[["舜既入深，瞽叟與象共下土實井，舜從匿空出，去。","zh-Hant"]]},{"id":"shiji_ch-1_p-22_s-16","passageId":"shiji_ch-1_p-22","order":16,"canonicalText":"瞽叟、象喜，以舜為已死。","chunks":[["瞽叟、象喜，以舜為已死。","zh-Hant"]]},{"id":"shiji_ch-1_p-22_s-17","passageId":"shiji_ch-1_p-22","order":17,"canonicalText":"象曰：「本謀者象。","chunks":[["象曰：「本謀者象。","zh-Hant"]]},{"id":"shiji_ch-1_p-22_s-18","passageId":"shiji_ch-1_p-22","order":18,"canonicalText":"」象與其父母分，於是曰：「舜妻堯二女，與琴，象取之。","chunks":[["」象與其父母分，於是曰：「舜妻堯二女，與琴，象取之。","zh-Hant"]]},{"id":"shiji_ch-1_p-22_s-19","passageId":"shiji_ch-1_p-22","order":19,"canonicalText":"牛羊倉廩予父母。","chunks":[["牛羊倉廩予父母。","zh-Hant"]]},{"id":"shiji_ch-1_p-22_s-20","passageId":"shiji_ch-1_p-22","order":20,"canonicalText":"」象乃止舜宮居，鼓其琴。","chunks":[["」象乃止舜宮居，鼓其琴。","zh-Hant"]]},{"id":"shiji_ch-1_p-22_s-21","passageId":"shiji_ch-1_p-22","order":21,"canonicalText":"舜往見之。","chunks":[["舜往見之。","zh-Hant"]]},{"id":"shiji_ch-1_p-22_s-22","passageId":"shiji_ch-1_p-22","order":22,"canonicalText":"象鄂不懌，曰：「我思舜正郁陶！","chunks":[["象鄂不懌，曰：「我思舜正郁陶！","zh-Hant"]]},{"id":"shiji_ch-1_p-22_s-23","passageId":"shiji_ch-1_p-22","order":23,"canonicalText":"」舜曰：「然，爾其庶矣！","chunks":[["」舜曰：「然，爾其庶矣！","zh-Hant"]]},{"id":"shiji_ch-1_p-22_s-24","passageId":"shiji_ch-1_p-22","order":24,"canonicalText":"」舜復事瞽叟愛弟彌謹。","chunks":[["」舜復事瞽叟愛弟彌謹。","zh-Hant"]]},{"id":"shiji_ch-1_p-22_s-25","passageId":"shiji_ch-1_p-22","order":25,"canonicalText":"於是堯乃試舜五典百官，皆治。","chunks":[["於是堯乃試舜五典百官，皆治。","zh-Hant"]]},{"id":"shiji_ch-1_p-23_s-1","passageId":"shiji_ch-1_p-23","order":1,"canonicalText":"昔高陽氏有才子八人，世得其利，謂之「八愷」。","chunks":[["昔高陽氏有才子八人，世得其利，謂之「八愷」。","zh-Hant"]]},{"id":"shiji_ch-1_p-23_s-2","passageId":"shiji_ch-1_p-23","order":2,"canonicalText":"高辛氏有才子八人，世謂之「八元」。","chunks":[["高辛氏有才子八人，世謂之「八元」。","zh-Hant"]]},{"id":"shiji_ch-1_p-23_s-3","passageId":"shiji_ch-1_p-23","order":3,"canonicalText":"此十六族者，世濟其美，不隕其名。","chunks":[["此十六族者，世濟其美，不隕其名。","zh-Hant"]]},{"id":"shiji_ch-1_p-23_s-4","passageId":"shiji_ch-1_p-23","order":4,"canonicalText":"至於堯，堯未能舉。","chunks":[["至於堯，堯未能舉。","zh-Hant"]]},{"id":"shiji_ch-1_p-23_s-5","passageId":"shiji_ch-1_p-23","order":5,"canonicalText":"舜舉八愷，使主后土，以揆百事，莫不時序。","chunks":[["舜舉八愷，使主后土，以揆百事，莫不時序。","zh-Hant"]]},{"id":"shiji_ch-1_p-23_s-6","passageId":"shiji_ch-1_p-23","order":6,"canonicalText":"舉八元，使布五教于四方，父義，母慈，兄友，弟恭，子孝，內平外成。","chunks":[["舉八元，使布五教于四方，父義，母慈，兄友，弟恭，子孝，內平外成。","zh-Hant"]]},{"id":"shiji_ch-1_p-24_s-1","passageId":"shiji_ch-1_p-24","order":1,"canonicalText":"昔帝鴻氏有不才子，掩義隱賊，好行凶慝，天下謂之渾沌。","chunks":[["昔帝鴻氏有不才子，掩義隱賊，好行凶慝，天下謂之渾沌。","zh-Hant"]]},{"id":"shiji_ch-1_p-24_s-2","passageId":"shiji_ch-1_p-24","order":2,"canonicalText":"少暤氏有不才子，毀信惡忠，崇飾惡言，天下謂之窮奇。","chunks":[["少暤氏有不才子，毀信惡忠，崇飾惡言，天下謂之窮奇。","zh-Hant"]]},{"id":"shiji_ch-1_p-24_s-3","passageId":"shiji_ch-1_p-24","order":3,"canonicalText":"顓頊氏有不才子，不可教訓，不知話言，天下謂之梼杌。","chunks":[["顓頊氏有不才子，不可教訓，不知話言，天下謂之梼杌。","zh-Hant"]]},{"id":"shiji_ch-1_p-24_s-4","passageId":"shiji_ch-1_p-24","order":4,"canonicalText":"此三族世憂之。","chunks":[["此三族世憂之。","zh-Hant"]]},{"id":"shiji_ch-1_p-24_s-5","passageId":"shiji_ch-1_p-24","order":5,"canonicalText":"至于堯，堯未能去。","chunks":[["至于堯，堯未能去。","zh-Hant"]]},{"id":"shiji_ch-1_p-24_s-6","passageId":"shiji_ch-1_p-24","order":6,"canonicalText":"縉云氏有不才子，貪于飲食，冒于貨賄，天下謂之饕餮。","chunks":[["縉云氏有不才子，貪于飲食，冒于貨賄，天下謂之饕餮。","zh-Hant"]]},{"id":"shiji_ch-1_p-24_s-7","passageId":"shiji_ch-1_p-24","order":7,"canonicalText":"天下惡之，比之三凶。","chunks":[["天下惡之，比之三凶。","zh-Hant"]]},{"id":"shiji_ch-1_p-24_s-8","passageId":"shiji_ch-1_p-24","order":8,"canonicalText":"舜賓於四門，乃流四凶族，遷于四裔，以御螭魅，於是四門辟，言毋凶人也。","chunks":[["舜賓於四門，乃流四凶族，遷于四裔，以御螭魅，於是四門辟，言毋凶人也。","zh-Hant"]]},{"id":"shiji_ch-1_p-25_s-1","passageId":"shiji_ch-1_p-25","order":1,"canonicalText":"舜入于大麓，烈風雷雨不迷，堯乃知舜之足授天下。","chunks":[["舜入于大麓，烈風雷雨不迷，堯乃知舜之足授天下。","zh-Hant"]]},{"id":"shiji_ch-1_p-25_s-2","passageId":"shiji_ch-1_p-25","order":2,"canonicalText":"堯老，使舜攝行天子政，巡狩。","chunks":[["堯老，使舜攝行天子政，巡狩。","zh-Hant"]]},{"id":"shiji_ch-1_p-25_s-3","passageId":"shiji_ch-1_p-25","order":3,"canonicalText":"舜得舉用事二十年，而堯使攝政。","chunks":[["舜得舉用事二十年，而堯使攝政。","zh-Hant"]]},{"id":"shiji_ch-1_p-25_s-4","passageId":"shiji_ch-1_p-25","order":4,"canonicalText":"攝政八年而堯崩。","chunks":[["攝政八年而堯崩。","zh-Hant"]]},{"id":"shiji_ch-1_p-25_s-5","passageId":"shiji_ch-1_p-25","order":5,"canonicalText":"三年喪畢，讓丹朱，天下歸舜。","chunks":[["三年喪畢，讓丹朱，天下歸舜。","zh-Hant"]]},{"id":"shiji_ch-1_p-25_s-6","passageId":"shiji_ch-1_p-25","order":6,"canonicalText":"而禹、皋陶、契、后稷、伯夷、夔、龍、倕、益、彭祖自堯時而皆舉用，未有分職。","chunks":[["而禹、皋陶、契、后稷、伯夷、夔、龍、倕、益、彭祖自堯時而皆舉用，未有分職。","zh-Hant"]]},{"id":"shiji_ch-1_p-25_s-7","passageId":"shiji_ch-1_p-25","order":7,"canonicalText":"於是舜乃至於文祖，謀于四嶽，辟四門，明通四方耳目，命十二牧論帝德，行厚德，遠佞人，則蠻夷率服。","chunks":[["於是舜乃至於文祖，謀于四嶽，辟四門，明通四方耳目，命十二牧論帝德，行厚德，遠佞人，則蠻夷率服。","zh-Hant"]]},{"id":"shiji_ch-1_p-25_s-8","passageId":"shiji_ch-1_p-25","order":8,"canonicalText":"舜謂四嶽曰：「有能奮庸美堯之事者，使居官相事？","chunks":[["舜謂四嶽曰：「有能奮庸美堯之事者，使居官相事？","zh-Hant"]]},{"id":"shiji_ch-1_p-25_s-9","passageId":"shiji_ch-1_p-25","order":9,"canonicalText":"」皆曰：「伯禹為司空，可美帝功。","chunks":[["」皆曰：「伯禹為司空，可美帝功。","zh-Hant"]]},{"id":"shiji_ch-1_p-25_s-10","passageId":"shiji_ch-1_p-25","order":10,"canonicalText":"」舜曰：「嗟，然！","chunks":[["」舜曰：「嗟，然！","zh-Hant"]]},{"id":"shiji_ch-1_p-25_s-11","passageId":"shiji_ch-1_p-25","order":11,"canonicalText":"禹，汝平水土，維是勉哉。","chunks":[["禹，汝平水土，維是勉哉。","zh-Hant"]]},{"id":"shiji_ch-1_p-25_s-12","passageId":"shiji_ch-1_p-25","order":12,"canonicalText":"」禹拜稽首，讓於稷、契與皋陶。","chunks":[["」禹拜稽首，讓於稷、契與皋陶。","zh-Hant"]]},{"id":"shiji_ch-1_p-25_s-13","passageId":"shiji_ch-1_p-25","order":13,"canonicalText":"舜曰：「然，往矣。","chunks":[["舜曰：「然，往矣。","zh-Hant"]]},{"id":"shiji_ch-1_p-25_s-14","passageId":"shiji_ch-1_p-25","order":14,"canonicalText":"」舜曰：「棄，黎民始饑，汝后稷播時百穀。","chunks":[["」舜曰：「棄，黎民始饑，汝后稷播時百穀。","zh-Hant"]]},{"id":"shiji_ch-1_p-25_s-15","passageId":"shiji_ch-1_p-25","order":15,"canonicalText":"」舜曰：「契，百姓不親，五品不馴，汝為司徒，而敬敷五教，在寬。","chunks":[["」舜曰：「契，百姓不親，五品不馴，汝為司徒，而敬敷五教，在寬。","zh-Hant"]]},{"id":"shiji_ch-1_p-25_s-16","passageId":"shiji_ch-1_p-25","order":16,"canonicalText":"」舜曰：「皋陶，蠻夷猾夏，寇賊姦軌，汝作士，五刑有服，五服三就；","chunks":[["」舜曰：「皋陶，蠻夷猾夏，寇賊姦軌，汝作士，五刑有服，五服三就；","zh-Hant"]]},{"id":"shiji_ch-1_p-25_s-17","passageId":"shiji_ch-1_p-25","order":17,"canonicalText":"五流有度，五度三居：維明能信。","chunks":[["五流有度，五度三居：維明能信。","zh-Hant"]]},{"id":"shiji_ch-1_p-25_s-18","passageId":"shiji_ch-1_p-25","order":18,"canonicalText":"」舜曰：「誰能馴予工？","chunks":[["」舜曰：「誰能馴予工？","zh-Hant"]]},{"id":"shiji_ch-1_p-25_s-19","passageId":"shiji_ch-1_p-25","order":19,"canonicalText":"」皆曰垂可。","chunks":[["」皆曰垂可。","zh-Hant"]]},{"id":"shiji_ch-1_p-25_s-20","passageId":"shiji_ch-1_p-25","order":20,"canonicalText":"於是以垂為共工。","chunks":[["於是以垂為共工。","zh-Hant"]]},{"id":"shiji_ch-1_p-25_s-21","passageId":"shiji_ch-1_p-25","order":21,"canonicalText":"舜曰：「誰能馴予上下草木鳥獸？","chunks":[["舜曰：「誰能馴予上下草木鳥獸？","zh-Hant"]]},{"id":"shiji_ch-1_p-25_s-22","passageId":"shiji_ch-1_p-25","order":22,"canonicalText":"」皆曰益可。","chunks":[["」皆曰益可。","zh-Hant"]]},{"id":"shiji_ch-1_p-25_s-23","passageId":"shiji_ch-1_p-25","order":23,"canonicalText":"於是以益為朕虞。","chunks":[["於是以益為朕虞。","zh-Hant"]]},{"id":"shiji_ch-1_p-25_s-24","passageId":"shiji_ch-1_p-25","order":24,"canonicalText":"益拜稽首，讓于諸臣朱虎、熊羆。","chunks":[["益拜稽首，讓于諸臣朱虎、熊羆。","zh-Hant"]]},{"id":"shiji_ch-1_p-25_s-25","passageId":"shiji_ch-1_p-25","order":25,"canonicalText":"舜曰：「往矣，汝諧。","chunks":[["舜曰：「往矣，汝諧。","zh-Hant"]]},{"id":"shiji_ch-1_p-25_s-26","passageId":"shiji_ch-1_p-25","order":26,"canonicalText":"」遂以朱虎、熊羆為佐。","chunks":[["」遂以朱虎、熊羆為佐。","zh-Hant"]]},{"id":"shiji_ch-1_p-25_s-27","passageId":"shiji_ch-1_p-25","order":27,"canonicalText":"舜曰：「嗟！","chunks":[["舜曰：「嗟！","zh-Hant"]]},{"id":"shiji_ch-1_p-25_s-28","passageId":"shiji_ch-1_p-25","order":28,"canonicalText":"四嶽，有能典朕三禮？","chunks":[["四嶽，有能典朕三禮？","zh-Hant"]]},{"id":"shiji_ch-1_p-25_s-29","passageId":"shiji_ch-1_p-25","order":29,"canonicalText":"」皆曰伯夷可。","chunks":[["」皆曰伯夷可。","zh-Hant"]]},{"id":"shiji_ch-1_p-25_s-30","passageId":"shiji_ch-1_p-25","order":30,"canonicalText":"舜曰：「嗟！","chunks":[["舜曰：「嗟！","zh-Hant"]]},{"id":"shiji_ch-1_p-25_s-31","passageId":"shiji_ch-1_p-25","order":31,"canonicalText":"伯夷，以汝為秩宗，夙夜維敬，直哉維靜絜。","chunks":[["伯夷，以汝為秩宗，夙夜維敬，直哉維靜絜。","zh-Hant"]]},{"id":"shiji_ch-1_p-25_s-32","passageId":"shiji_ch-1_p-25","order":32,"canonicalText":"」伯夷讓夔、龍。","chunks":[["」伯夷讓夔、龍。","zh-Hant"]]},{"id":"shiji_ch-1_p-25_s-33","passageId":"shiji_ch-1_p-25","order":33,"canonicalText":"舜曰：「然。","chunks":[["舜曰：「然。","zh-Hant"]]},{"id":"shiji_ch-1_p-25_s-34","passageId":"shiji_ch-1_p-25","order":34,"canonicalText":"以夔為典樂，教稚子，直而溫，寬而栗，剛而毋虐，簡而毋傲；","chunks":[["以夔為典樂，教稚子，直而溫，寬而栗，剛而毋虐，簡而毋傲；","zh-Hant"]]},{"id":"shiji_ch-1_p-25_s-35","passageId":"shiji_ch-1_p-25","order":35,"canonicalText":"詩言意，歌長言，聲依永，律和聲，八音能諧，毋相奪倫，神人以和。","chunks":[["詩言意，歌長言，聲依永，律和聲，八音能諧，毋相奪倫，神人以和。","zh-Hant"]]},{"id":"shiji_ch-1_p-25_s-36","passageId":"shiji_ch-1_p-25","order":36,"canonicalText":"」夔曰：「於！","chunks":[["」夔曰：「於！","zh-Hant"]]},{"id":"shiji_ch-1_p-25_s-37","passageId":"shiji_ch-1_p-25","order":37,"canonicalText":"予擊石拊石，百獸率舞。","chunks":[["予擊石拊石，百獸率舞。","zh-Hant"]]},{"id":"shiji_ch-1_p-25_s-38","passageId":"shiji_ch-1_p-25","order":38,"canonicalText":"」舜曰：「龍，朕畏忌讒說殄偽，振驚朕眾，命汝為納言，夙夜出入朕命，惟信。","chunks":[["」舜曰：「龍，朕畏忌讒說殄偽，振驚朕眾，命汝為納言，夙夜出入朕命，惟信。","zh-Hant"]]},{"id":"shiji_ch-1_p-25_s-39","passageId":"shiji_ch-1_p-25","order":39,"canonicalText":"」舜曰：「嗟！","chunks":[["」舜曰：「嗟！","zh-Hant"]]},{"id":"shiji_ch-1_p-25_s-40","passageId":"shiji_ch-1_p-25","order":40,"canonicalText":"女二十有二人，敬哉，惟時相天事。","chunks":[["女二十有二人，敬哉，惟時相天事。","zh-Hant"]]},{"id":"shiji_ch-1_p-25_s-41","passageId":"shiji_ch-1_p-25","order":41,"canonicalText":"」三歲一考功，三考絀陟，遠近眾功咸興。","chunks":[["」三歲一考功，三考絀陟，遠近眾功咸興。","zh-Hant"]]},{"id":"shiji_ch-1_p-25_s-42","passageId":"shiji_ch-1_p-25","order":42,"canonicalText":"分北三苗。","chunks":[["分北三苗。","zh-Hant"]]},{"id":"shiji_ch-1_p-26_s-1","passageId":"shiji_ch-1_p-26","order":1,"canonicalText":"此二十二人咸成厥功：皋陶為大理，平，民各伏得其實；","chunks":[["此二十二人咸成厥功：皋陶為大理，平，民各伏得其實；","zh-Hant"]]},{"id":"shiji_ch-1_p-26_s-2","passageId":"shiji_ch-1_p-26","order":2,"canonicalText":"伯夷主禮，上下咸讓；","chunks":[["伯夷主禮，上下咸讓；","zh-Hant"]]},{"id":"shiji_ch-1_p-26_s-3","passageId":"shiji_ch-1_p-26","order":3,"canonicalText":"垂主工師，百工致功；","chunks":[["垂主工師，百工致功；","zh-Hant"]]},{"id":"shiji_ch-1_p-26_s-4","passageId":"shiji_ch-1_p-26","order":4,"canonicalText":"益主虞，山澤辟；","chunks":[["益主虞，山澤辟；","zh-Hant"]]},{"id":"shiji_ch-1_p-26_s-5","passageId":"shiji_ch-1_p-26","order":5,"canonicalText":"棄主稷，百穀時茂；","chunks":[["棄主稷，百穀時茂；","zh-Hant"]]},{"id":"shiji_ch-1_p-26_s-6","passageId":"shiji_ch-1_p-26","order":6,"canonicalText":"契主司徒，百姓親和；","chunks":[["契主司徒，百姓親和；","zh-Hant"]]},{"id":"shiji_ch-1_p-26_s-7","passageId":"shiji_ch-1_p-26","order":7,"canonicalText":"龍主賓客，遠人至；","chunks":[["龍主賓客，遠人至；","zh-Hant"]]},{"id":"shiji_ch-1_p-26_s-8","passageId":"shiji_ch-1_p-26","order":8,"canonicalText":"十二牧行而九州莫敢辟違；","chunks":[["十二牧行而九州莫敢辟違；","zh-Hant"]]},{"id":"shiji_ch-1_p-26_s-9","passageId":"shiji_ch-1_p-26","order":9,"canonicalText":"唯禹之功為大，披九山，通九澤，決九河，定九州，各以其職來貢，不失厥宜。","chunks":[["唯禹之功為大，披九山，通九澤，決九河，定九州，各以其職來貢，不失厥宜。","zh-Hant"]]},{"id":"shiji_ch-1_p-26_s-10","passageId":"shiji_ch-1_p-26","order":10,"canonicalText":"方五千里，至于荒服。","chunks":[["方五千里，至于荒服。","zh-Hant"]]},{"id":"shiji_ch-1_p-26_s-11","passageId":"shiji_ch-1_p-26","order":11,"canonicalText":"南撫交阯、北發，西戎、析枝、渠廋、氐、羌，北山戎、發、息慎，東長、鳥夷，四海之內咸戴帝舜之功。","chunks":[["南撫交阯、北發，西戎、析枝、渠廋、氐、羌，北山戎、發、息慎，東長、鳥夷，四海之內咸戴帝舜之功。","zh-Hant"]]},{"id":"shiji_ch-1_p-26_s-12","passageId":"shiji_ch-1_p-26","order":12,"canonicalText":"於是禹乃興九招之樂，致異物，鳳皇來翔。","chunks":[["於是禹乃興九招之樂，致異物，鳳皇來翔。","zh-Hant"]]},{"id":"shiji_ch-1_p-26_s-13","passageId":"shiji_ch-1_p-26","order":13,"canonicalText":"天下明德皆自虞帝始。","chunks":[["天下明德皆自虞帝始。","zh-Hant"]]},{"id":"shiji_ch-1_p-27_s-1","passageId":"shiji_ch-1_p-27","order":1,"canonicalText":"舜年二十以孝聞，年三十堯舉之，年五十攝行天子事，年五十八堯崩，年六十一代堯踐帝位。","chunks":[["舜年二十以孝聞，年三十堯舉之，年五十攝行天子事，年五十八堯崩，年六十一代堯踐帝位。","zh-Hant"]]},{"id":"shiji_ch-1_p-27_s-2","passageId":"shiji_ch-1_p-27","order":2,"canonicalText":"踐帝位三十九年，南巡狩，崩於蒼梧之野。","chunks":[["踐帝位三十九年，南巡狩，崩於蒼梧之野。","zh-Hant"]]},{"id":"shiji_ch-1_p-27_s-3","passageId":"shiji_ch-1_p-27","order":3,"canonicalText":"葬於江南九疑，是為零陵。","chunks":[["葬於江南九疑，是為零陵。","zh-Hant"]]},{"id":"shiji_ch-1_p-27_s-4","passageId":"shiji_ch-1_p-27","order":4,"canonicalText":"舜之踐帝位，載天子旗，往朝父瞽叟，夔夔唯謹，如子道。","chunks":[["舜之踐帝位，載天子旗，往朝父瞽叟，夔夔唯謹，如子道。","zh-Hant"]]},{"id":"shiji_ch-1_p-27_s-5","passageId":"shiji_ch-1_p-27","order":5,"canonicalText":"封弟象為諸侯。","chunks":[["封弟象為諸侯。","zh-Hant"]]},{"id":"shiji_ch-1_p-27_s-6","passageId":"shiji_ch-1_p-27","order":6,"canonicalText":"舜子商均亦不肖，舜乃豫薦禹於天。","chunks":[["舜子商均亦不肖，舜乃豫薦禹於天。","zh-Hant"]]},{"id":"shiji_ch-1_p-27_s-7","passageId":"shiji_ch-1_p-27","order":7,"canonicalText":"十七年而崩。","chunks":[["十七年而崩。","zh-Hant"]]},{"id":"shiji_ch-1_p-27_s-8","passageId":"shiji_ch-1_p-27","order":8,"canonicalText":"三年喪畢，禹亦乃讓舜子，如舜讓堯子。","chunks":[["三年喪畢，禹亦乃讓舜子，如舜讓堯子。","zh-Hant"]]},{"id":"shiji_ch-1_p-27_s-9","passageId":"shiji_ch-1_p-27","order":9,"canonicalText":"諸侯歸之，然後禹踐天子位。","chunks":[["諸侯歸之，然後禹踐天子位。","zh-Hant"]]},{"id":"shiji_ch-1_p-27_s-10","passageId":"shiji_ch-1_p-27","order":10,"canonicalText":"堯子丹朱，舜子商均，皆有疆土，以奉先祀。","chunks":[["堯子丹朱，舜子商均，皆有疆土，以奉先祀。","zh-Hant"]]},{"id":"shiji_ch-1_p-27_s-11","passageId":"shiji_ch-1_p-27","order":11,"canonicalText":"服其服，禮樂如之。","chunks":[["服其服，禮樂如之。","zh-Hant"]]},{"id":"shiji_ch-1_p-27_s-12","passageId":"shiji_ch-1_p-27","order":12,"canonicalText":"以客見天子，天子弗臣，示不敢專也。","chunks":[["以客見天子，天子弗臣，示不敢專也。","zh-Hant"]]},{"id":"shiji_ch-1_p-28_s-1","passageId":"shiji_ch-1_p-28","order":1,"canonicalText":"自黃帝至舜、禹，皆同姓而異其國號，以章明德。","chunks":[["自黃帝至舜、禹，皆同姓而異其國號，以章明德。","zh-Hant"]]},{"id":"shiji_ch-1_p-28_s-2","passageId":"shiji_ch-1_p-28","order":2,"canonicalText":"故黃帝為有熊，帝顓頊為高陽，帝嚳為高辛，帝堯為陶唐，帝舜為有虞。","chunks":[["故黃帝為有熊，帝顓頊為高陽，帝嚳為高辛，帝堯為陶唐，帝舜為有虞。","zh-Hant"]]},{"id":"shiji_ch-1_p-28_s-3","passageId":"shiji_ch-1_p-28","order":3,"canonicalText":"帝禹為夏后而別氏，姓姒氏。","chunks":[["帝禹為夏后而別氏，姓姒氏。","zh-Hant"]]},{"id":"shiji_ch-1_p-28_s-4","passageId":"shiji_ch-1_p-28","order":4,"canonicalText":"契為商，姓子氏。","chunks":[["契為商，姓子氏。","zh-Hant"]]},{"id":"shiji_ch-1_p-28_s-5","passageId":"shiji_ch-1_p-28","order":5,"canonicalText":"棄為周，姓姬氏。","chunks":[["棄為周，姓姬氏。","zh-Hant"]]},{"id":"shiji_ch-1_p-29_s-1","passageId":"shiji_ch-1_p-29","order":1,"canonicalText":"太史公曰：學者多稱五帝，尚矣。","chunks":[["太史公曰：學者多稱五帝，尚矣。","zh-Hant"]]},{"id":"shiji_ch-1_p-29_s-2","passageId":"shiji_ch-1_p-29","order":2,"canonicalText":"然尚書獨載堯以來；","chunks":[["然尚書獨載堯以來；","zh-Hant"]]},{"id":"shiji_ch-1_p-29_s-3","passageId":"shiji_ch-1_p-29","order":3,"canonicalText":"而百家言黃帝，其文不雅馴，薦紳先生難言之。","chunks":[["而百家言黃帝，其文不雅馴，薦紳先生難言之。","zh-Hant"]]},{"id":"shiji_ch-1_p-29_s-4","passageId":"shiji_ch-1_p-29","order":4,"canonicalText":"孔子所傳宰予問五帝德及帝系姓，儒者或不傳。","chunks":[["孔子所傳宰予問五帝德及帝系姓，儒者或不傳。","zh-Hant"]]},{"id":"shiji_ch-1_p-29_s-5","passageId":"shiji_ch-1_p-29","order":5,"canonicalText":"余嘗西至空桐，北過涿鹿，東漸於海，南浮江淮矣，至長老皆各往往稱黃帝、堯、舜之處，風教固殊焉，總之不離古文者近是。","chunks":[["余嘗西至空桐，北過涿鹿，東漸於海，南浮江淮矣，至長老皆各往往稱黃帝、堯、舜之處，風教固殊焉，總之不離古文者近是。","zh-Hant"]]},{"id":"shiji_ch-1_p-29_s-6","passageId":"shiji_ch-1_p-29","order":6,"canonicalText":"予觀春秋、國語，其發明五帝德、帝系姓章矣，顧弟弗深考，其所表見皆不虛。","chunks":[["予觀春秋、國語，其發明五帝德、帝系姓章矣，顧弟弗深考，其所表見皆不虛。","zh-Hant"]]},{"id":"shiji_ch-1_p-29_s-7","passageId":"shiji_ch-1_p-29","order":7,"canonicalText":"書缺有閒矣，其軼乃時時見於他說。","chunks":[["書缺有閒矣，其軼乃時時見於他說。","zh-Hant"]]},{"id":"shiji_ch-1_p-29_s-8","passageId":"shiji_ch-1_p-29","order":8,"canonicalText":"非好學深思，心知其意，固難為淺見寡聞道也。","chunks":[["非好學深思，心知其意，固難為淺見寡聞道也。","zh-Hant"]]},{"id":"shiji_ch-1_p-29_s-9","passageId":"shiji_ch-1_p-29","order":9,"canonicalText":"余并論次，擇其言尤雅者，故著為本紀書首。","chunks":[["余并論次，擇其言尤雅者，故著為本紀書首。","zh-Hant"]]},{"id":"shiji_ch-2_p-1_s-1","passageId":"shiji_ch-2_p-1","order":1,"canonicalText":"夏禹，名曰文命。","chunks":[["夏禹，名曰文命。","zh-Hant"]]},{"id":"shiji_ch-2_p-1_s-2","passageId":"shiji_ch-2_p-1","order":2,"canonicalText":"禹之父曰鯀，鯀之父曰帝顓頊，顓頊之父曰昌意，昌意之父曰黃帝。","chunks":[["禹之父曰鯀，鯀之父曰帝顓頊，顓頊之父曰昌意，昌意之父曰黃帝。","zh-Hant"]]},{"id":"shiji_ch-2_p-1_s-3","passageId":"shiji_ch-2_p-1","order":3,"canonicalText":"禹者，黃帝之玄孫而帝顓頊之孫也。","chunks":[["禹者，黃帝之玄孫而帝顓頊之孫也。","zh-Hant"]]},{"id":"shiji_ch-2_p-1_s-4","passageId":"shiji_ch-2_p-1","order":4,"canonicalText":"禹之曾大父昌意及父鯀皆不得在帝位，為人臣。","chunks":[["禹之曾大父昌意及父鯀皆不得在帝位，為人臣。","zh-Hant"]]},{"id":"shiji_ch-2_p-2_s-1","passageId":"shiji_ch-2_p-2","order":1,"canonicalText":"當帝堯之時，鴻水滔天，浩浩懷山襄陵，下民其憂。","chunks":[["當帝堯之時，鴻水滔天，浩浩懷山襄陵，下民其憂。","zh-Hant"]]},{"id":"shiji_ch-2_p-2_s-2","passageId":"shiji_ch-2_p-2","order":2,"canonicalText":"堯求能治水者，群臣四嶽皆曰鯀可。","chunks":[["堯求能治水者，群臣四嶽皆曰鯀可。","zh-Hant"]]},{"id":"shiji_ch-2_p-2_s-3","passageId":"shiji_ch-2_p-2","order":3,"canonicalText":"堯曰：「鯀為人負命毀族，不可。","chunks":[["堯曰：「鯀為人負命毀族，不可。","zh-Hant"]]},{"id":"shiji_ch-2_p-2_s-4","passageId":"shiji_ch-2_p-2","order":4,"canonicalText":"」四嶽曰：「等之未有賢於鯀者，願帝試之。","chunks":[["」四嶽曰：「等之未有賢於鯀者，願帝試之。","zh-Hant"]]},{"id":"shiji_ch-2_p-2_s-5","passageId":"shiji_ch-2_p-2","order":5,"canonicalText":"」於是堯聽四嶽，用鯀治水。","chunks":[["」於是堯聽四嶽，用鯀治水。","zh-Hant"]]},{"id":"shiji_ch-2_p-2_s-6","passageId":"shiji_ch-2_p-2","order":6,"canonicalText":"九年而水不息，功用不成。","chunks":[["九年而水不息，功用不成。","zh-Hant"]]},{"id":"shiji_ch-2_p-2_s-7","passageId":"shiji_ch-2_p-2","order":7,"canonicalText":"於是帝堯乃求人，更得舜。","chunks":[["於是帝堯乃求人，更得舜。","zh-Hant"]]},{"id":"shiji_ch-2_p-2_s-8","passageId":"shiji_ch-2_p-2","order":8,"canonicalText":"舜登用，攝行天子之政，巡狩。","chunks":[["舜登用，攝行天子之政，巡狩。","zh-Hant"]]},{"id":"shiji_ch-2_p-2_s-9","passageId":"shiji_ch-2_p-2","order":9,"canonicalText":"行視鯀之治水無狀，乃殛鯀於羽山以死。","chunks":[["行視鯀之治水無狀，乃殛鯀於羽山以死。","zh-Hant"]]},{"id":"shiji_ch-2_p-2_s-10","passageId":"shiji_ch-2_p-2","order":10,"canonicalText":"天下皆以舜之誅為是。","chunks":[["天下皆以舜之誅為是。","zh-Hant"]]},{"id":"shiji_ch-2_p-2_s-11","passageId":"shiji_ch-2_p-2","order":11,"canonicalText":"於是舜舉鯀子禹，而使續鯀之業。","chunks":[["於是舜舉鯀子禹，而使續鯀之業。","zh-Hant"]]},{"id":"shiji_ch-2_p-3_s-1","passageId":"shiji_ch-2_p-3","order":1,"canonicalText":"堯崩，帝舜問四嶽曰：「有能成美堯之事者使居官？","chunks":[["堯崩，帝舜問四嶽曰：「有能成美堯之事者使居官？","zh-Hant"]]},{"id":"shiji_ch-2_p-3_s-2","passageId":"shiji_ch-2_p-3","order":2,"canonicalText":"」皆曰：「伯禹為司空，可成美堯之功。","chunks":[["」皆曰：「伯禹為司空，可成美堯之功。","zh-Hant"]]},{"id":"shiji_ch-2_p-3_s-3","passageId":"shiji_ch-2_p-3","order":3,"canonicalText":"」舜曰：「嗟，然！","chunks":[["」舜曰：「嗟，然！","zh-Hant"]]},{"id":"shiji_ch-2_p-3_s-4","passageId":"shiji_ch-2_p-3","order":4,"canonicalText":"」命禹：「女平水土，維是勉之。","chunks":[["」命禹：「女平水土，維是勉之。","zh-Hant"]]},{"id":"shiji_ch-2_p-3_s-5","passageId":"shiji_ch-2_p-3","order":5,"canonicalText":"」禹拜稽首，讓於契、后稷、皋陶。","chunks":[["」禹拜稽首，讓於契、后稷、皋陶。","zh-Hant"]]},{"id":"shiji_ch-2_p-3_s-6","passageId":"shiji_ch-2_p-3","order":6,"canonicalText":"舜曰：「女其往視爾事矣。","chunks":[["舜曰：「女其往視爾事矣。","zh-Hant"]]},{"id":"shiji_ch-2_p-3_s-7","passageId":"shiji_ch-2_p-3","order":7,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"shiji_ch-2_p-4_s-1","passageId":"shiji_ch-2_p-4","order":1,"canonicalText":"禹為人敏給克勤；","chunks":[["禹為人敏給克勤；","zh-Hant"]]},{"id":"shiji_ch-2_p-4_s-2","passageId":"shiji_ch-2_p-4","order":2,"canonicalText":"其德不違，其仁可親，其言可信；","chunks":[["其德不違，其仁可親，其言可信；","zh-Hant"]]},{"id":"shiji_ch-2_p-4_s-3","passageId":"shiji_ch-2_p-4","order":3,"canonicalText":"聲為律，身為度，稱以出；","chunks":[["聲為律，身為度，稱以出；","zh-Hant"]]},{"id":"shiji_ch-2_p-4_s-4","passageId":"shiji_ch-2_p-4","order":4,"canonicalText":"亹亹穆穆，為綱為紀。","chunks":[["亹亹穆穆，為綱為紀。","zh-Hant"]]},{"id":"shiji_ch-2_p-5_s-1","passageId":"shiji_ch-2_p-5","order":1,"canonicalText":"禹乃遂與益、后稷奉帝命，命諸侯百姓興人徒以傅土，行山表木，定高山大川。","chunks":[["禹乃遂與益、后稷奉帝命，命諸侯百姓興人徒以傅土，行山表木，定高山大川。","zh-Hant"]]},{"id":"shiji_ch-2_p-5_s-2","passageId":"shiji_ch-2_p-5","order":2,"canonicalText":"禹傷先人父鯀功之不成受誅，乃勞身焦思，居外十三年，過家門不敢入。","chunks":[["禹傷先人父鯀功之不成受誅，乃勞身焦思，居外十三年，過家門不敢入。","zh-Hant"]]},{"id":"shiji_ch-2_p-5_s-3","passageId":"shiji_ch-2_p-5","order":3,"canonicalText":"薄衣食，致孝于鬼神。","chunks":[["薄衣食，致孝于鬼神。","zh-Hant"]]},{"id":"shiji_ch-2_p-5_s-4","passageId":"shiji_ch-2_p-5","order":4,"canonicalText":"卑宮室，致費於溝淢。","chunks":[["卑宮室，致費於溝淢。","zh-Hant"]]},{"id":"shiji_ch-2_p-5_s-5","passageId":"shiji_ch-2_p-5","order":5,"canonicalText":"陸行乘車，水行乘船，泥行乘橇，山行乘檋。","chunks":[["陸行乘車，水行乘船，泥行乘橇，山行乘檋。","zh-Hant"]]},{"id":"shiji_ch-2_p-5_s-6","passageId":"shiji_ch-2_p-5","order":6,"canonicalText":"左準繩，右規矩，載四時，以開九州，通九道，陂九澤，度九山。","chunks":[["左準繩，右規矩，載四時，以開九州，通九道，陂九澤，度九山。","zh-Hant"]]},{"id":"shiji_ch-2_p-5_s-7","passageId":"shiji_ch-2_p-5","order":7,"canonicalText":"令益予眾庶稻，可種卑溼。","chunks":[["令益予眾庶稻，可種卑溼。","zh-Hant"]]},{"id":"shiji_ch-2_p-5_s-8","passageId":"shiji_ch-2_p-5","order":8,"canonicalText":"命后稷予眾庶難得之食。","chunks":[["命后稷予眾庶難得之食。","zh-Hant"]]},{"id":"shiji_ch-2_p-5_s-9","passageId":"shiji_ch-2_p-5","order":9,"canonicalText":"食少，調有餘相給，以均諸侯。","chunks":[["食少，調有餘相給，以均諸侯。","zh-Hant"]]},{"id":"shiji_ch-2_p-5_s-10","passageId":"shiji_ch-2_p-5","order":10,"canonicalText":"禹乃行相地宜所有以貢，及山川之便利。","chunks":[["禹乃行相地宜所有以貢，及山川之便利。","zh-Hant"]]},{"id":"shiji_ch-2_p-6_s-1","passageId":"shiji_ch-2_p-6","order":1,"canonicalText":"禹行自冀州始。","chunks":[["禹行自冀州始。","zh-Hant"]]},{"id":"shiji_ch-2_p-6_s-2","passageId":"shiji_ch-2_p-6","order":2,"canonicalText":"冀州：既載壺口，治梁及岐。","chunks":[["冀州：既載壺口，治梁及岐。","zh-Hant"]]},{"id":"shiji_ch-2_p-6_s-3","passageId":"shiji_ch-2_p-6","order":3,"canonicalText":"既修太原，至于嶽陽。","chunks":[["既修太原，至于嶽陽。","zh-Hant"]]},{"id":"shiji_ch-2_p-6_s-4","passageId":"shiji_ch-2_p-6","order":4,"canonicalText":"覃懷致功，至於衡漳。","chunks":[["覃懷致功，至於衡漳。","zh-Hant"]]},{"id":"shiji_ch-2_p-6_s-5","passageId":"shiji_ch-2_p-6","order":5,"canonicalText":"其土白壤。","chunks":[["其土白壤。","zh-Hant"]]},{"id":"shiji_ch-2_p-6_s-6","passageId":"shiji_ch-2_p-6","order":6,"canonicalText":"賦上上錯，田中中，常、衛既從，大陸既為。","chunks":[["賦上上錯，田中中，常、衛既從，大陸既為。","zh-Hant"]]},{"id":"shiji_ch-2_p-6_s-7","passageId":"shiji_ch-2_p-6","order":7,"canonicalText":"鳥夷皮服。","chunks":[["鳥夷皮服。","zh-Hant"]]},{"id":"shiji_ch-2_p-6_s-8","passageId":"shiji_ch-2_p-6","order":8,"canonicalText":"夾右碣石，入于海。","chunks":[["夾右碣石，入于海。","zh-Hant"]]},{"id":"shiji_ch-2_p-7_s-1","passageId":"shiji_ch-2_p-7","order":1,"canonicalText":"濟、河維沇州：九河既道，雷夏既澤，雍、沮會同，桑土既蠶，於是民得下丘居土。","chunks":[["濟、河維沇州：九河既道，雷夏既澤，雍、沮會同，桑土既蠶，於是民得下丘居土。","zh-Hant"]]},{"id":"shiji_ch-2_p-7_s-2","passageId":"shiji_ch-2_p-7","order":2,"canonicalText":"其土黑墳，草繇木條。","chunks":[["其土黑墳，草繇木條。","zh-Hant"]]},{"id":"shiji_ch-2_p-7_s-3","passageId":"shiji_ch-2_p-7","order":3,"canonicalText":"田中下，賦貞，作十有三年乃同。","chunks":[["田中下，賦貞，作十有三年乃同。","zh-Hant"]]},{"id":"shiji_ch-2_p-7_s-4","passageId":"shiji_ch-2_p-7","order":4,"canonicalText":"其貢漆絲，其篚織文。","chunks":[["其貢漆絲，其篚織文。","zh-Hant"]]},{"id":"shiji_ch-2_p-7_s-5","passageId":"shiji_ch-2_p-7","order":5,"canonicalText":"浮於濟、漯，通於河。","chunks":[["浮於濟、漯，通於河。","zh-Hant"]]},{"id":"shiji_ch-2_p-8_s-1","passageId":"shiji_ch-2_p-8","order":1,"canonicalText":"海岱維青州：堣夷既略，濰、淄其道。","chunks":[["海岱維青州：堣夷既略，濰、淄其道。","zh-Hant"]]},{"id":"shiji_ch-2_p-8_s-2","passageId":"shiji_ch-2_p-8","order":2,"canonicalText":"其土白墳，海濱廣潟，厥田斥鹵。","chunks":[["其土白墳，海濱廣潟，厥田斥鹵。","zh-Hant"]]},{"id":"shiji_ch-2_p-8_s-3","passageId":"shiji_ch-2_p-8","order":3,"canonicalText":"田上下，賦中上。","chunks":[["田上下，賦中上。","zh-Hant"]]},{"id":"shiji_ch-2_p-8_s-4","passageId":"shiji_ch-2_p-8","order":4,"canonicalText":"厥貢鹽絺，海物維錯，岱畎絲、枲、鉛、松、怪石，萊夷為牧，其篚酓絲。","chunks":[["厥貢鹽絺，海物維錯，岱畎絲、枲、鉛、松、怪石，萊夷為牧，其篚酓絲。","zh-Hant"]]},{"id":"shiji_ch-2_p-8_s-5","passageId":"shiji_ch-2_p-8","order":5,"canonicalText":"浮於汶，通於濟。","chunks":[["浮於汶，通於濟。","zh-Hant"]]},{"id":"shiji_ch-2_p-9_s-1","passageId":"shiji_ch-2_p-9","order":1,"canonicalText":"海岱及淮維徐州：淮、沂其治，蒙、羽其藝。","chunks":[["海岱及淮維徐州：淮、沂其治，蒙、羽其藝。","zh-Hant"]]},{"id":"shiji_ch-2_p-9_s-2","passageId":"shiji_ch-2_p-9","order":2,"canonicalText":"大野既都，東原底平。","chunks":[["大野既都，東原底平。","zh-Hant"]]},{"id":"shiji_ch-2_p-9_s-3","passageId":"shiji_ch-2_p-9","order":3,"canonicalText":"其土赤埴墳，草木漸包。","chunks":[["其土赤埴墳，草木漸包。","zh-Hant"]]},{"id":"shiji_ch-2_p-9_s-4","passageId":"shiji_ch-2_p-9","order":4,"canonicalText":"其田上中，賦中中。","chunks":[["其田上中，賦中中。","zh-Hant"]]},{"id":"shiji_ch-2_p-9_s-5","passageId":"shiji_ch-2_p-9","order":5,"canonicalText":"貢維土五色，羽畎夏狄，嶧陽孤桐，泗濱浮磬，淮夷蠙珠臮魚，其篚玄纖縞。","chunks":[["貢維土五色，羽畎夏狄，嶧陽孤桐，泗濱浮磬，淮夷蠙珠臮魚，其篚玄纖縞。","zh-Hant"]]},{"id":"shiji_ch-2_p-9_s-6","passageId":"shiji_ch-2_p-9","order":6,"canonicalText":"浮于淮、泗，通于河。","chunks":[["浮于淮、泗，通于河。","zh-Hant"]]},{"id":"shiji_ch-2_p-10_s-1","passageId":"shiji_ch-2_p-10","order":1,"canonicalText":"淮海維揚州：彭蠡既都，陽鳥所居。","chunks":[["淮海維揚州：彭蠡既都，陽鳥所居。","zh-Hant"]]},{"id":"shiji_ch-2_p-10_s-2","passageId":"shiji_ch-2_p-10","order":2,"canonicalText":"三江既入，震澤致定。","chunks":[["三江既入，震澤致定。","zh-Hant"]]},{"id":"shiji_ch-2_p-10_s-3","passageId":"shiji_ch-2_p-10","order":3,"canonicalText":"竹箭既布。","chunks":[["竹箭既布。","zh-Hant"]]},{"id":"shiji_ch-2_p-10_s-4","passageId":"shiji_ch-2_p-10","order":4,"canonicalText":"其草惟夭，其木惟喬，其土涂泥。","chunks":[["其草惟夭，其木惟喬，其土涂泥。","zh-Hant"]]},{"id":"shiji_ch-2_p-10_s-5","passageId":"shiji_ch-2_p-10","order":5,"canonicalText":"田下下，賦下上上雜。","chunks":[["田下下，賦下上上雜。","zh-Hant"]]},{"id":"shiji_ch-2_p-10_s-6","passageId":"shiji_ch-2_p-10","order":6,"canonicalText":"貢金三品，瑤、琨、竹箭，齒、革、羽、旄，島夷卉服，其篚織貝，其包橘、柚錫貢。","chunks":[["貢金三品，瑤、琨、竹箭，齒、革、羽、旄，島夷卉服，其篚織貝，其包橘、柚錫貢。","zh-Hant"]]},{"id":"shiji_ch-2_p-10_s-7","passageId":"shiji_ch-2_p-10","order":7,"canonicalText":"均江海，通淮、泗。","chunks":[["均江海，通淮、泗。","zh-Hant"]]},{"id":"shiji_ch-2_p-11_s-1","passageId":"shiji_ch-2_p-11","order":1,"canonicalText":"荊及衡陽維荊州：江、漢朝宗于海。","chunks":[["荊及衡陽維荊州：江、漢朝宗于海。","zh-Hant"]]},{"id":"shiji_ch-2_p-11_s-2","passageId":"shiji_ch-2_p-11","order":2,"canonicalText":"九江甚中，沱、涔已道，云土、夢為治。","chunks":[["九江甚中，沱、涔已道，云土、夢為治。","zh-Hant"]]},{"id":"shiji_ch-2_p-11_s-3","passageId":"shiji_ch-2_p-11","order":3,"canonicalText":"其土涂泥。","chunks":[["其土涂泥。","zh-Hant"]]},{"id":"shiji_ch-2_p-11_s-4","passageId":"shiji_ch-2_p-11","order":4,"canonicalText":"田下中，賦上下。","chunks":[["田下中，賦上下。","zh-Hant"]]},{"id":"shiji_ch-2_p-11_s-5","passageId":"shiji_ch-2_p-11","order":5,"canonicalText":"貢羽、旄、齒、革，金三品，杶、榦、栝、柏，礪、砥、砮、丹，維箘簬、楛，三國致貢其名，包匭菁茅，其篚玄纁璣組，九江入賜大龜。","chunks":[["貢羽、旄、齒、革，金三品，杶、榦、栝、柏，礪、砥、砮、丹，維箘簬、楛，三國致貢其名，包匭菁茅，其篚玄纁璣組，九江入賜大龜。","zh-Hant"]]},{"id":"shiji_ch-2_p-11_s-6","passageId":"shiji_ch-2_p-11","order":6,"canonicalText":"浮于江、沱、涔、（于）漢，踰于雒，至于南河。","chunks":[["浮于江、沱、涔、（于）漢，踰于雒，至于南河。","zh-Hant"]]},{"id":"shiji_ch-2_p-12_s-1","passageId":"shiji_ch-2_p-12","order":1,"canonicalText":"荊河惟豫州：伊、雒、瀍、澗既入于河，滎播既都，道荷澤，被明都。","chunks":[["荊河惟豫州：伊、雒、瀍、澗既入于河，滎播既都，道荷澤，被明都。","zh-Hant"]]},{"id":"shiji_ch-2_p-12_s-2","passageId":"shiji_ch-2_p-12","order":2,"canonicalText":"其土壤，下土墳壚。","chunks":[["其土壤，下土墳壚。","zh-Hant"]]},{"id":"shiji_ch-2_p-12_s-3","passageId":"shiji_ch-2_p-12","order":3,"canonicalText":"田中上，賦雜上中。","chunks":[["田中上，賦雜上中。","zh-Hant"]]},{"id":"shiji_ch-2_p-12_s-4","passageId":"shiji_ch-2_p-12","order":4,"canonicalText":"貢漆、絲、絺、紵，其篚纖絮，錫貢磬錯。","chunks":[["貢漆、絲、絺、紵，其篚纖絮，錫貢磬錯。","zh-Hant"]]},{"id":"shiji_ch-2_p-12_s-5","passageId":"shiji_ch-2_p-12","order":5,"canonicalText":"浮於雒，達於河。","chunks":[["浮於雒，達於河。","zh-Hant"]]},{"id":"shiji_ch-2_p-13_s-1","passageId":"shiji_ch-2_p-13","order":1,"canonicalText":"華陽黑水惟梁州：汶、嶓既藝，沱、涔既道，蔡、蒙旅平，和夷厎績。","chunks":[["華陽黑水惟梁州：汶、嶓既藝，沱、涔既道，蔡、蒙旅平，和夷厎績。","zh-Hant"]]},{"id":"shiji_ch-2_p-13_s-2","passageId":"shiji_ch-2_p-13","order":2,"canonicalText":"其土青驪。","chunks":[["其土青驪。","zh-Hant"]]},{"id":"shiji_ch-2_p-13_s-3","passageId":"shiji_ch-2_p-13","order":3,"canonicalText":"田下上，賦下中三錯。","chunks":[["田下上，賦下中三錯。","zh-Hant"]]},{"id":"shiji_ch-2_p-13_s-4","passageId":"shiji_ch-2_p-13","order":4,"canonicalText":"貢璆、鐵、銀、鏤、砮、磬，熊、羆、狐、貍、織皮。","chunks":[["貢璆、鐵、銀、鏤、砮、磬，熊、羆、狐、貍、織皮。","zh-Hant"]]},{"id":"shiji_ch-2_p-13_s-5","passageId":"shiji_ch-2_p-13","order":5,"canonicalText":"西傾因桓是來，浮于潛，踰于沔，入于渭，亂于河。","chunks":[["西傾因桓是來，浮于潛，踰于沔，入于渭，亂于河。","zh-Hant"]]},{"id":"shiji_ch-2_p-14_s-1","passageId":"shiji_ch-2_p-14","order":1,"canonicalText":"黑水西河惟雍州：弱水既西，涇屬渭汭。","chunks":[["黑水西河惟雍州：弱水既西，涇屬渭汭。","zh-Hant"]]},{"id":"shiji_ch-2_p-14_s-2","passageId":"shiji_ch-2_p-14","order":2,"canonicalText":"漆、沮既從，灃水所同。","chunks":[["漆、沮既從，灃水所同。","zh-Hant"]]},{"id":"shiji_ch-2_p-14_s-3","passageId":"shiji_ch-2_p-14","order":3,"canonicalText":"荊、岐已旅，終南、敦物至于鳥鼠。","chunks":[["荊、岐已旅，終南、敦物至于鳥鼠。","zh-Hant"]]},{"id":"shiji_ch-2_p-14_s-4","passageId":"shiji_ch-2_p-14","order":4,"canonicalText":"原隰厎績，至于都野。","chunks":[["原隰厎績，至于都野。","zh-Hant"]]},{"id":"shiji_ch-2_p-14_s-5","passageId":"shiji_ch-2_p-14","order":5,"canonicalText":"三危既度，三苗大序。","chunks":[["三危既度，三苗大序。","zh-Hant"]]},{"id":"shiji_ch-2_p-14_s-6","passageId":"shiji_ch-2_p-14","order":6,"canonicalText":"其土黃壤。","chunks":[["其土黃壤。","zh-Hant"]]},{"id":"shiji_ch-2_p-14_s-7","passageId":"shiji_ch-2_p-14","order":7,"canonicalText":"田上上，賦中下。","chunks":[["田上上，賦中下。","zh-Hant"]]},{"id":"shiji_ch-2_p-14_s-8","passageId":"shiji_ch-2_p-14","order":8,"canonicalText":"貢璆、琳、瑯玕。","chunks":[["貢璆、琳、瑯玕。","zh-Hant"]]},{"id":"shiji_ch-2_p-14_s-9","passageId":"shiji_ch-2_p-14","order":9,"canonicalText":"浮于積石，至于龍門西河，會于渭汭。","chunks":[["浮于積石，至于龍門西河，會于渭汭。","zh-Hant"]]},{"id":"shiji_ch-2_p-14_s-10","passageId":"shiji_ch-2_p-14","order":10,"canonicalText":"織皮昆侖、析支、渠搜，西戎即序。","chunks":[["織皮昆侖、析支、渠搜，西戎即序。","zh-Hant"]]},{"id":"shiji_ch-2_p-15_s-1","passageId":"shiji_ch-2_p-15","order":1,"canonicalText":"道九山：汧及岐至于荊山，踰于河；","chunks":[["道九山：汧及岐至于荊山，踰于河；","zh-Hant"]]},{"id":"shiji_ch-2_p-15_s-2","passageId":"shiji_ch-2_p-15","order":2,"canonicalText":"壺口、雷首至于太嶽；","chunks":[["壺口、雷首至于太嶽；","zh-Hant"]]},{"id":"shiji_ch-2_p-15_s-3","passageId":"shiji_ch-2_p-15","order":3,"canonicalText":"砥柱、析城至于王屋；","chunks":[["砥柱、析城至于王屋；","zh-Hant"]]},{"id":"shiji_ch-2_p-15_s-4","passageId":"shiji_ch-2_p-15","order":4,"canonicalText":"太行、常山至于碣石，入于海；","chunks":[["太行、常山至于碣石，入于海；","zh-Hant"]]},{"id":"shiji_ch-2_p-15_s-5","passageId":"shiji_ch-2_p-15","order":5,"canonicalText":"西傾、朱圉、鳥鼠至于太華；","chunks":[["西傾、朱圉、鳥鼠至于太華；","zh-Hant"]]},{"id":"shiji_ch-2_p-15_s-6","passageId":"shiji_ch-2_p-15","order":6,"canonicalText":"熊耳、外方、桐柏至于負尾；","chunks":[["熊耳、外方、桐柏至于負尾；","zh-Hant"]]},{"id":"shiji_ch-2_p-15_s-7","passageId":"shiji_ch-2_p-15","order":7,"canonicalText":"道嶓冢，至于荊山；","chunks":[["道嶓冢，至于荊山；","zh-Hant"]]},{"id":"shiji_ch-2_p-15_s-8","passageId":"shiji_ch-2_p-15","order":8,"canonicalText":"內方至于大別；","chunks":[["內方至于大別；","zh-Hant"]]},{"id":"shiji_ch-2_p-15_s-9","passageId":"shiji_ch-2_p-15","order":9,"canonicalText":"汶山之陽至衡山，過九江，至于敷淺原。","chunks":[["汶山之陽至衡山，過九江，至于敷淺原。","zh-Hant"]]},{"id":"shiji_ch-2_p-16_s-1","passageId":"shiji_ch-2_p-16","order":1,"canonicalText":"道九川：弱水至於合黎，餘波入于流沙。","chunks":[["道九川：弱水至於合黎，餘波入于流沙。","zh-Hant"]]},{"id":"shiji_ch-2_p-16_s-2","passageId":"shiji_ch-2_p-16","order":2,"canonicalText":"道黑水，至于三危，入于南海。","chunks":[["道黑水，至于三危，入于南海。","zh-Hant"]]},{"id":"shiji_ch-2_p-16_s-3","passageId":"shiji_ch-2_p-16","order":3,"canonicalText":"道河積石，至于龍門，南至華陰，東至砥柱，又東至于盟津，東過雒汭，至于大邳，北過降水，至于大陸，北播為九河，同為逆河，入于海。","chunks":[["道河積石，至于龍門，南至華陰，東至砥柱，又東至于盟津，東過雒汭，至于大邳，北過降水，至于大陸，北播為九河，同為逆河，入于海。","zh-Hant"]]},{"id":"shiji_ch-2_p-16_s-4","passageId":"shiji_ch-2_p-16","order":4,"canonicalText":"嶓冢道瀁，東流為漢，又東為蒼浪之水，過三澨，入于大別，南入于江，東匯澤為彭蠡，東為北江，入于海。","chunks":[["嶓冢道瀁，東流為漢，又東為蒼浪之水，過三澨，入于大別，南入于江，東匯澤為彭蠡，東為北江，入于海。","zh-Hant"]]},{"id":"shiji_ch-2_p-16_s-5","passageId":"shiji_ch-2_p-16","order":5,"canonicalText":"汶山道江，東別為沱，又東至于醴，過九江，至于東陵，東迆北會于匯，東為中江，入于梅。","chunks":[["汶山道江，東別為沱，又東至于醴，過九江，至于東陵，東迆北會于匯，東為中江，入于梅。","zh-Hant"]]},{"id":"shiji_ch-2_p-16_s-6","passageId":"shiji_ch-2_p-16","order":6,"canonicalText":"道沇水，東為濟，入于河，泆為滎，東出陶丘北，又東至于荷，又東北會于汶，又東北入于海。","chunks":[["道沇水，東為濟，入于河，泆為滎，東出陶丘北，又東至于荷，又東北會于汶，又東北入于海。","zh-Hant"]]},{"id":"shiji_ch-2_p-16_s-7","passageId":"shiji_ch-2_p-16","order":7,"canonicalText":"道淮自桐柏，東會于泗、沂，東入于海。","chunks":[["道淮自桐柏，東會于泗、沂，東入于海。","zh-Hant"]]},{"id":"shiji_ch-2_p-16_s-8","passageId":"shiji_ch-2_p-16","order":8,"canonicalText":"道渭自鳥鼠同穴，東會于灃，又東北至于涇，東過漆、沮，入于河。","chunks":[["道渭自鳥鼠同穴，東會于灃，又東北至于涇，東過漆、沮，入于河。","zh-Hant"]]},{"id":"shiji_ch-2_p-16_s-9","passageId":"shiji_ch-2_p-16","order":9,"canonicalText":"道雒自熊耳，東北會于澗、瀍，又東會于伊，東北入于河。","chunks":[["道雒自熊耳，東北會于澗、瀍，又東會于伊，東北入于河。","zh-Hant"]]},{"id":"shiji_ch-2_p-17_s-1","passageId":"shiji_ch-2_p-17","order":1,"canonicalText":"於是九州攸同，四奧既居，九山刊旅，九川滌原，九澤既陂，四海會同。","chunks":[["於是九州攸同，四奧既居，九山刊旅，九川滌原，九澤既陂，四海會同。","zh-Hant"]]},{"id":"shiji_ch-2_p-17_s-2","passageId":"shiji_ch-2_p-17","order":2,"canonicalText":"六府甚修，眾土交正，致慎財賦，咸則三壤成賦。","chunks":[["六府甚修，眾土交正，致慎財賦，咸則三壤成賦。","zh-Hant"]]},{"id":"shiji_ch-2_p-17_s-3","passageId":"shiji_ch-2_p-17","order":3,"canonicalText":"中國賜土姓：「祗臺德先，不距朕行。","chunks":[["中國賜土姓：「祗臺德先，不距朕行。","zh-Hant"]]},{"id":"shiji_ch-2_p-17_s-4","passageId":"shiji_ch-2_p-17","order":4,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"shiji_ch-2_p-18_s-1","passageId":"shiji_ch-2_p-18","order":1,"canonicalText":"令天子之國以外五百里甸服：百里賦納總，二百里納銍，三百里納秸服，四百里粟，五百里米。","chunks":[["令天子之國以外五百里甸服：百里賦納總，二百里納銍，三百里納秸服，四百里粟，五百里米。","zh-Hant"]]},{"id":"shiji_ch-2_p-18_s-2","passageId":"shiji_ch-2_p-18","order":2,"canonicalText":"甸服外五百里侯服：百里采，二百里任國，三百里諸侯。","chunks":[["甸服外五百里侯服：百里采，二百里任國，三百里諸侯。","zh-Hant"]]},{"id":"shiji_ch-2_p-18_s-3","passageId":"shiji_ch-2_p-18","order":3,"canonicalText":"侯服外五百里綏服：三百里揆文教，二百里奮武衛。","chunks":[["侯服外五百里綏服：三百里揆文教，二百里奮武衛。","zh-Hant"]]},{"id":"shiji_ch-2_p-18_s-4","passageId":"shiji_ch-2_p-18","order":4,"canonicalText":"綏服外五百里要服：三百里夷，二百里蔡。","chunks":[["綏服外五百里要服：三百里夷，二百里蔡。","zh-Hant"]]},{"id":"shiji_ch-2_p-18_s-5","passageId":"shiji_ch-2_p-18","order":5,"canonicalText":"要服外五百里荒服：三百里蠻，二百里流。","chunks":[["要服外五百里荒服：三百里蠻，二百里流。","zh-Hant"]]},{"id":"shiji_ch-2_p-19_s-1","passageId":"shiji_ch-2_p-19","order":1,"canonicalText":"東漸于海，西被于流沙，朔、南暨：聲教訖于四海。","chunks":[["東漸于海，西被于流沙，朔、南暨：聲教訖于四海。","zh-Hant"]]},{"id":"shiji_ch-2_p-19_s-2","passageId":"shiji_ch-2_p-19","order":2,"canonicalText":"於是帝錫禹玄圭，以告成功于天下。","chunks":[["於是帝錫禹玄圭，以告成功于天下。","zh-Hant"]]},{"id":"shiji_ch-2_p-19_s-3","passageId":"shiji_ch-2_p-19","order":3,"canonicalText":"天下於是太平治。","chunks":[["天下於是太平治。","zh-Hant"]]},{"id":"shiji_ch-2_p-20_s-1","passageId":"shiji_ch-2_p-20","order":1,"canonicalText":"皋陶作士以理民。","chunks":[["皋陶作士以理民。","zh-Hant"]]},{"id":"shiji_ch-2_p-20_s-2","passageId":"shiji_ch-2_p-20","order":2,"canonicalText":"帝舜朝，禹、伯夷、皋陶相與語帝前。","chunks":[["帝舜朝，禹、伯夷、皋陶相與語帝前。","zh-Hant"]]},{"id":"shiji_ch-2_p-20_s-3","passageId":"shiji_ch-2_p-20","order":3,"canonicalText":"皋陶述其謀曰：「信其道德，謀明輔和。","chunks":[["皋陶述其謀曰：「信其道德，謀明輔和。","zh-Hant"]]},{"id":"shiji_ch-2_p-20_s-4","passageId":"shiji_ch-2_p-20","order":4,"canonicalText":"」禹曰：「然，如何？","chunks":[["」禹曰：「然，如何？","zh-Hant"]]},{"id":"shiji_ch-2_p-20_s-5","passageId":"shiji_ch-2_p-20","order":5,"canonicalText":"」皋陶曰：「於！","chunks":[["」皋陶曰：「於！","zh-Hant"]]},{"id":"shiji_ch-2_p-20_s-6","passageId":"shiji_ch-2_p-20","order":6,"canonicalText":"慎其身修，思長，敦序九族，眾明高翼，近可遠在已。","chunks":[["慎其身修，思長，敦序九族，眾明高翼，近可遠在已。","zh-Hant"]]},{"id":"shiji_ch-2_p-20_s-7","passageId":"shiji_ch-2_p-20","order":7,"canonicalText":"」禹拜美言，曰：「然。","chunks":[["」禹拜美言，曰：「然。","zh-Hant"]]},{"id":"shiji_ch-2_p-20_s-8","passageId":"shiji_ch-2_p-20","order":8,"canonicalText":"」皋陶曰：「於！","chunks":[["」皋陶曰：「於！","zh-Hant"]]},{"id":"shiji_ch-2_p-20_s-9","passageId":"shiji_ch-2_p-20","order":9,"canonicalText":"在知人，在安民。","chunks":[["在知人，在安民。","zh-Hant"]]},{"id":"shiji_ch-2_p-20_s-10","passageId":"shiji_ch-2_p-20","order":10,"canonicalText":"」禹曰：「吁！","chunks":[["」禹曰：「吁！","zh-Hant"]]},{"id":"shiji_ch-2_p-20_s-11","passageId":"shiji_ch-2_p-20","order":11,"canonicalText":"皆若是，惟帝其難之。","chunks":[["皆若是，惟帝其難之。","zh-Hant"]]},{"id":"shiji_ch-2_p-20_s-12","passageId":"shiji_ch-2_p-20","order":12,"canonicalText":"知人則智，能官人；","chunks":[["知人則智，能官人；","zh-Hant"]]},{"id":"shiji_ch-2_p-20_s-13","passageId":"shiji_ch-2_p-20","order":13,"canonicalText":"能安民則惠，黎民懷之。","chunks":[["能安民則惠，黎民懷之。","zh-Hant"]]},{"id":"shiji_ch-2_p-20_s-14","passageId":"shiji_ch-2_p-20","order":14,"canonicalText":"能知能惠，何憂乎驩兜，何遷乎有苗，何畏乎巧言善色佞人？","chunks":[["能知能惠，何憂乎驩兜，何遷乎有苗，何畏乎巧言善色佞人？","zh-Hant"]]},{"id":"shiji_ch-2_p-20_s-15","passageId":"shiji_ch-2_p-20","order":15,"canonicalText":"」皋陶曰：「然，於！","chunks":[["」皋陶曰：「然，於！","zh-Hant"]]},{"id":"shiji_ch-2_p-20_s-16","passageId":"shiji_ch-2_p-20","order":16,"canonicalText":"亦行有九德，亦言其有德。","chunks":[["亦行有九德，亦言其有德。","zh-Hant"]]},{"id":"shiji_ch-2_p-20_s-17","passageId":"shiji_ch-2_p-20","order":17,"canonicalText":"」乃言曰：「始事事，寬而栗，柔而立，願而共，治而敬，擾而毅，直而溫，簡而廉，剛而實，彊而義，章其有常，吉哉。","chunks":[["」乃言曰：「始事事，寬而栗，柔而立，願而共，治而敬，擾而毅，直而溫，簡而廉，剛而實，彊而義，章其有常，吉哉。","zh-Hant"]]},{"id":"shiji_ch-2_p-20_s-18","passageId":"shiji_ch-2_p-20","order":18,"canonicalText":"日宣三德，蚤夜翊明有家。","chunks":[["日宣三德，蚤夜翊明有家。","zh-Hant"]]},{"id":"shiji_ch-2_p-20_s-19","passageId":"shiji_ch-2_p-20","order":19,"canonicalText":"日嚴振敬六德，亮采有國。","chunks":[["日嚴振敬六德，亮采有國。","zh-Hant"]]},{"id":"shiji_ch-2_p-20_s-20","passageId":"shiji_ch-2_p-20","order":20,"canonicalText":"翕受普施，九德咸事，俊乂在官，百吏肅謹。","chunks":[["翕受普施，九德咸事，俊乂在官，百吏肅謹。","zh-Hant"]]},{"id":"shiji_ch-2_p-20_s-21","passageId":"shiji_ch-2_p-20","order":21,"canonicalText":"毋教邪淫奇謀。","chunks":[["毋教邪淫奇謀。","zh-Hant"]]},{"id":"shiji_ch-2_p-20_s-22","passageId":"shiji_ch-2_p-20","order":22,"canonicalText":"非其人居其官，是謂亂天事。","chunks":[["非其人居其官，是謂亂天事。","zh-Hant"]]},{"id":"shiji_ch-2_p-20_s-23","passageId":"shiji_ch-2_p-20","order":23,"canonicalText":"天討有罪，五刑五用哉。","chunks":[["天討有罪，五刑五用哉。","zh-Hant"]]},{"id":"shiji_ch-2_p-20_s-24","passageId":"shiji_ch-2_p-20","order":24,"canonicalText":"吾言厎可行乎？","chunks":[["吾言厎可行乎？","zh-Hant"]]},{"id":"shiji_ch-2_p-20_s-25","passageId":"shiji_ch-2_p-20","order":25,"canonicalText":"」禹曰：「女言致可績行。","chunks":[["」禹曰：「女言致可績行。","zh-Hant"]]},{"id":"shiji_ch-2_p-20_s-26","passageId":"shiji_ch-2_p-20","order":26,"canonicalText":"」皋陶曰：「余未有知，思贊道哉。","chunks":[["」皋陶曰：「余未有知，思贊道哉。","zh-Hant"]]},{"id":"shiji_ch-2_p-20_s-27","passageId":"shiji_ch-2_p-20","order":27,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"shiji_ch-2_p-21_s-1","passageId":"shiji_ch-2_p-21","order":1,"canonicalText":"帝舜謂禹曰：「女亦昌言。","chunks":[["帝舜謂禹曰：「女亦昌言。","zh-Hant"]]},{"id":"shiji_ch-2_p-21_s-2","passageId":"shiji_ch-2_p-21","order":2,"canonicalText":"」禹拜曰；","chunks":[["」禹拜曰；","zh-Hant"]]},{"id":"shiji_ch-2_p-21_s-3","passageId":"shiji_ch-2_p-21","order":3,"canonicalText":"「於，予何言！","chunks":[["「於，予何言！","zh-Hant"]]},{"id":"shiji_ch-2_p-21_s-4","passageId":"shiji_ch-2_p-21","order":4,"canonicalText":"予思日孳孳。","chunks":[["予思日孳孳。","zh-Hant"]]},{"id":"shiji_ch-2_p-21_s-5","passageId":"shiji_ch-2_p-21","order":5,"canonicalText":"」皋陶難禹曰：「何謂孳孳？","chunks":[["」皋陶難禹曰：「何謂孳孳？","zh-Hant"]]},{"id":"shiji_ch-2_p-21_s-6","passageId":"shiji_ch-2_p-21","order":6,"canonicalText":"」禹曰：「鴻水滔天，浩浩懷山襄陵，下民皆服於水。","chunks":[["」禹曰：「鴻水滔天，浩浩懷山襄陵，下民皆服於水。","zh-Hant"]]},{"id":"shiji_ch-2_p-21_s-7","passageId":"shiji_ch-2_p-21","order":7,"canonicalText":"予陸行乘車，水行乘舟，泥行乘橇，山行乘檋，行山刊木。","chunks":[["予陸行乘車，水行乘舟，泥行乘橇，山行乘檋，行山刊木。","zh-Hant"]]},{"id":"shiji_ch-2_p-21_s-8","passageId":"shiji_ch-2_p-21","order":8,"canonicalText":"與益予眾庶稻鮮食。","chunks":[["與益予眾庶稻鮮食。","zh-Hant"]]},{"id":"shiji_ch-2_p-21_s-9","passageId":"shiji_ch-2_p-21","order":9,"canonicalText":"以決九川致四海，浚畎澮致之川。","chunks":[["以決九川致四海，浚畎澮致之川。","zh-Hant"]]},{"id":"shiji_ch-2_p-21_s-10","passageId":"shiji_ch-2_p-21","order":10,"canonicalText":"與稷予眾庶難得之食。","chunks":[["與稷予眾庶難得之食。","zh-Hant"]]},{"id":"shiji_ch-2_p-21_s-11","passageId":"shiji_ch-2_p-21","order":11,"canonicalText":"食少，調有餘補不足，徙居。","chunks":[["食少，調有餘補不足，徙居。","zh-Hant"]]},{"id":"shiji_ch-2_p-21_s-12","passageId":"shiji_ch-2_p-21","order":12,"canonicalText":"眾民乃定，萬國為治。","chunks":[["眾民乃定，萬國為治。","zh-Hant"]]},{"id":"shiji_ch-2_p-21_s-13","passageId":"shiji_ch-2_p-21","order":13,"canonicalText":"」皋陶曰：「然，此而美也。","chunks":[["」皋陶曰：「然，此而美也。","zh-Hant"]]},{"id":"shiji_ch-2_p-21_s-14","passageId":"shiji_ch-2_p-21","order":14,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"shiji_ch-2_p-22_s-1","passageId":"shiji_ch-2_p-22","order":1,"canonicalText":"禹曰：「於，帝！","chunks":[["禹曰：「於，帝！","zh-Hant"]]},{"id":"shiji_ch-2_p-22_s-2","passageId":"shiji_ch-2_p-22","order":2,"canonicalText":"慎乃在位，安爾止。","chunks":[["慎乃在位，安爾止。","zh-Hant"]]},{"id":"shiji_ch-2_p-22_s-3","passageId":"shiji_ch-2_p-22","order":3,"canonicalText":"輔德，天下大應。","chunks":[["輔德，天下大應。","zh-Hant"]]},{"id":"shiji_ch-2_p-22_s-4","passageId":"shiji_ch-2_p-22","order":4,"canonicalText":"清意以昭待上帝命，天其重命用休。","chunks":[["清意以昭待上帝命，天其重命用休。","zh-Hant"]]},{"id":"shiji_ch-2_p-22_s-5","passageId":"shiji_ch-2_p-22","order":5,"canonicalText":"」帝曰：「吁，臣哉，臣哉！","chunks":[["」帝曰：「吁，臣哉，臣哉！","zh-Hant"]]},{"id":"shiji_ch-2_p-22_s-6","passageId":"shiji_ch-2_p-22","order":6,"canonicalText":"臣作朕股肱耳目。","chunks":[["臣作朕股肱耳目。","zh-Hant"]]},{"id":"shiji_ch-2_p-22_s-7","passageId":"shiji_ch-2_p-22","order":7,"canonicalText":"予欲左右有民，女輔之。","chunks":[["予欲左右有民，女輔之。","zh-Hant"]]},{"id":"shiji_ch-2_p-22_s-8","passageId":"shiji_ch-2_p-22","order":8,"canonicalText":"余欲觀古人之象。","chunks":[["余欲觀古人之象。","zh-Hant"]]},{"id":"shiji_ch-2_p-22_s-9","passageId":"shiji_ch-2_p-22","order":9,"canonicalText":"日月星辰，作文繡服色，女明之。","chunks":[["日月星辰，作文繡服色，女明之。","zh-Hant"]]},{"id":"shiji_ch-2_p-22_s-10","passageId":"shiji_ch-2_p-22","order":10,"canonicalText":"予欲聞六律五聲八音，來始滑，以出入五言，女聽。","chunks":[["予欲聞六律五聲八音，來始滑，以出入五言，女聽。","zh-Hant"]]},{"id":"shiji_ch-2_p-22_s-11","passageId":"shiji_ch-2_p-22","order":11,"canonicalText":"予即辟，女匡拂予。","chunks":[["予即辟，女匡拂予。","zh-Hant"]]},{"id":"shiji_ch-2_p-22_s-12","passageId":"shiji_ch-2_p-22","order":12,"canonicalText":"女無面諛。","chunks":[["女無面諛。","zh-Hant"]]},{"id":"shiji_ch-2_p-22_s-13","passageId":"shiji_ch-2_p-22","order":13,"canonicalText":"退而謗予。","chunks":[["退而謗予。","zh-Hant"]]},{"id":"shiji_ch-2_p-22_s-14","passageId":"shiji_ch-2_p-22","order":14,"canonicalText":"敬四輔臣。","chunks":[["敬四輔臣。","zh-Hant"]]},{"id":"shiji_ch-2_p-22_s-15","passageId":"shiji_ch-2_p-22","order":15,"canonicalText":"諸眾讒嬖臣，君德誠施皆清矣。","chunks":[["諸眾讒嬖臣，君德誠施皆清矣。","zh-Hant"]]},{"id":"shiji_ch-2_p-22_s-16","passageId":"shiji_ch-2_p-22","order":16,"canonicalText":"」禹曰：「然。","chunks":[["」禹曰：「然。","zh-Hant"]]},{"id":"shiji_ch-2_p-22_s-17","passageId":"shiji_ch-2_p-22","order":17,"canonicalText":"帝即不時，布同善惡則毋功。","chunks":[["帝即不時，布同善惡則毋功。","zh-Hant"]]},{"id":"shiji_ch-2_p-22_s-18","passageId":"shiji_ch-2_p-22","order":18,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"shiji_ch-2_p-23_s-1","passageId":"shiji_ch-2_p-23","order":1,"canonicalText":"帝曰：「毋若丹朱傲，維慢游是好，毋水行舟，朋淫于家，用絕其世。","chunks":[["帝曰：「毋若丹朱傲，維慢游是好，毋水行舟，朋淫于家，用絕其世。","zh-Hant"]]},{"id":"shiji_ch-2_p-23_s-2","passageId":"shiji_ch-2_p-23","order":2,"canonicalText":"予不能順是。","chunks":[["予不能順是。","zh-Hant"]]},{"id":"shiji_ch-2_p-23_s-3","passageId":"shiji_ch-2_p-23","order":3,"canonicalText":"」禹曰：「予（辛壬）娶涂山，［辛壬］癸甲，生啟予不子，以故能成水土功。","chunks":[["」禹曰：「予（辛壬）娶涂山，［辛壬］癸甲，生啟予不子，以故能成水土功。","zh-Hant"]]},{"id":"shiji_ch-2_p-23_s-4","passageId":"shiji_ch-2_p-23","order":4,"canonicalText":"輔成五服，至于五千里，州十二師，外薄四海，咸建五長，各道有功。","chunks":[["輔成五服，至于五千里，州十二師，外薄四海，咸建五長，各道有功。","zh-Hant"]]},{"id":"shiji_ch-2_p-23_s-5","passageId":"shiji_ch-2_p-23","order":5,"canonicalText":"苗頑不即功，帝其念哉。","chunks":[["苗頑不即功，帝其念哉。","zh-Hant"]]},{"id":"shiji_ch-2_p-23_s-6","passageId":"shiji_ch-2_p-23","order":6,"canonicalText":"」帝曰：「道吾德，乃女功序之也。","chunks":[["」帝曰：「道吾德，乃女功序之也。","zh-Hant"]]},{"id":"shiji_ch-2_p-23_s-7","passageId":"shiji_ch-2_p-23","order":7,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"shiji_ch-2_p-24_s-1","passageId":"shiji_ch-2_p-24","order":1,"canonicalText":"皋陶於是敬禹之德，令民皆則禹。","chunks":[["皋陶於是敬禹之德，令民皆則禹。","zh-Hant"]]},{"id":"shiji_ch-2_p-24_s-2","passageId":"shiji_ch-2_p-24","order":2,"canonicalText":"不如言，刑從之。","chunks":[["不如言，刑從之。","zh-Hant"]]},{"id":"shiji_ch-2_p-24_s-3","passageId":"shiji_ch-2_p-24","order":3,"canonicalText":"舜德大明。","chunks":[["舜德大明。","zh-Hant"]]},{"id":"shiji_ch-2_p-25_s-1","passageId":"shiji_ch-2_p-25","order":1,"canonicalText":"於是夔行樂，祖考至，群后相讓，鳥獸翔舞，簫韶九成，鳳皇來儀，百獸率舞，百官信諧。","chunks":[["於是夔行樂，祖考至，群后相讓，鳥獸翔舞，簫韶九成，鳳皇來儀，百獸率舞，百官信諧。","zh-Hant"]]},{"id":"shiji_ch-2_p-25_s-2","passageId":"shiji_ch-2_p-25","order":2,"canonicalText":"帝用此作歌曰：「陟天之命，維時維幾。","chunks":[["帝用此作歌曰：「陟天之命，維時維幾。","zh-Hant"]]},{"id":"shiji_ch-2_p-25_s-3","passageId":"shiji_ch-2_p-25","order":3,"canonicalText":"」乃歌曰：「股肱喜哉，元首起哉，百工熙哉！","chunks":[["」乃歌曰：「股肱喜哉，元首起哉，百工熙哉！","zh-Hant"]]},{"id":"shiji_ch-2_p-25_s-4","passageId":"shiji_ch-2_p-25","order":4,"canonicalText":"」皋陶拜手稽首揚言曰：「念哉，率為興事，慎乃憲，敬哉！","chunks":[["」皋陶拜手稽首揚言曰：「念哉，率為興事，慎乃憲，敬哉！","zh-Hant"]]},{"id":"shiji_ch-2_p-25_s-5","passageId":"shiji_ch-2_p-25","order":5,"canonicalText":"」乃更為歌曰：「元首明哉，股肱良哉，庶事康哉！","chunks":[["」乃更為歌曰：「元首明哉，股肱良哉，庶事康哉！","zh-Hant"]]},{"id":"shiji_ch-2_p-25_s-6","passageId":"shiji_ch-2_p-25","order":6,"canonicalText":"」（舜）又歌曰：「元首叢脞哉，股肱惰哉，萬事墮哉！","chunks":[["」（舜）又歌曰：「元首叢脞哉，股肱惰哉，萬事墮哉！","zh-Hant"]]},{"id":"shiji_ch-2_p-25_s-7","passageId":"shiji_ch-2_p-25","order":7,"canonicalText":"」帝拜曰：「然，往欽哉！","chunks":[["」帝拜曰：「然，往欽哉！","zh-Hant"]]},{"id":"shiji_ch-2_p-25_s-8","passageId":"shiji_ch-2_p-25","order":8,"canonicalText":"」於是天下皆宗禹之明度數聲樂，為山川神主。","chunks":[["」於是天下皆宗禹之明度數聲樂，為山川神主。","zh-Hant"]]},{"id":"shiji_ch-2_p-26_s-1","passageId":"shiji_ch-2_p-26","order":1,"canonicalText":"帝舜薦禹於天，為嗣。","chunks":[["帝舜薦禹於天，為嗣。","zh-Hant"]]},{"id":"shiji_ch-2_p-26_s-2","passageId":"shiji_ch-2_p-26","order":2,"canonicalText":"十七年而帝舜崩。","chunks":[["十七年而帝舜崩。","zh-Hant"]]},{"id":"shiji_ch-2_p-26_s-3","passageId":"shiji_ch-2_p-26","order":3,"canonicalText":"三年喪畢，禹辭辟舜之子商均於陽城。","chunks":[["三年喪畢，禹辭辟舜之子商均於陽城。","zh-Hant"]]},{"id":"shiji_ch-2_p-26_s-4","passageId":"shiji_ch-2_p-26","order":4,"canonicalText":"天下諸侯皆去商均而朝禹。","chunks":[["天下諸侯皆去商均而朝禹。","zh-Hant"]]},{"id":"shiji_ch-2_p-26_s-5","passageId":"shiji_ch-2_p-26","order":5,"canonicalText":"禹於是遂即天子位，南面朝天下，國號曰夏后，姓姒氏。","chunks":[["禹於是遂即天子位，南面朝天下，國號曰夏后，姓姒氏。","zh-Hant"]]},{"id":"shiji_ch-2_p-27_s-1","passageId":"shiji_ch-2_p-27","order":1,"canonicalText":"帝禹立而舉皋陶薦之，且授政焉，而皋陶卒。","chunks":[["帝禹立而舉皋陶薦之，且授政焉，而皋陶卒。","zh-Hant"]]},{"id":"shiji_ch-2_p-27_s-2","passageId":"shiji_ch-2_p-27","order":2,"canonicalText":"封皋陶之後於英、六，或在許。","chunks":[["封皋陶之後於英、六，或在許。","zh-Hant"]]},{"id":"shiji_ch-2_p-27_s-3","passageId":"shiji_ch-2_p-27","order":3,"canonicalText":"而后舉益，任之政。","chunks":[["而后舉益，任之政。","zh-Hant"]]},{"id":"shiji_ch-2_p-28_s-1","passageId":"shiji_ch-2_p-28","order":1,"canonicalText":"十年，帝禹東巡狩，至于會稽而崩。","chunks":[["十年，帝禹東巡狩，至于會稽而崩。","zh-Hant"]]},{"id":"shiji_ch-2_p-28_s-2","passageId":"shiji_ch-2_p-28","order":2,"canonicalText":"以天下授益。","chunks":[["以天下授益。","zh-Hant"]]},{"id":"shiji_ch-2_p-28_s-3","passageId":"shiji_ch-2_p-28","order":3,"canonicalText":"三年之喪畢，益讓帝禹之子啟，而辟居箕山之陽。","chunks":[["三年之喪畢，益讓帝禹之子啟，而辟居箕山之陽。","zh-Hant"]]},{"id":"shiji_ch-2_p-28_s-4","passageId":"shiji_ch-2_p-28","order":4,"canonicalText":"禹子啟賢，天下屬意焉。","chunks":[["禹子啟賢，天下屬意焉。","zh-Hant"]]},{"id":"shiji_ch-2_p-28_s-5","passageId":"shiji_ch-2_p-28","order":5,"canonicalText":"及禹崩，雖授益，益之佐禹日淺，天下未洽。","chunks":[["及禹崩，雖授益，益之佐禹日淺，天下未洽。","zh-Hant"]]},{"id":"shiji_ch-2_p-28_s-6","passageId":"shiji_ch-2_p-28","order":6,"canonicalText":"故諸侯皆去益而朝啟，曰：「吾君帝禹之子也」。","chunks":[["故諸侯皆去益而朝啟，曰：「吾君帝禹之子也」。","zh-Hant"]]},{"id":"shiji_ch-2_p-28_s-7","passageId":"shiji_ch-2_p-28","order":7,"canonicalText":"於是啟遂即天子之位，是為夏后帝啟。","chunks":[["於是啟遂即天子之位，是為夏后帝啟。","zh-Hant"]]},{"id":"shiji_ch-2_p-29_s-1","passageId":"shiji_ch-2_p-29","order":1,"canonicalText":"夏后帝啟，禹之子，其母涂山氏之女也。","chunks":[["夏后帝啟，禹之子，其母涂山氏之女也。","zh-Hant"]]},{"id":"shiji_ch-2_p-30_s-1","passageId":"shiji_ch-2_p-30","order":1,"canonicalText":"有扈氏不服，啟伐之，大戰於甘。","chunks":[["有扈氏不服，啟伐之，大戰於甘。","zh-Hant"]]},{"id":"shiji_ch-2_p-30_s-2","passageId":"shiji_ch-2_p-30","order":2,"canonicalText":"將戰，作甘誓，乃召六卿申之。","chunks":[["將戰，作甘誓，乃召六卿申之。","zh-Hant"]]},{"id":"shiji_ch-2_p-30_s-3","passageId":"shiji_ch-2_p-30","order":3,"canonicalText":"啟曰：「嗟！","chunks":[["啟曰：「嗟！","zh-Hant"]]},{"id":"shiji_ch-2_p-30_s-4","passageId":"shiji_ch-2_p-30","order":4,"canonicalText":"六事之人，予誓告女：有扈氏威侮五行，怠棄三正，天用勦絕其命。","chunks":[["六事之人，予誓告女：有扈氏威侮五行，怠棄三正，天用勦絕其命。","zh-Hant"]]},{"id":"shiji_ch-2_p-30_s-5","passageId":"shiji_ch-2_p-30","order":5,"canonicalText":"今予維共行天之罰。","chunks":[["今予維共行天之罰。","zh-Hant"]]},{"id":"shiji_ch-2_p-30_s-6","passageId":"shiji_ch-2_p-30","order":6,"canonicalText":"左不攻于左，右不攻于右，女不共命。","chunks":[["左不攻于左，右不攻于右，女不共命。","zh-Hant"]]},{"id":"shiji_ch-2_p-30_s-7","passageId":"shiji_ch-2_p-30","order":7,"canonicalText":"御非其馬之政，女不共命。","chunks":[["御非其馬之政，女不共命。","zh-Hant"]]},{"id":"shiji_ch-2_p-30_s-8","passageId":"shiji_ch-2_p-30","order":8,"canonicalText":"用命，賞于祖；","chunks":[["用命，賞于祖；","zh-Hant"]]},{"id":"shiji_ch-2_p-30_s-9","passageId":"shiji_ch-2_p-30","order":9,"canonicalText":"不用命，僇于社，予則帑僇女。","chunks":[["不用命，僇于社，予則帑僇女。","zh-Hant"]]},{"id":"shiji_ch-2_p-30_s-10","passageId":"shiji_ch-2_p-30","order":10,"canonicalText":"」遂滅有扈氏。","chunks":[["」遂滅有扈氏。","zh-Hant"]]},{"id":"shiji_ch-2_p-30_s-11","passageId":"shiji_ch-2_p-30","order":11,"canonicalText":"天下咸朝。","chunks":[["天下咸朝。","zh-Hant"]]},{"id":"shiji_ch-2_p-31_s-1","passageId":"shiji_ch-2_p-31","order":1,"canonicalText":"夏后帝啟崩，子帝太康立。","chunks":[["夏后帝啟崩，子帝太康立。","zh-Hant"]]},{"id":"shiji_ch-2_p-31_s-2","passageId":"shiji_ch-2_p-31","order":2,"canonicalText":"帝太康失國，昆弟五人，須于洛汭，作五子之歌。","chunks":[["帝太康失國，昆弟五人，須于洛汭，作五子之歌。","zh-Hant"]]},{"id":"shiji_ch-2_p-32_s-1","passageId":"shiji_ch-2_p-32","order":1,"canonicalText":"太康崩，弟中康立，是為帝中康。","chunks":[["太康崩，弟中康立，是為帝中康。","zh-Hant"]]},{"id":"shiji_ch-2_p-32_s-2","passageId":"shiji_ch-2_p-32","order":2,"canonicalText":"帝中康時，羲、和湎淫，廢時亂日。","chunks":[["帝中康時，羲、和湎淫，廢時亂日。","zh-Hant"]]},{"id":"shiji_ch-2_p-32_s-3","passageId":"shiji_ch-2_p-32","order":3,"canonicalText":"胤往征之，作胤征。","chunks":[["胤往征之，作胤征。","zh-Hant"]]},{"id":"shiji_ch-2_p-33_s-1","passageId":"shiji_ch-2_p-33","order":1,"canonicalText":"中康崩，子帝相立。","chunks":[["中康崩，子帝相立。","zh-Hant"]]},{"id":"shiji_ch-2_p-33_s-2","passageId":"shiji_ch-2_p-33","order":2,"canonicalText":"帝相崩，子帝少康立。","chunks":[["帝相崩，子帝少康立。","zh-Hant"]]},{"id":"shiji_ch-2_p-33_s-3","passageId":"shiji_ch-2_p-33","order":3,"canonicalText":"帝少康崩，子帝予立。","chunks":[["帝少康崩，子帝予立。","zh-Hant"]]},{"id":"shiji_ch-2_p-33_s-4","passageId":"shiji_ch-2_p-33","order":4,"canonicalText":"帝予崩，子帝槐立。","chunks":[["帝予崩，子帝槐立。","zh-Hant"]]},{"id":"shiji_ch-2_p-33_s-5","passageId":"shiji_ch-2_p-33","order":5,"canonicalText":"帝槐崩，子帝芒立。","chunks":[["帝槐崩，子帝芒立。","zh-Hant"]]},{"id":"shiji_ch-2_p-33_s-6","passageId":"shiji_ch-2_p-33","order":6,"canonicalText":"帝芒崩，子帝泄立。","chunks":[["帝芒崩，子帝泄立。","zh-Hant"]]},{"id":"shiji_ch-2_p-33_s-7","passageId":"shiji_ch-2_p-33","order":7,"canonicalText":"帝泄崩，子帝不降立。","chunks":[["帝泄崩，子帝不降立。","zh-Hant"]]},{"id":"shiji_ch-2_p-33_s-8","passageId":"shiji_ch-2_p-33","order":8,"canonicalText":"帝不降崩，弟帝扃立。","chunks":[["帝不降崩，弟帝扃立。","zh-Hant"]]},{"id":"shiji_ch-2_p-33_s-9","passageId":"shiji_ch-2_p-33","order":9,"canonicalText":"帝扃崩，子帝廑立。","chunks":[["帝扃崩，子帝廑立。","zh-Hant"]]},{"id":"shiji_ch-2_p-33_s-10","passageId":"shiji_ch-2_p-33","order":10,"canonicalText":"帝廑崩，立帝不降之子孔甲，是為帝孔甲。","chunks":[["帝廑崩，立帝不降之子孔甲，是為帝孔甲。","zh-Hant"]]},{"id":"shiji_ch-2_p-33_s-11","passageId":"shiji_ch-2_p-33","order":11,"canonicalText":"帝孔甲立，好方鬼神，事淫亂。","chunks":[["帝孔甲立，好方鬼神，事淫亂。","zh-Hant"]]},{"id":"shiji_ch-2_p-33_s-12","passageId":"shiji_ch-2_p-33","order":12,"canonicalText":"夏后氏德衰，諸侯畔之。","chunks":[["夏后氏德衰，諸侯畔之。","zh-Hant"]]},{"id":"shiji_ch-2_p-33_s-13","passageId":"shiji_ch-2_p-33","order":13,"canonicalText":"天降龍二，有雌雄，孔甲不能食，未得豢龍氏。","chunks":[["天降龍二，有雌雄，孔甲不能食，未得豢龍氏。","zh-Hant"]]},{"id":"shiji_ch-2_p-33_s-14","passageId":"shiji_ch-2_p-33","order":14,"canonicalText":"陶唐既衰，其后有劉累，學擾龍于豢龍氏，以事孔甲。","chunks":[["陶唐既衰，其后有劉累，學擾龍于豢龍氏，以事孔甲。","zh-Hant"]]},{"id":"shiji_ch-2_p-33_s-15","passageId":"shiji_ch-2_p-33","order":15,"canonicalText":"孔甲賜之姓曰御龍氏，受豕韋之後。","chunks":[["孔甲賜之姓曰御龍氏，受豕韋之後。","zh-Hant"]]},{"id":"shiji_ch-2_p-33_s-16","passageId":"shiji_ch-2_p-33","order":16,"canonicalText":"龍一雌死，以食夏后。","chunks":[["龍一雌死，以食夏后。","zh-Hant"]]},{"id":"shiji_ch-2_p-33_s-17","passageId":"shiji_ch-2_p-33","order":17,"canonicalText":"夏后使求，懼而遷去。","chunks":[["夏后使求，懼而遷去。","zh-Hant"]]},{"id":"shiji_ch-2_p-34_s-1","passageId":"shiji_ch-2_p-34","order":1,"canonicalText":"孔甲崩，子帝皋立。","chunks":[["孔甲崩，子帝皋立。","zh-Hant"]]},{"id":"shiji_ch-2_p-34_s-2","passageId":"shiji_ch-2_p-34","order":2,"canonicalText":"帝皋崩，子帝發立。","chunks":[["帝皋崩，子帝發立。","zh-Hant"]]},{"id":"shiji_ch-2_p-34_s-3","passageId":"shiji_ch-2_p-34","order":3,"canonicalText":"帝發崩，子帝履癸立，是為桀。","chunks":[["帝發崩，子帝履癸立，是為桀。","zh-Hant"]]},{"id":"shiji_ch-2_p-34_s-4","passageId":"shiji_ch-2_p-34","order":4,"canonicalText":"帝桀之時，自孔甲以來而諸侯多畔夏，桀不務德而武傷百姓，百姓弗堪。","chunks":[["帝桀之時，自孔甲以來而諸侯多畔夏，桀不務德而武傷百姓，百姓弗堪。","zh-Hant"]]},{"id":"shiji_ch-2_p-34_s-5","passageId":"shiji_ch-2_p-34","order":5,"canonicalText":"乃召湯而囚之夏臺，已而釋之。","chunks":[["乃召湯而囚之夏臺，已而釋之。","zh-Hant"]]},{"id":"shiji_ch-2_p-34_s-6","passageId":"shiji_ch-2_p-34","order":6,"canonicalText":"湯修德，諸侯皆歸湯，湯遂率兵以伐夏桀。","chunks":[["湯修德，諸侯皆歸湯，湯遂率兵以伐夏桀。","zh-Hant"]]},{"id":"shiji_ch-2_p-34_s-7","passageId":"shiji_ch-2_p-34","order":7,"canonicalText":"桀走鳴條，遂放而死。","chunks":[["桀走鳴條，遂放而死。","zh-Hant"]]},{"id":"shiji_ch-2_p-34_s-8","passageId":"shiji_ch-2_p-34","order":8,"canonicalText":"桀謂人曰：「吾悔不遂殺湯於夏臺，使至此。","chunks":[["桀謂人曰：「吾悔不遂殺湯於夏臺，使至此。","zh-Hant"]]},{"id":"shiji_ch-2_p-34_s-9","passageId":"shiji_ch-2_p-34","order":9,"canonicalText":"」湯乃踐天子位，代夏朝天下。","chunks":[["」湯乃踐天子位，代夏朝天下。","zh-Hant"]]},{"id":"shiji_ch-2_p-34_s-10","passageId":"shiji_ch-2_p-34","order":10,"canonicalText":"湯封夏之後，至周封於杞也。","chunks":[["湯封夏之後，至周封於杞也。","zh-Hant"]]},{"id":"shiji_ch-2_p-35_s-1","passageId":"shiji_ch-2_p-35","order":1,"canonicalText":"太史公曰：禹為姒姓，其後分封，用國為姓，故有夏后氏、有扈氏、有男氏、斟尋氏、彤城氏、褒氏、費氏、杞氏、繒氏、辛氏、冥氏、斟（氏）戈氏。","chunks":[["太史公曰：禹為姒姓，其後分封，用國為姓，故有夏后氏、有扈氏、有男氏、斟尋氏、彤城氏、褒氏、費氏、杞氏、繒氏、辛氏、冥氏、斟（氏）戈氏。","zh-Hant"]]},{"id":"shiji_ch-2_p-35_s-2","passageId":"shiji_ch-2_p-35","order":2,"canonicalText":"孔子正夏時，學者多傳夏小正云。","chunks":[["孔子正夏時，學者多傳夏小正云。","zh-Hant"]]},{"id":"shiji_ch-2_p-35_s-3","passageId":"shiji_ch-2_p-35","order":3,"canonicalText":"自虞、夏時，貢賦備矣。","chunks":[["自虞、夏時，貢賦備矣。","zh-Hant"]]},{"id":"shiji_ch-2_p-35_s-4","passageId":"shiji_ch-2_p-35","order":4,"canonicalText":"或言禹會諸侯江南，計功而崩，因葬焉，命曰會稽。","chunks":[["或言禹會諸侯江南，計功而崩，因葬焉，命曰會稽。","zh-Hant"]]},{"id":"shiji_ch-2_p-35_s-5","passageId":"shiji_ch-2_p-35","order":5,"canonicalText":"會稽者，會計也。","chunks":[["會稽者，會計也。","zh-Hant"]]}]}') as WorkBundle
